  private int decodeRunLength(final DecodeState state, final InputStream in,
      final byte[] ll8, final int[] unzftab, final byte[] seqToUnseq,
      final char[] yy, final int limitLast, int lastShadow)
      throws IOException {
    int s = -1;

    for (int n = 1; true; n <<= 1) {
      if (state.nextSym == RUNA) {
        s += n;
      } else if (state.nextSym == RUNB) {
        s += n << 1;
      } else {
        break;
      }

      state.nextSym = decodeNextSymbol(state, in);
    }

    final byte ch = seqToUnseq[yy[0]];
    unzftab[ch & 0xff] += s + 1;

    while (s-- >= 0) {
      ll8[++lastShadow] = ch;
    }

    if (lastShadow >= limitLast) {
      throw new IOException("block overrun");
    }

    return lastShadow;
