      final byte[] ll8, final int[] unzftab, final byte[] seqToUnseq,
      final char[] yy, final int limitLast, int lastShadow)
      throws IOException {
    if (++lastShadow >= limitLast) {
      throw new IOException("block overrun");
    }

    final char tmp = yy[state.nextSym - 1];
    unzftab[seqToUnseq[tmp] & 0xff]++;
