private int decodeRunLength(DecodeState state, InputStream in, byte[] ll8, int[] unzftab, byte[] seqToUnseq, char[] yy, int limitLast, int lastShadow) throws IOException {
    int s = -1;
    for (int n = 1; true; n <<= 1) {
