/**
 * Receives the 16-bit bitmap that indicates which 16-symbol ranges are used.
 */
private int receiveInUseBitmap() throws IOException {
    int inUse16 = 0;
    for (int i = 0; i < 16; i++) {
      if (bsGetBit()) {
        inUse16 |= 1 << i;
      }
    }
    return inUse16;
  }

private void clearInUse(final boolean[] inUse) {
    for (int i = 256; --i >= 0;) {
      inUse[i] = false;
    }
  }

/**
 * Receives the per-symbol in-use flags for the ranges marked in the bitmap.
 */
private void receiveInUseSymbols(final boolean[] inUse, final int inUse16)
      throws IOException {
    for (int i = 0; i < 16; i++) {
      if ((inUse16 & (1 << i)) != 0) {
        final int i16 = i << 4;
        for (int j = 0; j < 16; j++) {
          if (bsGetBit()) {
            inUse[i16 + j] = true;
          }
        }
      }
    }
  }

private void receiveSelectors(final byte[] selectorMtf, final int nSelectors)
      throws IOException {
    for (int i = 0; i < nSelectors; i++) {
      int j = 0;
      while (bsGetBit()) {
        j++;
      }
      selectorMtf[i] = (byte) j;
    }
  }

/**
 * Undoes the move-to-front transform applied to the selectors.
 */
private void undoSelectorMtf(final byte[] selector, final byte[] selectorMtf,
      final byte[] pos, final int nGroups, final int nSelectors) {
    for (int v = nGroups; --v >= 0;) {
      pos[v] = (byte) v;
    }

    for (int i = 0; i < nSelectors; i++) {
      int v = selectorMtf[i] & 0xff;
      final byte tmp = pos[v];
      while (v > 0) {
        pos[v] = pos[v - 1];
        v--;
      }
      pos[0] = tmp;
      selector[i] = tmp;
    }
  }

private void receiveCodingTables(final char[][] len, final int nGroups,
      final int alphaSize) throws IOException {
    for (int t = 0; t < nGroups; t++) {
      int curr = (int) bsR(5);
      final char[] len_t = len[t];
      for (int i = 0; i < alphaSize; i++) {
        while (bsGetBit()) {
          curr += bsGetBit() ? -1 : 1;
        }
        len_t[i] = (char) curr;
      }
    }
  }

