/**
 * Decodes the next symbol from the bit stream, updating the group and
 * bit-stream state as a side effect.
 */
private int decodeNextSymbol(final DecodeState state, final InputStream in)
      throws IOException {
    if (state.groupPos == 0) {
      state.groupPos = G_SIZE - 1;
      state.groupNo++;
      state.zt = state.selector[state.groupNo] & 0xff;
      state.base = state.baseTables[state.zt];
      state.limit = state.limitTables[state.zt];
      state.perm = state.permTables[state.zt];
      state.minLens = state.minLensTable[state.zt];
    } else {
      state.groupPos--;
    }

    int zn = state.minLens;
    int bsBuffShadow = state.bsBuff;
    int bsLiveShadow = state.bsLive;

    while (bsLiveShadow < zn) {
      final int thech = readAByte(in);
      if (thech >= 0) {
        bsBuffShadow = (bsBuffShadow << 8) | thech;
        bsLiveShadow += 8;
        continue;
      }
      throw new IOException("unexpected end of stream");
    }
    int zvec = (bsBuffShadow >> (bsLiveShadow - zn)) & ((1 << zn) - 1);
    bsLiveShadow -= zn;

    while (zvec > state.limit[zn]) {
      zn++;
      while (bsLiveShadow < 1) {
        final int thech = readAByte(in);
        if (thech >= 0) {
          bsBuffShadow = (bsBuffShadow << 8) | thech;
          bsLiveShadow += 8;
          continue;
        }
        throw new IOException("unexpected end of stream");
      }
      bsLiveShadow--;
      zvec = (zvec << 1) | ((bsBuffShadow >> bsLiveShadow) & 1);
    }

    state.bsBuff = bsBuffShadow;
    state.bsLive = bsLiveShadow;

    return state.perm[zvec - state.base[zn]];
  }

decodeRunLength:

/**
 * Decodes a run-length sequence of RUNA/RUNB symbols and writes the
 * repeated byte into the output buffer.
 */
private int decodeRunLength(final DecodeState state, final InputStream in,
      final byte[] ll8, final int[] unzftab, final byte[] seqToUnseq,
      final char[] yy, final int limitLast, int lastShadow)
      throws IOException {
    int s = -1;

    for (int n = 1; true; n <<= 1) {
      if (state.nextSym == RUNA) {
        s += n;
      } else if (state.nextSym == RUNB) {
        s += n << 1;
      } else {
        break;
      }

      state.nextSym = decodeNextSymbol(state, in);
    }

    final byte ch = seqToUnseq[yy[0]];
    unzftab[ch & 0xff] += s + 1;

    while (s-- >= 0) {
      ll8[++lastShadow] = ch;
    }

    if (lastShadow >= limitLast) {
      throw new IOException("block overrun");
    }

    return lastShadow;
  }

decodeLiteral:

/**
 * Decodes a single literal symbol, updates the move-to-front list, and
 * reads the following symbol from the bit stream.
 */
private int decodeLiteral(final DecodeState state, final InputStream in,
      final byte[] ll8, final int[] unzftab, final byte[] seqToUnseq,
      final char[] yy, final int limitLast, int lastShadow)
      throws IOException {
    if (++lastShadow >= limitLast) {
      throw new IOException("block overrun");
    }

    final char tmp = yy[state.nextSym - 1];
    unzftab[seqToUnseq[tmp] & 0xff]++;
    ll8[lastShadow] = seqToUnseq[tmp];

    if (state.nextSym <= 16) {
      for (int j = state.nextSym - 1; j > 0;) {
        yy[j] = yy[--j];
      }
    } else {
      System.arraycopy(yy, 0, yy, 1, state.nextSym - 1);
    }

    yy[0] = tmp;

    state.nextSym = decodeNextSymbol(state, in);

    return lastShadow;
  }

