/** Receives the 16-bit in-use summary. */
private int receiveInUse16() throws IOException {
  int inUse16 = 0;
  for (int i = 0; i < 16; i++) {
    if (bsGetBit()) {
      inUse16 |= 1 << i;
    }
  }
  return inUse16;
}

/** Clears the in-use array before receiving per-bit flags. */
private void clearInUse(boolean[] inUse) {
  for (int i = 256; --i >= 0;) {
    inUse[i] = false;
  }
}

/** Applies the per-bit in-use flags for groups marked in the summary. */
private void applyInUseBits(boolean[] inUse, int inUse16) throws IOException {
  for (int i = 0; i < 16; i++) {
    if ((inUse16 & (1 << i)) != 0) {
      final int i16 = i << 4;
      for (int j = 0; j < 16; j++) {
        if (bsGetBit()) {
          inUse[i16 + j] = true;
        }
      }
    }
  }
}

/** Receives the MTF-encoded selector values. */
private void receiveSelectorMtfValues(int nSelectors, byte[] selectorMtf) throws IOException {
  for (int i = 0; i < nSelectors; i++) {
    int j = 0;
    while (bsGetBit()) {
      j++;
    }
    selectorMtf[i] = (byte) j;
