/** Ensures that at least {@code n} bits are available in the bit buffer. */
private void fillBits(InputStream in, BitBuffer bits, int n) throws IOException {
  while (bits.live < n) {
    final int thech = readAByte(in);
    if (thech < 0) {
      throw new IOException("unexpected end of stream");
    }
    bits.buff = (bits.buff << 8) | thech;
    bits.live += 8;
  }
}

/** Reads and returns the next decoded symbol for the current group. */
private int readNextSymbol(InputStream in, GroupContext group, BitBuffer bits) throws IOException {
  int zn = group.minLens;
  fillBits(in, bits, zn);
  int zvec = (bits.buff >> (bits.live - zn)) & ((1 << zn) - 1);
  bits.live -= zn;

  while (zvec > group.limit[zn]) {
    zn++;
    fillBits(in, bits, 1);
    bits.live--;
    zvec = (zvec << 1) | ((bits.buff >> bits.live) & 1);
  }

  return group.perm[zvec - group.base[zn]];
}

/** Advances to the next selector group, cycling every {@code G_SIZE} symbols. */
private void advanceGroup(GroupContext group, byte[] selector, int[][] base,
    int[][] limit, int[][] perm, int[] minLens) {
  if (group.groupPos == 0) {
    group.groupPos = G_SIZE - 1;
    group.groupNo++;
    group.zt = selector[group.groupNo] & 0xff;
    group.base = base[group.zt];
    group.limit = limit[group.zt];
    group.perm = perm[group.zt];
    group.minLens = minLens[group.zt];
  } else {
    group.groupPos--;
  }
}

/** Initializes the move-to-front list and frequency table. */
private void initMoveToFrontTables(char[] yy, int[] unzftab) {
  for (int i = 256; --i >= 0;) {
    yy[i] = (char) i;
    unzftab[i] = 0;
  }
}

/** Returns true if the symbol is a run-length marker. */
private boolean isRunSymbol(int sym) {
  return sym == RUNA || sym == RUNB;
}

/** Accumulates one run-length step and returns the updated run length. */
private int accumulateRunLength(int nextSym, int runLength, int n) {
  if (nextSym == RUNA) {
    return runLength + n;
  }
  // nextSym == RUNB
  return runLength + (n << 1);
}

/** Writes {@code count}+1 copies of {@code ch} into the decoded buffer. */
private int writeRunBytes(byte[] ll8, int lastShadow, byte ch, int count, int limitLast)
    throws IOException {
  while (count-- >= 0) {
    ll8[++lastShadow] = ch;
  }
  if (lastShadow >= limitLast) {
    throw new IOException("block overrun");
  }
  return lastShadow;
}

/** Decodes a single literal symbol, updates the move-to-front list and returns the new last index. */
private int decodeLiteralSymbol(int nextSym, char[] yy, byte[] seqToUnseq,
    int[] unzftab, byte[] ll8, int lastShadow, int limitLast) throws IOException {
  if (++lastShadow >= limitLast) {
    throw new IOException("block overrun");
  }

  final char tmp = yy[nextSym - 1];
  unzftab[seqToUnseq[tmp] & 0xff]++;
  ll8[lastShadow] = seqToUnseq[tmp];

  if (nextSym <= 16) {
    for (int j = nextSym - 1; j > 0;) {
      yy[j] = yy[--j];
    }
  } else {
    System.arraycopy(yy, 0, yy, 1, nextSym - 1);
  }

  yy[0] = tmp;

  return lastShadow;
}

