      reportCRCError();
    }

    this.computedCombinedCRC = (this.computedCombinedCRC << 1)
        | (this.computedCombinedCRC >>> 31);
    this.computedCombinedCRC ^= this.computedBlockCRC;
  }

  private void complete() throws IOException {
    this.storedCombinedCRC = bsGetInt();
    this.currentState = STATE.EOF;
    this.data = null;

    if (this.storedCombinedCRC != this.computedCombinedCRC) {
      reportCRCError();
    }
  }

  @Override
  public void close() throws IOException {
    InputStream inShadow = this.in;
    if (inShadow != null) {
      try {
        if (inShadow != System.in) {
          inShadow.close();
        }
      } finally {
        this.data = null;
        this.in = null;
      }
    }
  }

  private long bsR(final long n) throws IOException {
    long bsLiveShadow = this.bsLive;
    long bsBuffShadow = this.bsBuff;

    if (bsLiveShadow < n) {
      final InputStream inShadow = this.in;
      do {
        int thech = readAByte(inShadow);

        if (thech < 0) {
          throw new IOException("unexpected end of stream");
        }

        bsBuffShadow = (bsBuffShadow << 8) | thech;
        bsLiveShadow += 8;
      } while (bsLiveShadow < n);

      this.bsBuff = bsBuffShadow;
    }

    this.bsLive = bsLiveShadow - n;
    return (bsBuffShadow >> (bsLiveShadow - n)) & ((1L << n) - 1);
  }

  private boolean bsGetBit() throws IOException {
    long bsLiveShadow = this.bsLive;
    long bsBuffShadow = this.bsBuff;

    if (bsLiveShadow < 1) {
      int thech = this.readAByte(in);

      if (thech < 0) {
        throw new IOException("unexpected end of stream");
      }

      bsBuffShadow = (bsBuffShadow << 8) | thech;
      bsLiveShadow += 8;
      this.bsBuff = bsBuffShadow;
    }

    this.bsLive = bsLiveShadow - 1;
    return ((bsBuffShadow >> (bsLiveShadow - 1)) & 1) != 0;
  }

  private char bsGetUByte() throws IOException {
    return (char) bsR(8);
  }

  private int bsGetInt() throws IOException {
    return (int) ((((((bsR(8) << 8) | bsR(8)) << 8) | bsR(8)) << 8) | bsR(8));
  }

  /**
  * Called by createHuffmanDecodingTables() exclusively.
  */
  private static void hbCreateDecodeTables(final int[] limit,
      final int[] base, final int[] perm, final char[] length,
      final int minLen, final int maxLen, final int alphaSize) {
    for (int i = minLen, pp = 0; i <= maxLen; i++) {
      for (int j = 0; j < alphaSize; j++) {
        if (length[j] == i) {
          perm[pp++] = j;
        }
      }
    }

    for (int i = MAX_CODE_LEN; --i > 0;) {
      base[i] = 0;
      limit[i] = 0;
    }

    for (int i = 0; i < alphaSize; i++) {
      base[length[i] + 1]++;
    }

    for (int i = 1, b = base[0]; i < MAX_CODE_LEN; i++) {
      b += base[i];
      base[i] = b;
    }

    for (int i = minLen, vec = 0, b = base[i]; i <= maxLen; i++) {
      final int nb = base[i + 1];
      vec += nb - b;
      b = nb;
      limit[i] = vec - 1;
      vec <<= 1;
    }

    for (int i = minLen + 1; i <= maxLen; i++) {
      base[i] = ((limit[i - 1] + 1) << 1) - base[i];
    }
  }

  private void recvDecodingTables() throws IOException {
    final Data dataShadow = this.data;
    final boolean[] inUse = dataShadow.inUse;

    final int inUse16 = receiveInUse16();
    clearInUse(inUse);
    receiveInUseBitmap(inUse16, inUse);

    makeMaps();
    final int alphaSize = this.nInUse + 2;

    final int nGroups = (int) bsR(3);
    final int nSelectors = (int) bsR(15);

    receiveSelectors(nSelectors, dataShadow.selectorMtf);
    undoMtfForSelectors(nGroups, nSelectors, dataShadow.recvDecodingTables_pos,
        dataShadow.selector, dataShadow.selectorMtf);

    receiveCodingTables(nGroups, alphaSize, dataShadow.temp_charArray2d);

    createHuffmanDecodingTables(alphaSize, nGroups);
  }

  /**
   * Receives the 16-bit bitmap that describes which groups of 16 symbols are used.
   *
   * @return the bitmap as an int
   * @throws IOException if an I/O error occurs
   */
  private int receiveInUse16() throws IOException {
    int inUse16 = 0;
    for (int i = 0; i < 16; i++) {
      if (bsGetBit()) {
        inUse16 |= 1 << i;
      }
    }
    return inUse16;
  }

  /**
   * Clears the in-use symbol table.
   *
   * @param inUse the table to clear
   */
  private void clearInUse(final boolean[] inUse) {
    for (int i = 256; --i >= 0;) {
      inUse[i] = false;
    }
  }

  /**
   * Receives the per-symbol in-use flags based on the group bitmap.
   *
   * @param inUse16 the group bitmap
   * @param inUse the per-symbol table to populate
   * @throws IOException if an I/O error occurs
   */
  private void receiveInUseBitmap(final int inUse16, final boolean[] inUse)
      throws IOException {
    for (int i = 0; i < 16; i++) {
      if (!isBitSet(inUse16, i)) {
        continue;
      }
      receiveInUseGroup(i, inUse);
    }
  }

  /**
   * Returns true if the given bit is set in value.
   *
   * @param value the value to test
   * @param bit the bit index
   * @return true if the bit is set
   */
  private static boolean isBitSet(final int value, final int bit) {
    return (value & (1 << bit)) != 0;
  }

  /**
   * Receives the in-use flags for one group of 16 symbols.
   *
   * @param group the group index
   * @param inUse the per-symbol table to populate
   * @throws IOException if an I/O error occurs
   */
  private void receiveInUseGroup(final int group, final boolean[] inUse)
      throws IOException {
    final int base = group << 4;
    for (int j = 0; j < 16; j++) {
      if (bsGetBit()) {
        inUse[base + j] = true;
      }
    }
  }

  /**
   * Receives the MTF-encoded selector values.
   *
   * @param nSelectors the number of selectors
   * @param selectorMtf the array to populate
   * @throws IOException if an I/O error occurs
   */
  private void receiveSelectors(final int nSelectors, final byte[] selectorMtf)
      throws IOException {
    for (int i = 0; i < nSelectors; i++) {
      selectorMtf[i] = (byte) countConsecutiveTrueBits();
    }
  }

  /**
   * Counts consecutive true bits read from the stream.
   *
   * @return the count of consecutive true bits
   * @throws IOException if an I/O error occurs
   */
  private int countConsecutiveTrueBits() throws IOException {
    int count = 0;
    while (bsGetBit()) {
      count++;
    }
    return count;
  }

  /**
   * Undoes the MTF transform for the selectors.
   *
   * @param nGroups the number of groups
   * @param nSelectors the number of selectors
   * @param pos the MTF position array
   * @param selector the decoded selector array
   * @param selectorMtf the MTF-encoded selector array
   */
  private void undoMtfForSelectors(final int nGroups, final int nSelectors,
      final byte[] pos, final byte[] selector, final byte[] selectorMtf) {
    initializeMtfPositions(nGroups, pos);
    for (int i = 0; i < nSelectors; i++) {
      selector[i] = undoMtfForOneSelector(pos, selectorMtf[i]);
    }
  }

  /**
   * Initializes the MTF position array.
   *
   * @param nGroups the number of groups
   * @param pos the position array
   */
  private void initializeMtfPositions(final int nGroups, final byte[] pos) {
    for (int v = nGroups; --v >= 0;) {
      pos[v] = (byte) v;
    }
  }

  /**
   * Undoes the MTF transform for a single selector value.
   *
   * @param pos the MTF position array
   * @param mtfValue the MTF-encoded value
   * @return the decoded selector value
   */
  private byte undoMtfForOneSelector(final byte[] pos, final int mtfValue) {
    int v = mtfValue & 0xff;
    final byte tmp = pos[v];
    while (v > 0) {
      pos[v] = pos[v - 1];
      v--;
    }
    pos[0] = tmp;
    return tmp;
  }

  /**
   * Receives the Huffman coding tables for all groups.
   *
   * @param nGroups the number of groups
   * @param alphaSize the alphabet size
   * @param len the length array to populate
   * @throws IOException if an I/O error occurs
   */
  private void receiveCodingTables(final int nGroups, final int alphaSize,
      final char[][] len) throws IOException {
    for (int t = 0; t < nGroups; t++) {
      receiveCodingTableForGroup(t, alphaSize, len);
    }
  }

  /**
   * Receives the Huffman coding table for a single group.
   *
   * @param group the group index
   * @param alphaSize the alphabet size
   * @param len the length array to populate
   * @throws IOException if an I/O error occurs
   */
  private void receiveCodingTableForGroup(final int group, final int alphaSize,
      final char[][] len) throws IOException {
    int curr = (int) bsR(5);
    final char[] lenGroup = len[group];
    for (int i = 0; i < alphaSize; i++) {
      lenGroup[i] = (char) receiveNextCodeLength(curr);
    }
  }

  /**
   * Receives the next code length value.
   *
   * @param curr the current length value
   * @return the updated length value
   * @throws IOException if an I/O error occurs
   */
  private int receiveNextCodeLength(int curr) throws IOException {
    while (bsGetBit()) {
      if (bsGetBit()) {
        curr--;
      } else {
        curr++;
      }
    }
    return curr;
  }

  /**
  * Called by recvDecodingTables() exclusively.
  */
  private void createHuffmanDecodingTables(final int alphaSize,
      final int nGroups) {
    final Data dataShadow = this.data;
    final char[][] len = dataShadow.temp_charArray2d;
    final int[] minLens = dataShadow.minLens;
    final int[][] limit = dataShadow.limit;
    final int[][] base = dataShadow.base;
    final int[][] perm = dataShadow.perm;

    for (int t = 0; t < nGroups; t++) {
      int minLen = 32;
      int maxLen = 0;
      final char[] len_t = len[t];
      for (int i = alphaSize; --i >= 0;) {
        final char lent = len_t[i];
        if (lent > maxLen) {
          maxLen = lent;
        }
        if (lent < minLen) {
          minLen = lent;
        }
      }
      hbCreateDecodeTables(limit[t], base[t], perm[t], len[t], minLen,
          maxLen, alphaSize);
      minLens[t] = minLen;
    }
  }

  private void getAndMoveToFrontDecode() throws IOException {
    this.origPtr = (int) bsR(24);
    recvDecodingTables();

    final Data dataShadow = this.data;
    final int limitLast = this.blockSize100k * 100000;

    initializeYyAndUnzftab(dataShadow.getAndMoveToFrontDecode_yy,
        dataShadow.unzftab);

    final int eob = this.nInUse + 1;
    final DecodeState state = newDecodeState(dataShadow);
    int nextSym = getAndMoveToFrontDecode0(0);

    while (nextSym != eob) {
      if (isRunLengthSymbol(nextSym)) {
        nextSym = decodeRunLength(nextSym, state, dataShadow, limitLast);
      } else {
        nextSym = decodeLiteral(nextSym, state, dataShadow, limitLast);
      }
    }

    this.last = state.lastShadow;
  }

  /**
   * Creates and initializes the decode state for a new block.
   *
   * @param dataShadow the data buffer
   * @return the initialized decode state
   */
  private DecodeState newDecodeState(final Data dataShadow) {
    final DecodeState state = new DecodeState();
    state.groupNo = 0;
    state.groupPos = G_SIZE - 1;
    state.zt = dataShadow.selector[0] & 0xff;
    state.base_zt = dataShadow.base[state.zt];
    state.limit_zt = dataShadow.limit[state.zt];
    state.perm_zt = dataShadow.perm[state.zt];
    state.minLens_zt = dataShadow.minLens[state.zt];
    state.lastShadow = -1;
    return state;
  }

  /**
   * Initializes the yy and unzftab arrays for a new block.
   *
   * @param yy the yy array
   * @param unzftab the frequency table
   */
  private void initializeYyAndUnzftab(final char[] yy, final int[] unzftab) {
    for (int i = 256; --i >= 0;) {
      yy[i] = (char) i;
      unzftab[i] = 0;
    }
  }

  /**
   * Returns true if the symbol is a run-length marker (RUNA or RUNB).
   *
   * @param sym the symbol to test
   * @return true if the symbol is a run-length marker
   */
  private boolean isRunLengthSymbol(final int sym) {
    return sym == RUNA || sym == RUNB;
  }

  /**
   * Decodes a run-length sequence starting with the given symbol.
   *
   * @param nextSym the first run-length symbol
   * @param state the current decode state
   * @param dataShadow the data buffer
   * @param limitLast the last valid index in the block
   * @return the first non-run symbol after the run
   * @throws IOException if an I/O error occurs
   */
  private int decodeRunLength(int nextSym, final DecodeState state,
      final Data dataShadow, final int limitLast) throws IOException {
    int s = -1;
    for (int n = 1; isRunLengthSymbol(nextSym); n <<= 1) {
      s += contributionForRunSymbol(nextSym, n);
      advanceGroupIfNeeded(state, dataShadow);
      nextSym = readNextSymbol(state);
    }
    writeRun(s + 1, state, dataShadow, limitLast);
    return nextSym;
  }

  /**
   * Returns the contribution of a run-length symbol to the run length.
   *
   * @param nextSym the run-length symbol
   * @param n the current power-of-two weight
   * @return the contribution
   */
  private int contributionForRunSymbol(final int nextSym, final int n) {
    if (nextSym == RUNA) {
      return n;
    }
    return n << 1;
  }

  /**
   * Writes a run of identical bytes to the decoded block.
   *
   * @param count the number of bytes to write
   * @param state the current decode state
   * @param dataShadow the data buffer
   * @param limitLast the last valid index in the block
   * @throws IOException if the block is overrun
   */
  private void writeRun(final int count, final DecodeState state,
      final Data dataShadow, final int limitLast) throws IOException {
    final byte ch = dataShadow.seqToUnseq[dataShadow.getAndMoveToFrontDecode_yy[0]];
    dataShadow.unzftab[ch & 0xff] += count;
    for (int i = 0; i < count; i++) {
      dataShadow.ll8[++state.lastShadow] = ch;
    }
    if (state.lastShadow >= limitLast) {
      throw new IOException("block overrun");
    }
  }

  /**
   * Decodes a literal symbol and updates the move-to-front list.
   *
   * @param nextSym the literal symbol
   * @param state the current decode state
   * @param dataShadow the data buffer
   * @param limitLast the last valid index in the block
   * @return the next symbol
   * @throws IOException if an I/O error occurs
   */
  private int decodeLiteral(final int nextSym, final DecodeState state,
      final Data dataShadow, final int limitLast) throws IOException {
    if (++state.lastShadow >= limitLast) {
      throw new IOException("block overrun");
    }
    final char tmp = dataShadow.getAndMoveToFrontDecode_yy[nextSym - 1];
    dataShadow.unzftab[dataShadow.seqToUnseq[tmp] & 0xff]++;
    dataShadow.ll8[state.lastShadow] = dataShadow.seqToUnseq[tmp];
    moveToFront(dataShadow.getAndMoveToFrontDecode_yy, nextSym, tmp);
    advanceGroupIfNeeded(state, dataShadow);
    return readNextSymbol(state);
  }

  /**
   * Updates the move-to-front list with the given symbol.
   *
   * @param yy the move-to-front list
   * @param nextSym the symbol index
   * @param tmp the character to move to the front
   */
  private void moveToFront(final char[] yy, final int nextSym, final char tmp) {
    if (nextSym <= 16) {
      for (int j = nextSym - 1; j > 0;) {
        yy[j] = yy[--j];
      }
    } else {
      System.arraycopy(yy, 0, yy, 1, nextSym - 1);
    }
    yy[0] = tmp;
  }

  /**
   * Advances to the next group if the current group has been exhausted.
   *
   * @param state the current decode state
   * @param dataShadow the data buffer
   */
  private void advanceGroupIfNeeded(final DecodeState state, final Data dataShadow) {
    if (state.groupPos == 0) {
      state.groupPos = G_SIZE - 1;
      state.zt = dataShadow.selector[++state.groupNo] & 0xff;
      state.base_zt = dataShadow.base[state.zt];
      state.limit_zt = dataShadow.limit[state.zt];
      state.perm_zt = dataShadow.perm[state.zt];
      state.minLens_zt = dataShadow.minLens[state.zt];
      return;
    }
    state.groupPos--;
  }

  /**
   * Reads the next symbol using the current Huffman tables.
   *
   * @param state the current decode state
   * @return the decoded symbol
   * @throws IOException if an I/O error occurs
   */
  private int readNextSymbol(final DecodeState state) throws IOException {
    int zn = state.minLens_zt;
    ensureBits(zn);
    int zvec = (int) ((this.bsBuff >> (this.bsLive - zn)) & ((1L << zn) - 1));
    this.bsLive -= zn;

    while (zvec > state.limit_zt[zn]) {
      zn++;
      ensureBits(1);
      this.bsLive--;
      zvec = (zvec << 1) | (int) ((this.bsBuff >> this.bsLive) & 1);
    }

    return state.perm_zt[zvec - state.base_zt[zn]];
  }

  /**
   * Ensures that at least n bits are available in the bit buffer.
   *
   * @param n the number of bits required
   * @throws IOException if the stream ends unexpectedly
   */
  private void ensureBits(final int n) throws IOException {
    while (this.bsLive < n) {
      final int thech = readAByte(this.in);
      if (thech < 0) {
        throw new IOException("unexpected end of stream");
      }
      this.bsBuff = (this.bsBuff << 8) | thech;
      this.bsLive += 8;
    }
  }

  private int getAndMoveToFrontDecode0(final int groupNo) throws IOException {
    final Data dataShadow = this.data;
    final int zt = dataShadow.selector[groupNo] & 0xff;
    final int[] limit_zt = dataShadow.limit[zt];
    int zn = dataShadow.minLens[zt];
    int zvec = (int) bsR(zn);

    while (zvec > limit_zt[zn]) {
      zn++;
      ensureBits(1);
      this.bsLive--;
      zvec = (zvec << 1) | (int) ((this.bsBuff >> this.bsLive) & 1);
    }

    return dataShadow.perm[zt][zvec - dataShadow.base[zt][zn]];
  }

  /**
   * Mutable state used during getAndMoveToFrontDecode.
   */
  private static final class DecodeState {
    int groupNo;
    int groupPos;
    int zt;
    int[] base_zt;
    int[] limit_zt;
    int[] perm_zt;
    int minLens_zt;
    int lastShadow;
  }

  private void setupBlock() throws IOException {
    if (this.data == null) {
      return;
    }

    final int[] cftab = this.data.cftab;
    final int[] tt = this.data.initTT(this.last + 1);
    final byte[] ll8 = this.data.ll8;
    cftab[0] = 0;
    System.arraycopy(this.data.unzftab, 0, cftab, 1, 256);

    for (int i = 1, c = cftab[0]; i <= 256; i++) {
      c += cftab[i];
      cftab[i] = c;
    }

    for (int i = 0, lastShadow = this.last; i <= lastShadow; i++) {
      tt[cftab[ll8[i] & 0xff]++] = i;
    }

    if ((this.origPtr < 0) || (this.origPtr >= tt.length)) {
      throw new IOException("stream corrupted");
    }

    this.su_tPos = tt[this.origPtr];
    this.su_count = 0;
    this.su_i2 = 0;
    this.su_ch2 = 256; /* not a char and not EOF */

    if (this.blockRandomised) {
      this.su_rNToGo = 0;
      this.su_rTPos = 0;
      setupRandPartA();
    } else {
      setupNoRandPartA();
    }
  }

  private void setupRandPartA() throws IOException {
    if (this.su_i2 <= this.last) {
      this.su_chPrev = this.su_ch2;
      int su_ch2Shadow = this.data.ll8[this.su_tPos] & 0xff;
      this.su_tPos = this.data.tt[this.su_tPos];
      if (this.su_rNToGo == 0) {
        this.su_rNToGo = BZip2Constants.rNums[this.su_rTPos] - 1;
        if (++this.su_rTPos == 512) {
          this.su_rTPos = 0;
        }
      } else {
        this.su_rNToGo--;
      }
      this.su_ch2 = su_ch2Shadow ^= (this.su_rNToGo == 1) ? 1 : 0;
      this.su_i2++;
      this.currentChar = su_ch2Shadow;
      this.currentState = STATE.RAND_PART_B_STATE;
      this.crc.updateCRC(su_ch2Shadow);
    } else {
      endBlock();
      if (readMode == READ_MODE.CONTINUOUS) {
      initBlock();
      setupBlock();
      } else if (readMode == READ_MODE.BYBLOCK) {
        this.currentState = STATE.NO_PROCESS_STATE;
      }
    }
  }

  private void setupNoRandPartA() throws IOException {
    if (this.su_i2 <= this.last) {
      this.su_chPrev = this.su_ch2;
      int su_ch2Shadow = this.data.ll8[this.su_tPos] & 0xff;
      this.su_ch2 = su_ch2Shadow;
      this.su_tPos = this.data.tt[this.su_tPos];
      this.su_i2++;
      this.currentChar = su_ch2Shadow;
      this.currentState = STATE.NO_RAND_PART_B_STATE;
      this.crc.updateCRC(su_ch2Shadow);
    } else {
      this.currentState = STATE.NO_RAND_PART_A_STATE;
      endBlock();
      if (readMode == READ_MODE.CONTINUOUS) {
      initBlock();
      setupBlock();
      } else if (readMode == READ_MODE.BYBLOCK) {
        this.currentState = STATE.NO_PROCESS_STATE;
      }
    }
  }

  private void setupRandPartB() throws IOException {
    if (this.su_ch2 != this.su_chPrev) {
      this.currentState = STATE.RAND_PART_A_STATE;
      this.su_count = 1;
      setupRandPartA();
    } else if (++this.su_count >= 4) {
      this.su_z = (char) (this.data.ll8[this.su_tPos] & 0xff);
      this.su_tPos = this.data.tt[this.su_tPos];
      if (this.su_rNToGo == 0) {
        this.su_rNToGo = BZip2Constants.rNums[this.su_rTPos] - 1;
        if (++this.su_rTPos == 512) {
          this.su_rTPos = 0;
        }
      } else {
        this.su_rNToGo--;
      }
      this.su_j2 = 0;
      this.currentState = STATE.RAND_PART_C_STATE;
      if (this.su_rNToGo == 1) {
        this.su_z ^= 1;
      }
      setupRandPartC();
    } else {
      this.currentState = STATE.RAND_PART_A_STATE;
      setupRandPartA();
    }
  }

  private void setupRandPartC() throws IOException {
    if (this.su_j2 < this.su_z) {
      this.currentChar = this.su_ch2;
      this.crc.updateCRC(this.su_ch2);
      this.su_j2++;
    } else {
      this.currentState = STATE.RAND_PART_A_STATE;
      this.su_i2++;
      this.su_count = 0;
      setupRandPartA();
    }
  }

  private void setupNoRandPartB() throws IOException {
    if (this.su_ch2 != this.su_chPrev) {
      this.su_count = 1;
      setupNoRandPartA();
    } else if (++this.su_count >= 4) {
      this.su_z = (char) (this.data.ll8[this.su_tPos] & 0xff);
      this.su_tPos = this.data.tt[this.su_tPos];
      this.su_j2 = 0;
      setupNoRandPartC();
    } else {
      setupNoRandPartA();
    }
  }

  private void setupNoRandPartC() throws IOException {
    if (this.su_j2 < this.su_z) {
      int su_ch2Shadow = this.su_ch2;
      this.currentChar = su_ch2Shadow;
      this.crc.updateCRC(su_ch2Shadow);
      this.su_j2++;
      this.currentState = STATE.NO_RAND_PART_C_STATE;
    } else {
      this.su_i2++;
      this.su_count = 0;
