private int resolveProxyPort(int proxyPort, boolean secureConnections) {
  if (proxyPort >= 0) {
    return proxyPort;
  }
  int defaultPort = secureConnections ? 443 : 80;
  LOG.warn("Proxy host set without port. Using " + (secureConnections ? "HTTPS" : "HTTP") + " default " + defaultPort);
  return defaultPort;
}
```

