private S3AFileStatus getSuffixedFileStatus(Path f, String key) throws IOException {
  if (key.endsWith("/")) {
    return null;
  }
  try {
    String newKey = key + "/";
    ObjectMetadata meta = s3.getObjectMetadata(bucket, newKey);
    statistics.incrementReadOps(1);
    S3AFileStatus status = metadataToFileStatus(f, newKey, meta);
    if (status.isDirectory()) {
      LOG.debug("Found file (with /): fake directory");
    } else {
      LOG.warn("Found file (with /): real file? should not happen: {}", key);
    }
    return status;
  } catch (AmazonServiceException e) {
    handleAmazonServiceException(e);
    return null;
  } catch (AmazonClientException e) {
    printAmazonClientException(e);
    throw e;
  }
}
