private void listDirectoryStatus(Path f, String key, List<FileStatus> result) throws IOException {
  String dirKey = key;
  if (!dirKey.isEmpty()) {
    dirKey = dirKey + "/";
  }
  if (LOG.isDebugEnabled()) {
    LOG.debug("listStatus: doing listObjects for directory " + dirKey);
  }
  ObjectListing objects = listObjects(dirKey, "/");
  while (true) {
    for (S3ObjectSummary summary : objects.getObjectSummaries()) {
      addSummaryStatus(result, summary, f);
    }
    for (String prefix : objects.getCommonPrefixes()) {
      addPrefixStatus(result, prefix, f);
    }
    if (objects.isTruncated()) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("listStatus: list truncated - getting next batch");
      }
      objects = listNextBatchOfObjects(objects);
    } else {
      break;
    }
  }
}
```

