private void ensureNoFileInPath(Path f) throws IOException {
  Path part = f;
  while (part != null) {
    try {
      FileStatus fileStatus = getFileStatus(part);
      if (fileStatus.isFile()) {
        throw new FileAlreadyExistsException(String.format("Can't make directory for path '%s' since it is a file.", part));
      }
    } catch (FileNotFoundException fnfe) {
      // continue
    }
    part = part.getParent();
  }
}
