private boolean validateRenameDestination(S3AFileStatus srcStatus, S3AFileStatus dstStatus, Path dst) throws IOException {
  if (dstStatus != null) {
    if (srcStatus.isDirectory() && dstStatus.isFile()) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src is a directory and dst is a file");
      }
      return false;
    }
    if (dstStatus.isDirectory() && !dstStatus.isEmptyDirectory()) {
      return false;
    }
    return true;
  }
  Path parent = dst.getParent();
  if (parent == null || pathToKey(parent).isEmpty()) {
    return true;
  }
  S3AFileStatus parentStatus = getStatusOrNull(parent);
  return parentStatus != null && parentStatus.isDirectory();
}
