private void applyProxySettings(ClientConfiguration awsConf, Configuration conf) {
  String proxyHost = conf.getTrimmed(PROXY_HOST, "");
  int proxyPort = conf.getInt(PROXY_PORT, -1);
  if (proxyHost.isEmpty()) {
    if (proxyPort >= 0) {
      throw proxyError(PROXY_PORT + " set without " + PROXY_HOST);
    }
    return;
  }
  boolean secureConnections = conf.getBoolean(SECURE_CONNECTIONS, DEFAULT_SECURE_CONNECTIONS);
  awsConf.setProxyHost(proxyHost);
  awsConf.setProxyPort(resolveProxyPort(proxyPort, secureConnections));
  validateProxyCredentials(awsConf, conf);
  if (LOG.isDebugEnabled()) {
    LOG.debug("Using proxy server {}:{} as user {} with password {} on domain {} as workstation {}", awsConf.getProxyHost(), awsConf.getProxyPort(), String.valueOf(awsConf.getProxyUsername()), awsConf.getProxyPassword(), awsConf.getProxyDomain(), awsConf.getProxyWorkstation());
  }
}
