private S3AFileStatus getExactFileStatus(String key, Path f) { if (key.isEmpty()) return null; try { ObjectMetadata meta = s3.getObjectMetadata(bucket, key); statistics.incrementReadOps(1); return createStatusFromMetadata(key, meta, f); } catch (AmazonServiceException e) { return handleS3ServiceException(e); } catch (AmazonClientException e) { printAmazonClientException(e); throw e; } }

private S3AFileStatus createStatusFromMetadata(String key, ObjectMetadata meta, Path f) { if (objectRepresentsDirectory(key, meta.getContentLength())) { log; return new S3AFileStatus(true,true,f.makeQualified(uri,workingDir)); } else { log; return new S3AFileStatus(meta.getContentLength(), dateToLong(meta.getLastModified()), f.makeQualified(uri,workingDir), getDefaultBlockSize(f.makeQualified(uri,workingDir))); } }

