  /**
   * Renames Path src to Path dst.  Can take place on local fs
   * or remote DFS.
   *
   * Warning: S3 does not support renames. This method does a copy which can
   * take S3 some time to execute with large files and directories. Since
   * there is no Progressable passed in, this can time out jobs.
   *
   * Note: This implementation differs with other S3 drivers. Specifically:
   *       Fails if src is a file and dst is a directory.
   *       Fails if src is a directory and dst is a file.
   *       Fails if the parent of dst does not exist or is a file.
   *       Fails if dst is a directory that is not empty.
   *
   * @param src path to be renamed
   * @param dst new path after rename
   * @throws IOException on failure
   * @return true if rename is successful
   */
  public boolean rename(Path src, Path dst) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Rename path {} to {}", src, dst);
    }

    String srcKey = pathToKey(src);
    String dstKey = pathToKey(dst);

    if (!areRenameKeysValid(srcKey, dstKey, src, dst)) {
      return false;
    }

    S3AFileStatus srcStatus = getStatusOrNull(src);
    if (srcStatus == null) {
      LOG.error("rename: src not found {}", src);
      return false;
    }

    if (srcKey.equals(dstKey)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src and dst refer to the same file or directory");
      }
      return srcStatus.isFile();
    }

    S3AFileStatus dstStatus = getStatusOrNull(dst);
    if (!validateDestinationForRename(srcStatus, dstStatus)) {
      return false;
    }

    if (dstStatus == null && !destinationParentIsDirectory(dst)) {
      return false;
    }

    if (!performRename(src, dst, srcKey, dstKey, srcStatus, dstStatus)) {
      return false;
    }

    cleanupAfterRename(src, dst);
    return true;
  }

  /**
   * Validate that the source and destination keys are non-empty.
   * @param srcKey the source key
   * @param dstKey the destination key
   * @param src the source path
   * @param dst the destination path
   * @return true if both keys are valid
   */
  private boolean areRenameKeysValid(String srcKey, String dstKey, Path src, Path dst) {
    if (srcKey.isEmpty() || dstKey.isEmpty()) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src or dst are empty");
      }
      return false;
    }
    return true;
  }

  /**
   * Get the file status for a path, returning null if it does not exist.
   * @param f the path to query
   * @return the file status, or null if not found
   * @throws IOException on other failures
   */
  private S3AFileStatus getStatusOrNull(Path f) throws IOException {
    try {
      return getFileStatus(f);
    } catch (FileNotFoundException e) {
      return null;
    }
  }

  /**
   * Validate that the destination is compatible with the source type.
   * @param srcStatus the source status
   * @param dstStatus the destination status, or null if it does not exist
   * @return true if the destination is valid
   */
  private boolean validateDestinationForRename(S3AFileStatus srcStatus, S3AFileStatus dstStatus) {
    if (dstStatus == null) {
      return true;
    }
    if (srcStatus.isDirectory() && dstStatus.isFile()) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src is a directory and dst is a file");
      }
      return false;
    }
    if (dstStatus.isDirectory() && !dstStatus.isEmptyDirectory()) {
      return false;
    }
    return true;
  }

  /**
   * Check that the parent of the destination path exists and is a directory.
   * @param dst the destination path
   * @return true if the parent is a valid directory
   * @throws IOException on failure
   */
  private boolean destinationParentIsDirectory(Path dst) throws IOException {
    Path parent = dst.getParent();
    if (pathToKey(parent).isEmpty()) {
      return true;
    }
    S3AFileStatus parentStatus = getStatusOrNull(parent);
    if (parentStatus == null || !parentStatus.isDirectory()) {
      return false;
    }
    return true;
  }

  /**
   * Perform the actual rename operation for a file or directory.
   * @param src the source path
   * @param dst the destination path
   * @param srcKey the source key
   * @param dstKey the destination key
   * @param srcStatus the source status
   * @param dstStatus the destination status
   * @return true if the rename succeeded
   * @throws IOException on failure
   */
  private boolean performRename(Path src, Path dst, String srcKey, String dstKey,
      S3AFileStatus srcStatus, S3AFileStatus dstStatus) throws IOException {
    if (srcStatus.isFile()) {
      renameFile(src, srcKey, dstKey, dstStatus);
      return true;
    } else {
      return renameDirectory(src, dst, srcKey, dstKey, dstStatus);
    }
  }

  /**
   * Rename a single file.
   * @param src the source path
   * @param srcKey the source key
   * @param dstKey the destination key
   * @param dstStatus the destination status
   * @throws IOException on failure
   */
  private void renameFile(Path src, String srcKey, String dstKey,
      S3AFileStatus dstStatus) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("rename: renaming file " + src + " to " + dstKey);
    }
    String targetKey = dstKey;
    if (dstStatus != null && dstStatus.isDirectory()) {
      targetKey = maybeAppendSlash(dstKey) + getFilename(srcKey, src.getParent());
    }
    copyFile(srcKey, targetKey);
    delete(src, false);
  }

  /**
   * Extract the filename portion of a key relative to its parent path.
   * @param srcKey the source key
   * @param srcParent the source parent path
   * @return the filename
   */
  private String getFilename(String srcKey, Path srcParent) {
    String parentKey = pathToKey(srcParent);
    return srcKey.substring(parentKey.length() + 1);
  }

  /**
   * Rename a directory and its contents.
   * @param src the source path
   * @param dst the destination path
   * @param srcKey the source key
   * @param dstKey the destination key
   * @param dstStatus the destination status
   * @return true if the rename succeeded
   * @throws IOException on failure
   */
  private boolean renameDirectory(Path src, Path dst, String srcKey, String dstKey,
      S3AFileStatus dstStatus) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("rename: renaming directory " + src + " to " + dst);
    }

    String normalizedDstKey = maybeAppendSlash(dstKey);
    String normalizedSrcKey = maybeAppendSlash(srcKey);

    // Verify dest is not a child of the source directory
    if (normalizedDstKey.startsWith(normalizedSrcKey)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("cannot rename a directory to a subdirectory of self");
      }
      return false;
    }

    List<DeleteObjectsRequest.KeyVersion> keysToDelete =
        new ArrayList<>();
    if (dstStatus != null && dstStatus.isEmptyDirectory()) {
      // delete unnecessary fake directory.
      keysToDelete.add(new DeleteObjectsRequest.KeyVersion(normalizedDstKey));
    }

    copyDirectoryEntries(normalizedSrcKey, normalizedDstKey, keysToDelete);
    return true;
  }

  /**
   * Copy all entries from the source directory to the destination directory.
   * @param srcKey the source directory key
   * @param dstKey the destination directory key
   * @param keysToDelete the list of keys to delete after copying
   * @throws IOException on failure
   */
  private void copyDirectoryEntries(String srcKey, String dstKey,
      List<DeleteObjectsRequest.KeyVersion> keysToDelete) throws IOException {
    ListObjectsRequest request = new ListObjectsRequest();
    request.setBucketName(bucket);
    request.setPrefix(srcKey);
    request.setMaxKeys(maxKeys);

    ObjectListing objects = s3.listObjects(request);
    statistics.incrementReadOps(1);

    while (true) {
      for (S3ObjectSummary summary : objects.getObjectSummaries()) {
        keysToDelete.add(new DeleteObjectsRequest.KeyVersion(summary.getKey()));
        String newDstKey = dstKey + summary.getKey().substring(srcKey.length());
        copyFile(summary.getKey(), newDstKey);

        if (keysToDelete.size() == MAX_ENTRIES_TO_DELETE) {
          deleteObjectBatch(keysToDelete);
        }
      }

      if (objects.isTruncated()) {
        objects = s3.listNextBatchOfObjects(objects);
        statistics.incrementReadOps(1);
      } else {
        if (!keysToDelete.isEmpty()) {
          deleteObjectBatch(keysToDelete);
        }
        break;
      }
    }
  }

  /**
   * Delete a batch of objects and clear the key list.
   * @param keys the keys to delete
   */
  private void deleteObjectBatch(List<DeleteObjectsRequest.KeyVersion> keys) {
    DeleteObjectsRequest deleteRequest =
        new DeleteObjectsRequest(bucket).withKeys(keys);
    s3.deleteObjects(deleteRequest);
    statistics.incrementWriteOps(1);
    keys.clear();
  }

  /**
   * Clean up fake directories after a rename.
   * @param src the source path
   * @param dst the destination path
   * @throws IOException on failure
   */
  private void cleanupAfterRename(Path src, Path dst) throws IOException {
    if (src.getParent() != dst.getParent()) {
      deleteUnnecessaryFakeDirectories(dst.getParent());
      createFakeDirectoryIfNecessary(src.getParent());
    }
  }

  /** Delete a file.
   *
   * @param f the path to delete.
   * @param recursive if path is a directory and set to
   * true, the directory is deleted else throws an exception. In
   * case of a file the recursive can be set to either true or false.
   * @return  true if delete is successful else false.
   * @throws IOException
   */
  public boolean delete(Path f, boolean recursive) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Delete path " + f + " - recursive " + recursive);
    }
    S3AFileStatus status = getStatusOrNull(f);
    if (status == null) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Couldn't delete " + f + " - does not exist");
      }
      return false;
    }

    String key = pathToKey(f);

    if (status.isDirectory()) {
      if (!deleteDirectory(f, key, recursive, status)) {
        return false;
      }
    } else {
      deleteFile(key);
    }

    createFakeDirectoryIfNecessary(f.getParent());

    return true;
  }

  /**
   * Delete a directory and its contents.
   * @param f the path to delete
   * @param key the directory key
   * @param recursive whether to delete recursively
   * @param status the directory status
   * @return true if deletion succeeded
   * @throws IOException on failure
   */
  private boolean deleteDirectory(Path f, String key, boolean recursive,
      S3AFileStatus status) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("delete: Path is a directory");
    }

    if (!recursive && !status.isEmptyDirectory()) {
      throw new IOException("Path is a folder: " + f +
          " and it is not an empty directory");
    }

    key = maybeAppendSlash(key);
    if (isRootKey(key)) {
      LOG.info("s3a cannot delete the root directory");
      return false;
    }

    if (status.isEmptyDirectory()) {
      deleteEmptyDirectory(key);
    } else {
      deleteDirectoryContents(key);
    }
    return true;
  }

  /**
   * Append a trailing slash to a key if it does not already have one.
   * @param key the key to normalize
   * @return the normalized key
   */
  private String maybeAppendSlash(String key) {
    return key.endsWith("/") ? key : key + "/";
  }

  /**
   * Check whether a key represents the root directory.
   * @param key the key to check
   * @return true if the key is the root
   */
  private boolean isRootKey(String key) {
    return "/".equals(key);
  }

  /**
   * Delete a single empty directory marker.
   * @param key the directory key
   */
  private void deleteEmptyDirectory(String key) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Deleting fake empty directory");
    }
    s3.deleteObject(bucket, key);
    statistics.incrementWriteOps(1);
  }

  /**
   * Delete all objects under a directory prefix.
   * @param key the directory key
   * @throws IOException on failure
   */
  private void deleteDirectoryContents(String key) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Getting objects for directory prefix " + key + " to delete");
    }

    ListObjectsRequest request = new ListObjectsRequest();
    request.setBucketName(bucket);
    request.setPrefix(key);
    request.setMaxKeys(maxKeys);

    List<DeleteObjectsRequest.KeyVersion> keys =
        new ArrayList<>();
    ObjectListing objects = s3.listObjects(request);
    statistics.incrementReadOps(1);
    while (true) {
      for (S3ObjectSummary summary : objects.getObjectSummaries()) {
        keys.add(new DeleteObjectsRequest.KeyVersion(summary.getKey()));
        if (LOG.isDebugEnabled()) {
          LOG.debug("Got object to delete " + summary.getKey());
        }

        if (keys.size() == MAX_ENTRIES_TO_DELETE) {
          deleteObjectBatch(keys);
        }
      }

      if (objects.isTruncated()) {
        objects = s3.listNextBatchOfObjects(objects);
        statistics.incrementReadOps(1);
      } else {
        if (!keys.isEmpty()) {
          deleteObjectBatch(keys);
        }
        break;
      }
    }
  }

  /**
   * Delete a single file.
   * @param key the file key
   */
  private void deleteFile(String key) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("delete: Path is a file");
    }
    s3.deleteObject(bucket, key);
    statistics.incrementWriteOps(1);
  }

  private void createFakeDirectoryIfNecessary(Path f) throws IOException {
    String key = pathToKey(f);
    if (!key.isEmpty() && !exists(f)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Creating new fake directory at " + f);
      }
      createFakeDirectory(bucket, key);
    }
  }

  /**
   * List the statuses of the files/directories in the given path if the path is
   * a directory.
   *
   * @param f given path
   * @return the statuses of the files/directories in the given patch
   * @throws FileNotFoundException when the path does not exist;
   *         IOException see specific implementation
   */
  public FileStatus[] listStatus(Path f) throws FileNotFoundException,
      IOException {
    String key = pathToKey(f);
    if (LOG.isDebugEnabled()) {
      LOG.debug("List status for path: " + f);
    }

    final List<FileStatus> result = new ArrayList<FileStatus>();
    final FileStatus fileStatus = getFileStatus(f);

    if (fileStatus.isDirectory()) {
      if (!key.isEmpty()) {
        key = key + "/";
      }
      listDirectoryEntries(f, key, result);
    } else {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Adding: rd (not a dir): " + f);
      }
      result.add(fileStatus);
    }

    return result.toArray(new FileStatus[result.size()]);
  }

  /**
   * List the entries under a directory and add them to the result list.
   * @param f the directory path
   * @param key the directory key
   * @param result the result list to populate
   * @throws IOException on failure
   */
  private void listDirectoryEntries(Path f, String key, List<FileStatus> result)
      throws IOException {
    ListObjectsRequest request = new ListObjectsRequest();
    request.setBucketName(bucket);
    request.setPrefix(key);
    request.setDelimiter("/");
    request.setMaxKeys(maxKeys);

    if (LOG.isDebugEnabled()) {
      LOG.debug("listStatus: doing listObjects for directory " + key);
    }

    ObjectListing objects = s3.listObjects(request);
    statistics.incrementReadOps(1);

    while (true) {
      addObjectSummaries(result, objects.getObjectSummaries(), f);
      addCommonPrefixes(result, objects.getCommonPrefixes(), f);

      if (objects.isTruncated()) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("listStatus: list truncated - getting next batch");
        }

        objects = s3.listNextBatchOfObjects(objects);
        statistics.incrementReadOps(1);
      } else {
        break;
      }
    }
  }

  /**
   * Add object summaries to the listing result.
   * @param result the result list
   * @param summaries the S3 object summaries
   * @param f the directory path
   */
  private void addObjectSummaries(List<FileStatus> result,
      List<S3ObjectSummary> summaries, Path f) {
    for (S3ObjectSummary summary : summaries) {
      Path keyPath = keyToPath(summary.getKey()).makeQualified(uri, workingDir);
      // Skip over keys that are ourselves and old S3N _$folder$ files
      if (keyPath.equals(f) || summary.getKey().endsWith(S3N_FOLDER_SUFFIX)) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("Ignoring: " + keyPath);
        }
        continue;
      }

      if (objectRepresentsDirectory(summary.getKey(), summary.getSize())) {
        result.add(new S3AFileStatus(true, true, keyPath));
        if (LOG.isDebugEnabled()) {
          LOG.debug("Adding: fd: " + keyPath);
        }
      } else {
        result.add(new S3AFileStatus(summary.getSize(),
            dateToLong(summary.getLastModified()), keyPath,
            getDefaultBlockSize(f.makeQualified(uri, workingDir))));
        if (LOG.isDebugEnabled()) {
          LOG.debug("Adding: fi: " + keyPath);
        }
      }
    }
  }

  /**
   * Add common prefixes to the listing result.
   * @param result the result list
   * @param prefixes the common prefixes
   * @param f the directory path
   */
  private void addCommonPrefixes(List<FileStatus> result, List<String> prefixes, Path f) {
    for (String prefix : prefixes) {
      Path keyPath = keyToPath(prefix).makeQualified(uri, workingDir);
      if (keyPath.equals(f)) {
        continue;
      }
      result.add(new S3AFileStatus(true, false, keyPath));
      if (LOG.isDebugEnabled()) {
        LOG.debug("Adding: rd: " + keyPath);
      }
    }
  }

  /**
   * Set the current working directory for the given file system. All relative
   * paths will be resolved relative to it.
   *
   * @param new_dir
   */
  public void setWorkingDirectory(Path new_dir) {
    workingDir = new_dir;
  }

  /**
   * Get the current working directory for the given file system
   * @return the directory pathname
   */
  public Path getWorkingDirectory() {
    return workingDir;
  }

  /**
   * Make the given file and all non-existent parents into
   * directories. Has the semantics of Unix 'mkdir -p'.
   * Existence of the directory hierarchy is not an error.
   * @param f path to create
   * @param permission to apply to f
   */
  // TODO: If we have created an empty file at /foo/bar and we then call
  // mkdirs for /foo/bar/baz/roo what happens to the empty file /foo/bar/?
  public boolean mkdirs(Path f, FsPermission permission) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Making directory: " + f);
    }

    S3AFileStatus status = getStatusOrNull(f);
    if (status != null) {
      if (status.isDirectory()) {
        return true;
      } else {
        throw new FileAlreadyExistsException("Path is a file: " + f);
      }
    }

    ensurePathHasNoFiles(f);

    String key = pathToKey(f);
    createFakeDirectory(bucket, key);
    return true;
  }

  /**
   * Ensure that no component of the path is an existing file.
   * @param f the path to check
   * @throws IOException if a component is a file
   */
  private void ensurePathHasNoFiles(Path f) throws IOException {
    Path fPart = f;
    do {
      S3AFileStatus fileStatus = getStatusOrNull(fPart);
      if (fileStatus != null && fileStatus.isFile()) {
        throw new FileAlreadyExistsException(String.format(
            "Can't make directory for path '%s' since it is a file.",
            fPart));
      }
      fPart = fPart.getParent();
    } while (fPart != null);
  }

  /**
   * Return a file status object that represents the path.
   * @param f The path we want information from
   * @return a FileStatus object
   * @throws java.io.FileNotFoundException when the path does not exist;
   *         IOException see specific implementation
   */
  public S3AFileStatus getFileStatus(Path f) throws IOException {
    String key = pathToKey(f);
    if (LOG.isDebugEnabled()) {
      LOG.debug("Getting path status for " + f + " (" + key + ")");
    }

    S3AFileStatus status = getFileStatusFromMetadata(key, f);
    if (status != null) {
      return status;
    }

    status = getFileStatusFromListing(key, f);
    if (status != null) {
      return status;
    }

    if (LOG.isDebugEnabled()) {
      LOG.debug("Not Found: " + f);
    }
    throw new FileNotFoundException("No such file or directory: " + f);
  }

  /**
   * Attempt to determine the file status from S3 object metadata.
   * @param key the key to query
   * @param f the original path
   * @return the file status, or null if not found
   * @throws IOException on failure
   */
  private S3AFileStatus getFileStatusFromMetadata(String key, Path f)
      throws IOException {
    if (!key.isEmpty()) {
      ObjectMetadata meta = getObjectMetadataOrNull(bucket, key);
      if (meta != null) {
        if (objectRepresentsDirectory(key, meta.getContentLength())) {
          if (LOG.isDebugEnabled()) {
            LOG.debug("Found exact file: fake directory");
          }
          return new S3AFileStatus(true, true,
              f.makeQualified(uri, workingDir));
        } else {
          if (LOG.isDebugEnabled()) {
            LOG.debug("Found exact file: normal file");
          }
          return createFileStatus(meta, f);
        }
      }

      if (!key.endsWith("/")) {
        String newKey = key + "/";
        ObjectMetadata metaWithSlash = getObjectMetadataOrNull(bucket, newKey);
        if (metaWithSlash != null) {
          if (objectRepresentsDirectory(newKey, metaWithSlash.getContentLength())) {
            if (LOG.isDebugEnabled()) {
              LOG.debug("Found file (with /): fake directory");
            }
            return new S3AFileStatus(true, true, f.makeQualified(uri, workingDir));
          } else {
            LOG.warn("Found file (with /): real file? should not happen: {}", key);
            return createFileStatus(metaWithSlash, f);
          }
        }
      }
    }
    return null;
  }

  /**
   * Get S3 object metadata, returning null for 404 responses.
   * @param bucketName the bucket name
   * @param key the object key
   * @return the object metadata, or null if not found
   * @throws IOException on failure
   */
  private ObjectMetadata getObjectMetadataOrNull(String bucketName, String key)
      throws IOException {
    try {
      ObjectMetadata meta = s3.getObjectMetadata(bucketName, key);
      statistics.incrementReadOps(1);
      return meta;
    } catch (AmazonServiceException e) {
      if (e.getStatusCode() != 404) {
        printAmazonServiceException(e);
        throw e;
      }
      return null;
    } catch (AmazonClientException e) {
      printAmazonClientException(e);
      throw e;
    }
  }

  /**
   * Build a file status from object metadata.
   * @param meta the object metadata
   * @param f the original path
   * @return the file status
   */
  private S3AFileStatus createFileStatus(ObjectMetadata meta, Path f) {
    return new S3AFileStatus(meta.getContentLength(),
        dateToLong(meta.getLastModified()),
        f.makeQualified(uri, workingDir),
        getDefaultBlockSize(f.makeQualified(uri, workingDir)));
  }

  /**
   * Attempt to determine the file status by listing the prefix.
   * @param key the key to query
   * @param f the original path
   * @return the directory status, or null if not found
   * @throws IOException on failure
   */
  private S3AFileStatus getFileStatusFromListing(String key, Path f)
      throws IOException {
    try {
      String prefix = key;
      if (!key.isEmpty() && !key.endsWith("/")) {
        prefix = key + "/";
      }
      ListObjectsRequest request = new ListObjectsRequest();
      request.setBucketName(bucket);
      request.setPrefix(prefix);
      request.setDelimiter("/");
      request.setMaxKeys(1);

      ObjectListing objects = s3.listObjects(request);
      statistics.incrementReadOps(1);

      if (!objects.getCommonPrefixes().isEmpty()
          || objects.getObjectSummaries().size() > 0) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("Found path as directory (with /): " +
              objects.getCommonPrefixes().size() + "/" +
              objects.getObjectSummaries().size());

          for (S3ObjectSummary summary : objects.getObjectSummaries()) {
            LOG.debug("Summary: " + summary.getKey() + " " + summary.getSize());
          }
          for (String prefixEntry : objects.getCommonPrefixes()) {
            LOG.debug("Prefix: " + prefixEntry);
          }
        }

        return new S3AFileStatus(true, false,
            f.makeQualified(uri, workingDir));
      }
      return null;
    } catch (AmazonServiceException e) {
      if (e.getStatusCode() != 404) {
        printAmazonServiceException(e);
        throw e;
      }
      return null;
    } catch (AmazonClientException e) {
      printAmazonClientException(e);
      throw e;
    }
  }

  /**
   * The src file is on the local disk.  Add it to FS at
   * the given dst name.
   *
   * This version doesn't need to create a temporary file to calculate the md5.
   * Sadly this doesn't seem to be used by the shell cp :(
   *
   * delSrc indicates if the source should be removed
   * @param delSrc whether to delete the src
   * @param overwrite whether to overwrite an existing file
   * @param src path
   * @param dst path
   */
  @Override
  public void copyFromLocalFile(boolean delSrc, boolean overwrite, Path src,
      Path dst) throws IOException {
    String key = pathToKey(dst);

    checkOverwrite(dst, overwrite);
    if (LOG.isDebugEnabled()) {
      LOG.debug("Copying local file from " + src + " to " + dst);
    }

    // Since we have a local file, we don't need to stream into a temporary file
    LocalFileSystem local = getLocal(getConf());
    File srcfile = local.pathToFile(src);

    PutObjectRequest putObjectRequest = createPutObjectRequest(key, srcfile);

    Upload up = transfers.upload(putObjectRequest);
    up.addProgressListener(createPartCompletedProgressListener());
    waitForUpload(up);

    // This will delete unnecessary fake parent directories
    finishedWrite(key);

    maybeDeleteLocalFile(local, src, delSrc);
  }

  /**
   * Throw if the destination exists and overwrite is disabled.
   * @param dst the destination path
   * @param overwrite whether overwrite is allowed
   * @throws IOException if the destination exists
   */
  private void checkOverwrite(Path dst, boolean overwrite) throws IOException {
    if (!overwrite && exists(dst)) {
      throw new IOException(dst + " already exists");
    }
  }

  /**
   * Build a PutObjectRequest for a local file upload.
   * @param key the destination key
   * @param srcfile the local source file
   * @return the put object request
   */
  private PutObjectRequest createPutObjectRequest(String key, File srcfile) {
    final ObjectMetadata om = new ObjectMetadata();
    if (StringUtils.isNotBlank(serverSideEncryptionAlgorithm)) {
      om.setServerSideEncryption(serverSideEncryptionAlgorithm);
    }
    PutObjectRequest putObjectRequest = new PutObjectRequest(bucket, key, srcfile);
    putObjectRequest.setCannedAcl(cannedACL);
    putObjectRequest.setMetadata(om);
    return putObjectRequest;
  }

  /**
   * Create a progress listener that counts completed upload/copy parts.
   * @return the progress listener
   */
  private ProgressListener createPartCompletedProgressListener() {
    return new ProgressListener() {
      public void progressChanged(ProgressEvent progressEvent) {
        switch (progressEvent.getEventCode()) {
          case ProgressEvent.PART_COMPLETED_EVENT_CODE:
            statistics.incrementWriteOps(1);
            break;
          default:
            break;
        }
      }
    };
  }

  /**
   * Wait for an upload to complete and account for the final write operation.
   * @param up the upload to wait for
   * @throws IOException if interrupted
   */
  private void waitForUpload(Upload up) throws IOException {
    try {
      up.waitForUploadResult();
      statistics.incrementWriteOps(1);
    } catch (InterruptedException e) {
      throw new IOException("Got interrupted, cancelling");
    }
  }

  /**
   * Delete the local source file if requested.
   * @param local the local filesystem
   * @param src the source path
   * @param delSrc whether to delete the source
   * @throws IOException on failure
   */
  private void maybeDeleteLocalFile(LocalFileSystem local, Path src, boolean delSrc)
      throws IOException {
    if (delSrc) {
      local.delete(src, false);
    }
  }

  @Override
  public void close() throws IOException {
    try {
      super.close();
    } finally {
      if (transfers != null) {
        transfers.shutdownNow(true);
        transfers = null;
      }
    }
  }

  /**
  * Override getCononicalServiceName because we don't support token in S3A
  */
  @Override
  public String getCanonicalServiceName() {
    // Does not support Token
    return null;
  }

  /**
   * Copy a single S3 object to a new key.
   * @param srcKey the source key
   * @param dstKey the destination key
   * @throws IOException on failure
   */
  private void copyFile(String srcKey, String dstKey) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("copyFile " + srcKey + " -> " + dstKey);
    }

    CopyObjectRequest copyObjectRequest = createCopyObjectRequest(srcKey, dstKey);

    Copy copy = transfers.copy(copyObjectRequest);
    copy.addProgressListener(createPartCompletedProgressListener());
    waitForCopy(copy);
  }

  /**
   * Build a CopyObjectRequest for copying an existing S3 object.
   * @param srcKey the source key
   * @param dstKey the destination key
   * @return the copy object request
   */
  private CopyObjectRequest createCopyObjectRequest(String srcKey, String dstKey) {
    ObjectMetadata srcom = s3.getObjectMetadata(bucket, srcKey);
    final ObjectMetadata dstom = srcom.clone();
    if (StringUtils.isNotBlank(serverSideEncryptionAlgorithm)) {
      dstom.setServerSideEncryption(serverSideEncryptionAlgorithm);
    }
    CopyObjectRequest copyObjectRequest = new CopyObjectRequest(bucket, srcKey, bucket, dstKey);
    copyObjectRequest.setCannedAccessControlList(cannedACL);
    copyObjectRequest.setNewObjectMetadata(dstom);
    return copyObjectRequest;
  }

  /**
   * Wait for a copy to complete and account for the final write operation.
   * @param copy the copy to wait for
   * @throws IOException if interrupted
   */
  private void waitForCopy(Copy copy) throws IOException {
    try {
      copy.waitForCopyResult();
      statistics.incrementWriteOps(1);
    } catch (InterruptedException e) {
      throw new IOException("Got interrupted, cancelling");
    }
  }

  private boolean objectRepresentsDirectory(final String name, final long size) {
    return !name.isEmpty() && name.charAt(name.length() - 1) == '/' && size == 0L;
