  /* Turns a path (relative or otherwise) into an S3 key
   */
  private String pathToKey(Path path) {
    if (!path.isAbsolute()) {
      path = new Path(workingDir, path);
    }

    if (hasEmptyPath(path)) {
      return "";
    }

    return path.toUri().getPath().substring(1);
  }

  /**
   * Predicate: the path URI has a scheme and an empty path component.
   * @param path the path to inspect
   * @return true when the path represents the root authority
   */
  private static boolean hasEmptyPath(Path path) {
    return path.toUri().getScheme() != null && path.toUri().getPath().isEmpty();
  }

  private Path keyToPath(String key) {
    return new Path("/" + key);
  }

  /**
   * Appends a trailing slash to a key, even if the key is empty.
   * @param key the S3 key
   * @return the key ending with a slash
   */
  private String keyWithTrailingSlash(String key) {
    if (key.endsWith("/")) {
      return key;
    }
    return key + "/";
  }

  /**
   * Returns a directory listing prefix, leaving the root prefix empty.
   * @param key the S3 key
   * @return the directory prefix
   */
  private String directoryPrefix(String key) {
    if (key.isEmpty()) {
      return key;
    }
    return keyWithTrailingSlash(key);
