private ThreadPoolExecutor createThreadPoolExecutor(Configuration conf) {
  int maxThreads = conf.getInt(MAX_THREADS, DEFAULT_MAX_THREADS);
  int coreThreads = conf.getInt(CORE_THREADS, DEFAULT_CORE_THREADS);
  maxThreads = defaultThreadsIfZero(maxThreads);
  coreThreads = defaultThreadsIfZero(coreThreads);
  long keepAliveTime = conf.getLong(KEEPALIVE_TIME, DEFAULT_KEEPALIVE_TIME);
  int maxTotalTasks = conf.getInt(MAX_TOTAL_TASKS, DEFAULT_MAX_TOTAL_TASKS);
  LinkedBlockingQueue<Runnable> workQueue = new LinkedBlockingQueue<>(maxThreads * maxTotalTasks);
  ThreadPoolExecutor executor = new ThreadPoolExecutor(
      coreThreads,
      maxThreads,
      keepAliveTime,
      TimeUnit.SECONDS,
      workQueue,
      newDaemonThreadFactory("s3a-transfer-shared-"));
  executor.allowCoreThreadTimeOut(true);
  return executor;
}

