      @Override
      public Thread newThread(Runnable r) {
        Thread t = namedFactory.newThread(r);
        if (!t.isDaemon()) {
          t.setDaemon(true);
        }
        if (t.getPriority() != Thread.NORM_PRIORITY) {
          t.setPriority(Thread.NORM_PRIORITY);
        }
        return t;
      }
    };
  }

  /**
   * Called after a new FileSystem instance is constructed.
   * @param name a uri whose authority section names the host, port, etc.
   *   for this FileSystem
   * @param conf the configuration
   */
  public void initialize(URI name, Configuration conf) throws IOException {
    super.initialize(name, conf);

    initUriAndWorkingDir(name);
    AWSCredentialsProviderChain credentials = buildCredentials(name, conf);
    bucket = name.getHost();

    ClientConfiguration awsConf = createClientConfiguration(conf);
    s3 = new AmazonS3Client(credentials, awsConf);

    configureEndpoint(conf);
    initTransferSettings(conf);
    initThreadPool(conf);
    initTransferManager();
    initCannedAcl(conf);
    verifyBucketExists();
    purgeExistingMultipartUploads(conf);

    serverSideEncryptionAlgorithm = conf.get(SERVER_SIDE_ENCRYPTION_ALGORITHM);

    setConf(conf);
  }

  /** Initializes the filesystem URI and working directory. */
  private void initUriAndWorkingDir(URI name) {
    uri = URI.create(name.getScheme() + "://" + name.getAuthority());
    workingDir = new Path("/user", System.getProperty("user.name")).makeQualified(this.uri,
        this.getWorkingDirectory());
  }

  /** Builds the AWS credentials chain from configuration and URI user info. */
  private AWSCredentialsProviderChain buildCredentials(URI name, Configuration conf) {
    String accessKey = conf.get(ACCESS_KEY, null);
    String secretKey = conf.get(SECRET_KEY, null);

    String userInfo = name.getUserInfo();
    if (userInfo != null) {
      int index = userInfo.indexOf(':');
      if (index != -1) {
        accessKey = userInfo.substring(0, index);
        secretKey = userInfo.substring(index + 1);
      } else {
        accessKey = userInfo;
      }
    }

    return new AWSCredentialsProviderChain(
        new BasicAWSCredentialsProvider(accessKey, secretKey),
        new InstanceProfileCredentialsProvider(),
        new AnonymousAWSCredentialsProvider()
    );
  }

  /** Creates and configures the AWS client configuration. */
  private ClientConfiguration createClientConfiguration(Configuration conf) {
    ClientConfiguration awsConf = new ClientConfiguration();
    awsConf.setMaxConnections(conf.getInt(MAXIMUM_CONNECTIONS,
        DEFAULT_MAXIMUM_CONNECTIONS));

    boolean secureConnections = conf.getBoolean(SECURE_CONNECTIONS,
        DEFAULT_SECURE_CONNECTIONS);
    if (secureConnections) {
      awsConf.setProtocol(Protocol.HTTPS);
    } else {
      awsConf.setProtocol(Protocol.HTTP);
    }

    awsConf.setMaxErrorRetry(conf.getInt(MAX_ERROR_RETRIES,
        DEFAULT_MAX_ERROR_RETRIES));
    awsConf.setConnectionTimeout(conf.getInt(ESTABLISH_TIMEOUT,
        DEFAULT_ESTABLISH_TIMEOUT));
    awsConf.setSocketTimeout(conf.getInt(SOCKET_TIMEOUT,
        DEFAULT_SOCKET_TIMEOUT));

    configureProxy(awsConf, conf, secureConnections);
    return awsConf;
  }

  /** Configures proxy settings on the AWS client configuration. */
  private void configureProxy(ClientConfiguration awsConf, Configuration conf,
      boolean secureConnections) {
    String proxyHost = conf.getTrimmed(PROXY_HOST, "");
    int proxyPort = conf.getInt(PROXY_PORT, -1);

    if (proxyHost.isEmpty()) {
      if (proxyPort >= 0) {
        throwProxyError(PROXY_PORT + " set without " + PROXY_HOST);
      }
      return;
    }

    awsConf.setProxyHost(proxyHost);
    if (proxyPort < 0) {
      proxyPort = defaultProxyPort(secureConnections);
    }
    awsConf.setProxyPort(proxyPort);

    configureProxyCredentials(awsConf, conf);
    awsConf.setProxyDomain(conf.getTrimmed(PROXY_DOMAIN));
    awsConf.setProxyWorkstation(conf.getTrimmed(PROXY_WORKSTATION));
    logProxySettings(awsConf);
  }

  /** Returns the default proxy port based on whether secure connections are used. */
  private int defaultProxyPort(boolean secureConnections) {
    if (secureConnections) {
      LOG.warn("Proxy host set without port. Using HTTPS default 443");
      return 443;
    }
    LOG.warn("Proxy host set without port. Using HTTP default 80");
    return 80;
  }

  /** Configures proxy credentials, validating that both username and password are set. */
  private void configureProxyCredentials(ClientConfiguration awsConf, Configuration conf) {
    String proxyUsername = conf.getTrimmed(PROXY_USERNAME);
    String proxyPassword = conf.getTrimmed(PROXY_PASSWORD);

    if (isProxyAuthIncomplete(proxyUsername, proxyPassword)) {
      throwProxyError(PROXY_USERNAME + " or " + PROXY_PASSWORD +
          " set without the other.");
    }

    awsConf.setProxyUsername(proxyUsername);
    awsConf.setProxyPassword(proxyPassword);
  }

  /** Checks whether exactly one of the proxy credentials is set. */
  private boolean isProxyAuthIncomplete(String proxyUsername, String proxyPassword) {
    return (proxyUsername == null) != (proxyPassword == null);
  }

  /** Throws an IllegalArgumentException for a proxy configuration error. */
  private void throwProxyError(String detail) {
    String msg = "Proxy error: " + detail;
    LOG.error(msg);
    throw new IllegalArgumentException(msg);
  }

  /** Logs proxy settings at debug level. */
  private void logProxySettings(ClientConfiguration awsConf) {
    if (!LOG.isDebugEnabled()) {
      return;
    }
    LOG.debug("Using proxy server {}:{} as user {} with password {} on " +
            "domain {} as workstation {}", awsConf.getProxyHost(),
        awsConf.getProxyPort(), String.valueOf(awsConf.getProxyUsername()),
        awsConf.getProxyPassword(), awsConf.getProxyDomain(),
        awsConf.getProxyWorkstation());
  }

  /** Configures a custom S3 endpoint if one is provided. */
  private void configureEndpoint(Configuration conf) {
    String endPoint = conf.getTrimmed(ENDPOINT, "");
    if (endPoint.isEmpty()) {
      return;
    }
    try {
      s3.setEndpoint(endPoint);
    } catch (IllegalArgumentException e) {
      String msg = "Incorrect endpoint: " + e.getMessage();
      LOG.error(msg);
      throw new IllegalArgumentException(msg, e);
    }
  }

  /** Initializes paging and multipart upload size settings. */
  private void initTransferSettings(Configuration conf) {
    maxKeys = conf.getInt(MAX_PAGING_KEYS, DEFAULT_MAX_PAGING_KEYS);
    partSize = conf.getLong(MULTIPART_SIZE, DEFAULT_MULTIPART_SIZE);
    multiPartThreshold = conf.getInt(MIN_MULTIPART_THRESHOLD,
        DEFAULT_MIN_MULTIPART_THRESHOLD);

    partSize = ensureAtLeastFiveMegabytes(partSize, MULTIPART_SIZE);
    multiPartThreshold = (int) ensureAtLeastFiveMegabytes(multiPartThreshold,
        MIN_MULTIPART_THRESHOLD);
  }

  /** Ensures a size value is at least 5 MB, logging a warning if it is adjusted. */
  private long ensureAtLeastFiveMegabytes(long value, String name) {
    if (value >= 5 * 1024 * 1024) {
      return value;
    }
    LOG.error(name + " must be at least 5 MB");
    return 5 * 1024 * 1024;
  }

  /** Initializes the shared thread pool used by the transfer manager. */
  private void initThreadPool(Configuration conf) {
    int maxThreads = conf.getInt(MAX_THREADS, DEFAULT_MAX_THREADS);
    int coreThreads = conf.getInt(CORE_THREADS, DEFAULT_CORE_THREADS);

    if (maxThreads == 0) {
      maxThreads = Runtime.getRuntime().availableProcessors() * 8;
    }
    if (coreThreads == 0) {
      coreThreads = Runtime.getRuntime().availableProcessors() * 8;
    }

    long keepAliveTime = conf.getLong(KEEPALIVE_TIME, DEFAULT_KEEPALIVE_TIME);
    int totalTasks = conf.getInt(MAX_TOTAL_TASKS, DEFAULT_MAX_TOTAL_TASKS);
    LinkedBlockingQueue<Runnable> workQueue =
        new LinkedBlockingQueue<>(maxThreads * totalTasks);

    threadPoolExecutor = new ThreadPoolExecutor(
        coreThreads,
        maxThreads,
        keepAliveTime,
        TimeUnit.SECONDS,
        workQueue,
        newDaemonThreadFactory("s3a-transfer-shared-"));
    threadPoolExecutor.allowCoreThreadTimeOut(true);
  }

  /** Creates and configures the S3 transfer manager. */
  private void initTransferManager() {
    TransferManagerConfiguration transferConfiguration = new TransferManagerConfiguration();
    transferConfiguration.setMinimumUploadPartSize(partSize);
    transferConfiguration.setMultipartUploadThreshold(multiPartThreshold);

    transfers = new TransferManager(s3, threadPoolExecutor);
    transfers.setConfiguration(transferConfiguration);
  }

  /** Initializes the canned ACL from configuration. */
  private void initCannedAcl(Configuration conf) {
    String cannedACLName = conf.get(CANNED_ACL, DEFAULT_CANNED_ACL);
    if (cannedACLName.isEmpty()) {
      cannedACL = null;
    } else {
      cannedACL = CannedAccessControlList.valueOf(cannedACLName);
    }
  }

  /** Verifies that the configured bucket exists. */
  private void verifyBucketExists() throws IOException {
    if (!s3.doesBucketExist(bucket)) {
      throw new IOException("Bucket " + bucket + " does not exist");
    }
  }

  /** Aborts multipart uploads older than the configured age if enabled. */
  private void purgeExistingMultipartUploads(Configuration conf) {
    boolean purgeExistingMultipart = conf.getBoolean(PURGE_EXISTING_MULTIPART,
        DEFAULT_PURGE_EXISTING_MULTIPART);
    if (!purgeExistingMultipart) {
      return;
    }

    long purgeExistingMultipartAge = conf.getLong(PURGE_EXISTING_MULTIPART_AGE,
        DEFAULT_PURGE_EXISTING_MULTIPART_AGE);
    Date purgeBefore = new Date(new Date().getTime() - purgeExistingMultipartAge * 1000);

    transfers.abortMultipartUploads(bucket, purgeBefore);
  }

  /**
   * Return the protocol scheme for the FileSystem.
   *
   * @return "s3a"
   */
  public String getScheme() {
    return "s3a";
  }

  /** Returns a URI whose scheme and authority identify this FileSystem.*/
  public URI getUri() {
    return uri;
  }

  /**
   * Returns the S3 client used by this filesystem.
   * @return AmazonS3Client
   */
  @VisibleForTesting
  AmazonS3Client getAmazonS3Client() {
    return s3;
  }

  public S3AFileSystem() {
    super();
  }

  /* Turns a path (relative or otherwise) into an S3 key
   */
  private String pathToKey(Path path) {
    if (!path.isAbsolute()) {
      path = new Path(workingDir, path);
    }

    URI pathUri = path.toUri();
    if (pathUri.getScheme() == null) {
      return pathUri.getPath().substring(1);
    }
    if (pathUri.getPath().isEmpty()) {
      return "";
    }
    return pathUri.getPath().substring(1);
  }

  private Path keyToPath(String key) {
    return new Path("/" + key);
  }

  /**
   * Opens an FSDataInputStream at the indicated Path.
   * @param f the file name to open
   * @param bufferSize the size of the buffer to be used.
   */
  public FSDataInputStream open(Path f, int bufferSize)
      throws IOException {

    if (LOG.isDebugEnabled()) {
      LOG.debug("Opening '{}' for reading.", f);
    }
    final FileStatus fileStatus = getFileStatus(f);
    if (fileStatus.isDirectory()) {
      throw new FileNotFoundException("Can't open " + f + " because it is a directory");
    }

    return new FSDataInputStream(new S3AInputStream(bucket, pathToKey(f),
        fileStatus.getLen(), s3, statistics));
  }

  /**
   * Create an FSDataOutputStream at the indicated Path with write-progress
   * reporting.
   * @param f the file name to open
   * @param permission
   * @param overwrite if a file with this name already exists, then if true,
   *   the file will be overwritten, and if false an error will be thrown.
   * @param bufferSize the size of the buffer to be used.
   * @param replication required block replication for the file.
   * @param blockSize
   * @param progress
   * @throws IOException
   * @see #setPermission(Path, FsPermission)
   */
  public FSDataOutputStream create(Path f, FsPermission permission, boolean overwrite,
      int bufferSize, short replication, long blockSize, Progressable progress) throws IOException {
    String key = pathToKey(f);

    if (fileExistsAndCannotOverwrite(f, overwrite)) {
      throw new FileAlreadyExistsException(f + " already exists");
    }

    if (isFastUploadEnabled()) {
      return new FSDataOutputStream(new S3AFastOutputStream(s3, this, bucket,
          key, progress, statistics, cannedACL,
          serverSideEncryptionAlgorithm, partSize, (long) multiPartThreshold,
          threadPoolExecutor), statistics);
    }

    // We pass null to FSDataOutputStream so it won't count writes that are being buffered to a file
    return new FSDataOutputStream(new S3AOutputStream(getConf(), transfers, this,
        bucket, key, progress, cannedACL, statistics,
        serverSideEncryptionAlgorithm), null);
  }

  /** Returns true when the file exists and overwrite is disabled. */
  private boolean fileExistsAndCannotOverwrite(Path f, boolean overwrite) throws IOException {
    if (overwrite) {
      return false;
    }
    return exists(f);
  }

  /** Returns true if the fast upload output stream is enabled. */
  private boolean isFastUploadEnabled() {
    return getConf().getBoolean(FAST_UPLOAD, DEFAULT_FAST_UPLOAD);
  }

  /**
   * Append to an existing file (optional operation).
   * @param f the existing file to be appended.
   * @param bufferSize the size of the buffer to be used.
   * @param progress for reporting progress if it is not null.
   * @throws IOException
   */
  public FSDataOutputStream append(Path f, int bufferSize,
      Progressable progress) throws IOException {
    throw new IOException("Not supported");
  }

  /**
   * Renames Path src to Path dst.  Can take place on local fs
   * or remote DFS.
   *
   * Warning: S3 does not support renames. This method does a copy which can
   * take S3 some time to execute with large files and directories. Since
   * there is no Progressable passed in, this can time out jobs.
   *
   * Note: This implementation differs with other S3 drivers. Specifically:
   *       Fails if src is a file and dst is a directory.
   *       Fails if src is a directory and dst is a file.
   *       Fails if the parent of dst does not exist or is a file.
   *       Fails if dst is a directory that is not empty.
   *
   * @param src path to be renamed
   * @param dst new path after rename
   * @throws IOException on failure
   * @return true if rename is successful
   */
  public boolean rename(Path src, Path dst) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Rename path {} to {}", src, dst);
    }

    String srcKey = pathToKey(src);
    String dstKey = pathToKey(dst);

    if (isRootKey(srcKey)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src or dst are empty");
      }
      return false;
    }
    if (isRootKey(dstKey)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src or dst are empty");
      }
      return false;
    }

    S3AFileStatus srcStatus = getStatusOrNull(src);
    if (srcStatus == null) {
      LOG.error("rename: src not found {}", src);
      return false;
    }

    if (srcKey.equals(dstKey)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("rename: src and dst refer to the same file or directory");
      }
      return srcStatus.isFile();
    }

    S3AFileStatus dstStatus = getStatusOrNull(dst);
    if (!isRenameDestinationValid(srcStatus, dstStatus, dst)) {
      return false;
    }

    if (srcStatus.isFile()) {
      renameFile(src, srcKey, dst, dstKey, dstStatus);
    } else {
      if (!renameDirectory(src, srcKey, dst, dstKey, dstStatus)) {
        return false;
      }
    }

    if (!haveSameParent(src, dst)) {
      deleteUnnecessaryFakeDirectories(dst.getParent());
      createFakeDirectoryIfNecessary(src.getParent());
    }
    return true;
  }

  /** Returns the file status for a path, or null if the path does not exist. */
  private S3AFileStatus getStatusOrNull(Path path) throws IOException {
    try {
      return getFileStatus(path);
    } catch (FileNotFoundException e) {
      return null;
    }
  }

  /** Returns true if the given S3 key represents the root of the bucket. */
  private boolean isRootKey(String key) {
    return key.isEmpty();
  }

  /** Returns true if the destination status makes this a directory-to-file rename. */
  private boolean isDirectoryToFileRename(S3AFileStatus srcStatus, S3AFileStatus dstStatus) {
    if (!srcStatus.isDirectory()) {
      return false;
    }
    return dstStatus.isFile();
  }

  /** Returns true if the status represents a non-empty directory. */
  private boolean isNonEmptyDirectory(S3AFileStatus status) {
    if (!status.isDirectory()) {
      return false;
    }
    return !status.isEmptyDirectory();
  }

  /** Returns true if the status represents an empty directory. */
  private boolean isEmptyDirectory(S3AFileStatus status) {
    if (status == null) {
      return false;
    }
    if (!status.isDirectory()) {
      return false;
    }
    return status.isEmptyDirectory();
  }

  /** Returns true if the status is non-null and represents a directory. */
  private boolean isExistingDirectory(S3AFileStatus status) {
    if (status == null) {
      return false;
    }
    return status.isDirectory();
  }

  /** Returns true if the destination key is a descendant of the source key. */
  private boolean isDescendant(String dstKey, String srcKey) {
    return dstKey.startsWith(srcKey);
  }

  /** Returns true if src and dst share the same parent path. */
  private boolean haveSameParent(Path src, Path dst) {
    Path srcParent = src.getParent();
    Path dstParent = dst.getParent();
    if (srcParent == null) {
      return dstParent == null;
    }
    return srcParent.equals(dstParent);
  }

  /** Validates that the rename destination is acceptable for the source type. */
  private boolean isRenameDestinationValid(S3AFileStatus srcStatus,
      S3AFileStatus dstStatus, Path dst) throws IOException {
    if (dstStatus != null) {
      if (isDirectoryToFileRename(srcStatus, dstStatus)) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("rename: src is a directory and dst is a file");
        }
        return false;
      }
      if (isNonEmptyDirectory(dstStatus)) {
        return false;
      }
      return true;
    }
    return parentOfDestinationExists(dst);
  }

  /** Returns true if the parent of the destination path exists and is a directory. */
  private boolean parentOfDestinationExists(Path dst) throws IOException {
    Path parent = dst.getParent();
    if (isRootPath(parent)) {
      return true;
    }
    S3AFileStatus parentStatus = getStatusOrNull(parent);
    if (parentStatus == null) {
      return false;
    }
    return parentStatus.isDirectory();
  }

  /** Returns true if the given path is the bucket root. */
  private boolean isRootPath(Path path) {
    return pathToKey(path).isEmpty();
  }

  /** Ensures a directory key ends with a trailing slash. */
  private String ensureDirectoryKey(String key) {
    if (key.endsWith("/")) {
      return key;
    }
    return key + "/";
  }

  /** Builds the destination key when a file is renamed into an existing directory. */
  private String buildDestinationKeyForFileInDirectory(Path src, String srcKey, String dstKey) {
    String dirKey = ensureDirectoryKey(dstKey);
    String parentKey = pathToKey(src.getParent());
    String filename = srcKey.substring(parentKey.length() + 1);
    return dirKey + filename;
  }

  /** Renames a file from src to dst. */
  private void renameFile(Path src, String srcKey, Path dst, String dstKey,
      S3AFileStatus dstStatus) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("rename: renaming file " + src + " to " + dst);
    }

    String destinationKey = dstKey;
    if (isExistingDirectory(dstStatus)) {
      destinationKey = buildDestinationKeyForFileInDirectory(src, srcKey, dstKey);
    }

    copyFile(srcKey, destinationKey);
    delete(src, false);
  }

  /** Renames a directory from src to dst. */
  private boolean renameDirectory(Path src, String srcKey, Path dst, String dstKey,
      S3AFileStatus dstStatus) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("rename: renaming directory " + src + " to " + dst);
    }

    String normalizedSrc = ensureDirectoryKey(srcKey);
    String normalizedDst = ensureDirectoryKey(dstKey);

    if (isDescendant(normalizedDst, normalizedSrc)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("cannot rename a directory to a subdirectory of self");
      }
      return false;
    }

    List<DeleteObjectsRequest.KeyVersion> keysToDelete = new ArrayList<>();
    if (isEmptyDirectory(dstStatus)) {
      keysToDelete.add(new DeleteObjectsRequest.KeyVersion(normalizedDst));
    }

    copyDirectoryContents(normalizedSrc, normalizedDst, keysToDelete);
    return true;
  }

  /** Copies all objects under a source directory prefix to a destination directory prefix. */
  private void copyDirectoryContents(String srcKey, String dstKey,
      List<DeleteObjectsRequest.KeyVersion> keysToDelete) throws IOException {
    ObjectListing objects = listObjectsForPrefix(srcKey);

    while (true) {
      copySummaries(objects, srcKey, dstKey, keysToDelete);

      if (!objects.isTruncated()) {
        deleteRemainingKeys(keysToDelete);
        break;
      }

      objects = s3.listNextBatchOfObjects(objects);
      statistics.incrementReadOps(1);
    }
  }

  /** Copies the object summaries in a listing and records keys for later deletion. */
  private void copySummaries(ObjectListing objects, String srcKey, String dstKey,
      List<DeleteObjectsRequest.KeyVersion> keysToDelete) throws IOException {
    for (S3ObjectSummary summary : objects.getObjectSummaries()) {
      keysToDelete.add(new DeleteObjectsRequest.KeyVersion(summary.getKey()));
      String newDstKey = dstKey + summary.getKey().substring(srcKey.length());
      copyFile(summary.getKey(), newDstKey);
      deleteKeysIfFull(keysToDelete);
    }
  }

  /** Deletes a batch of keys once the batch reaches the maximum allowed size. */
  private void deleteKeysIfFull(List<DeleteObjectsRequest.KeyVersion> keysToDelete) {
    if (keysToDelete.size() != MAX_ENTRIES_TO_DELETE) {
      return;
    }
    deleteKeys(keysToDelete);
    keysToDelete.clear();
  }

  /** Deletes any remaining keys in the batch. */
  private void deleteRemainingKeys(List<DeleteObjectsRequest.KeyVersion> keysToDelete) {
    if (keysToDelete.isEmpty()) {
      return;
    }
    deleteKeys(keysToDelete);
  }

  /** Deletes the given batch of keys from S3. */
  private void deleteKeys(List<DeleteObjectsRequest.KeyVersion> keysToDelete) {
    DeleteObjectsRequest deleteRequest =
        new DeleteObjectsRequest(bucket).withKeys(keysToDelete);
    s3.deleteObjects(deleteRequest);
    statistics.incrementWriteOps(1);
  }

  /** Lists S3 objects under the given prefix. */
  private ObjectListing listObjectsForPrefix(String prefix) {
    ListObjectsRequest request = new ListObjectsRequest();
    request.setBucketName(bucket);
    request.setPrefix(prefix);
    request.setMaxKeys(maxKeys);

    ObjectListing objects = s3.listObjects(request);
    statistics.incrementReadOps(1);
    return objects;
  }

  /** Delete a file.
   *
   * @param f the path to delete.
   * @param recursive if path is a directory and set to
   * true, the directory is deleted else throws an exception. In
   * case of a file the recursive can be set to either true or false.
   * @return  true if delete is successful else false.
   * @throws IOException
   */
  public boolean delete(Path f, boolean recursive) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Delete path " + f + " - recursive " + recursive);
    }

    S3AFileStatus status = getStatusOrNull(f);
    if (status == null) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Couldn't delete " + f + " - does not exist");
      }
      return false;
    }

    String key = pathToKey(f);
    if (status.isDirectory()) {
      return deleteDirectory(f, key, status, recursive);
    }
    return deleteFile(key, f);
  }

  /** Deletes a directory and its contents if recursive is true. */
  private boolean deleteDirectory(Path f, String key, S3AFileStatus status,
      boolean recursive) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("delete: Path is a directory");
    }

    if (!recursive) {
      if (!status.isEmptyDirectory()) {
        throw new IOException("Path is a folder: " + f +
            " and it is not an empty directory");
      }
    }

    String dirKey = ensureDirectoryKey(key);
    if (isRootKey(dirKey)) {
      LOG.info("s3a cannot delete the root directory");
      return false;
    }

    if (status.isEmptyDirectory()) {
      deleteEmptyDirectory(dirKey);
    } else {
      deleteDirectoryContents(dirKey);
    }

    createFakeDirectoryIfNecessary(f.getParent());
    return true;
  }

  /** Deletes a single empty directory marker. */
  private void deleteEmptyDirectory(String key) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Deleting fake empty directory");
    }
    s3.deleteObject(bucket, key);
    statistics.incrementWriteOps(1);
  }

  /** Deletes a file and creates a fake parent directory if necessary. */
  private boolean deleteFile(String key, Path f) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("delete: Path is a file");
    }
    s3.deleteObject(bucket, key);
    statistics.incrementWriteOps(1);
    createFakeDirectoryIfNecessary(f.getParent());
    return true;
  }

  /** Recursively deletes all objects under a directory prefix. */
  private void deleteDirectoryContents(String dirKey) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Getting objects for directory prefix " + dirKey + " to delete");
    }

    List<DeleteObjectsRequest.KeyVersion> keys = new ArrayList<>();
    ObjectListing objects = listObjectsForPrefix(dirKey);

    while (true) {
      collectKeysForDeletion(objects, keys);

      if (!objects.isTruncated()) {
        deleteRemainingKeys(keys);
        break;
      }

      objects = s3.listNextBatchOfObjects(objects);
      statistics.incrementReadOps(1);
    }
  }

  /** Collects object keys from a listing for batch deletion. */
  private void collectKeysForDeletion(ObjectListing objects,
      List<DeleteObjectsRequest.KeyVersion> keys) {
    for (S3ObjectSummary summary : objects.getObjectSummaries()) {
      keys.add(new DeleteObjectsRequest.KeyVersion(summary.getKey()));
      if (LOG.isDebugEnabled()) {
        LOG.debug("Got object to delete " + summary.getKey());
      }
      deleteKeysIfFull(keys);
    }
  }

  private void createFakeDirectoryIfNecessary(Path f) throws IOException {
    String key = pathToKey(f);
    if (key.isEmpty()) {
      return;
    }
    if (exists(f)) {
      return;
    }
    if (LOG.isDebugEnabled()) {
      LOG.debug("Creating new fake directory at " + f);
    }
    createFakeDirectory(bucket, key);
  }

  /**
   * List the statuses of the files/directories in the given path if the path is
   * a directory.
   *
   * @param f given path
   * @return the statuses of the files/directories in the given patch
   * @throws FileNotFoundException when the path does not exist;
   *         IOException see specific implementation
   */
  public FileStatus[] listStatus(Path f) throws FileNotFoundException,
      IOException {
    String key = pathToKey(f);
    if (LOG.isDebugEnabled()) {
      LOG.debug("List status for path: " + f);
    }

    List<FileStatus> result = new ArrayList<FileStatus>();
    FileStatus fileStatus = getFileStatus(f);

    if (!fileStatus.isDirectory()) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Adding: rd (not a dir): " + f);
      }
      result.add(fileStatus);
      return result.toArray(new FileStatus[result.size()]);
    }

    listDirectoryStatus(f, key, result);
    return result.toArray(new FileStatus[result.size()]);
  }

  /** Lists the statuses of entries in a directory. */
  private void listDirectoryStatus(Path f, String key, List<FileStatus> result)
      throws IOException {
    String prefix = ensureDirectoryPrefix(key);
    ListObjectsRequest request = buildListStatusRequest(prefix);

    ObjectListing objects = s3.listObjects(request);
    statistics.incrementReadOps(1);

    while (true) {
      addSummaries(objects, f, result);
      addPrefixes(objects, f, result);

      if (!objects.isTruncated()) {
        break;
      }

      objects = s3.listNextBatchOfObjects(objects);
      statistics.incrementReadOps(1);
      if (LOG.isDebugEnabled()) {
        LOG.debug("listStatus: list truncated - getting next batch");
      }
    }
  }

  /** Ensures a directory prefix ends with a slash, leaving the root prefix empty. */
  private String ensureDirectoryPrefix(String key) {
    if (key.isEmpty()) {
      return key;
    }
    return ensureDirectoryKey(key);
  }

  /** Builds a list request for directory status listing. */
  private ListObjectsRequest buildListStatusRequest(String prefix) {
    ListObjectsRequest request = new ListObjectsRequest();
    request.setBucketName(bucket);
    request.setPrefix(prefix);
    request.setDelimiter("/");
    request.setMaxKeys(maxKeys);
    return request;
  }

  /** Adds file statuses for object summaries to the result list. */
  private void addSummaries(ObjectListing objects, Path f, List<FileStatus> result)
      throws IOException {
    for (S3ObjectSummary summary : objects.getObjectSummaries()) {
      Path keyPath = keyToPath(summary.getKey()).makeQualified(uri, workingDir);

      if (shouldIgnoreSummary(keyPath, f, summary)) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("Ignoring: " + keyPath);
        }
        continue;
      }

      addSummaryStatus(summary, keyPath, result);
    }
  }

  /** Returns true if a summary should be skipped during listing. */
  private boolean shouldIgnoreSummary(Path keyPath, Path f, S3ObjectSummary summary) {
    if (keyPath.equals(f)) {
      return true;
    }
    return summary.getKey().endsWith(S3N_FOLDER_SUFFIX);
  }

  /** Adds a single summary as either a directory or file status. */
  private void addSummaryStatus(S3ObjectSummary summary, Path keyPath,
      List<FileStatus> result) throws IOException {
    if (objectRepresentsDirectory(summary.getKey(), summary.getSize())) {
      result.add(new S3AFileStatus(true, true, keyPath));
      if (LOG.isDebugEnabled()) {
        LOG.debug("Adding: fd: " + keyPath);
      }
    } else {
      result.add(new S3AFileStatus(summary.getSize(),
          dateToLong(summary.getLastModified()), keyPath,
          getDefaultBlockSize(keyPath)));
      if (LOG.isDebugEnabled()) {
        LOG.debug("Adding: fi: " + keyPath);
      }
    }
  }

  /** Adds directory statuses for common prefixes to the result list. */
  private void addPrefixes(ObjectListing objects, Path f, List<FileStatus> result) {
    for (String prefix : objects.getCommonPrefixes()) {
      Path keyPath = keyToPath(prefix).makeQualified(uri, workingDir);
      if (keyPath.equals(f)) {
        continue;
      }
      result.add(new S3AFileStatus(true, false, keyPath));
      if (LOG.isDebugEnabled()) {
        LOG.debug("Adding: rd: " + keyPath);
      }
    }
  }

  /**
   * Set the current working directory for the given file system. All relative
   * paths will be resolved relative to it.
   *
   * @param new_dir
   */
  public void setWorkingDirectory(Path new_dir) {
    workingDir = new_dir;
  }

  /**
   * Get the current working directory for the given file system
   * @return the directory pathname
   */
  public Path getWorkingDirectory() {
    return workingDir;
  }

  /**
   * Make the given file and all non-existent parents into
   * directories. Has the semantics of Unix 'mkdir -p'.
   * Existence of the directory hierarchy is not an error.
   * @param f path to create
   * @param permission to apply to f
   */
  // TODO: If we have created an empty file at /foo/bar and we then call
  // mkdirs for /foo/bar/baz/roo what happens to the empty file /foo/bar/?
  public boolean mkdirs(Path f, FsPermission permission) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Making directory: " + f);
    }

    try {
      FileStatus fileStatus = getFileStatus(f);
      if (fileStatus.isDirectory()) {
        return true;
      }
      throw new FileAlreadyExistsException("Path is a file: " + f);
    } catch (FileNotFoundException e) {
      ensureNoParentIsFile(f);
      String key = pathToKey(f);
      createFakeDirectory(bucket, key);
      return true;
    }
  }

  /** Ensures no parent of the given path is an existing file. */
  private void ensureNoParentIsFile(Path f) throws IOException {
    Path current = f;
    while (current != null) {
      S3AFileStatus status = getStatusOrNull(current);
      if (status == null) {
        current = current.getParent();
        continue;
      }
      if (status.isFile()) {
        throw new FileAlreadyExistsException(String.format(
            "Can't make directory for path '%s' since it is a file.",
            current));
      }
      current = current.getParent();
    }
  }

  /**
   * Return a file status object that represents the path.
   * @param f The path we want information from
   * @return a FileStatus object
   * @throws java.io.FileNotFoundException when the path does not exist;
   *         IOException see specific implementation
   */
  public S3AFileStatus getFileStatus(Path f) throws IOException {
    String key = pathToKey(f);
    if (LOG.isDebugEnabled()) {
      LOG.debug("Getting path status for " + f + " (" + key + ")");
    }

    if (key.isEmpty()) {
      S3AFileStatus rootStatus = resolveRootStatus(f);
      if (rootStatus != null) {
        return rootStatus;
      }
    } else {
      S3AFileStatus exact = resolveExactKeyStatus(f, key);
      if (exact != null) {
        return exact;
      }

      S3AFileStatus withSlash = resolveKeyWithSlashStatus(f, key);
      if (withSlash != null) {
        return withSlash;
      }

      S3AFileStatus directory = resolveDirectoryStatus(f, key);
      if (directory != null) {
        return directory;
      }
    }

    if (LOG.isDebugEnabled()) {
      LOG.debug("Not Found: " + f);
    }
    throw new FileNotFoundException("No such file or directory: " + f);
  }

  /** Resolves the status of the bucket root by listing its contents. */
  private S3AFileStatus resolveRootStatus(Path f) throws IOException {
    return resolveDirectoryStatus(f, "");
  }

  /** Resolves the status for the exact key without a trailing slash. */
  private S3AFileStatus resolveExactKeyStatus(Path f, String key) throws IOException {
    try {
      ObjectMetadata meta = s3.getObjectMetadata(bucket, key);
      statistics.incrementReadOps(1);
      return statusFromObjectMetadata(f, key, meta);
    } catch (AmazonServiceException e) {
      if (!isNotFound(e)) {
        printAmazonServiceException(e);
        throw e;
      }
    } catch (AmazonClientException e) {
      printAmazonClientException(e);
      throw e;
    }
    return null;
  }

  /** Builds a file status from object metadata for the exact key. */
  private S3AFileStatus statusFromObjectMetadata(Path f, String key, ObjectMetadata meta) {
    if (objectRepresentsDirectory(key, meta.getContentLength())) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Found exact file: fake directory");
      }
      return new S3AFileStatus(true, true,
          f.makeQualified(uri, workingDir));
    }
    if (LOG.isDebugEnabled()) {
      LOG.debug("Found exact file: normal file");
    }
    return new S3AFileStatus(meta.getContentLength(),
        dateToLong(meta.getLastModified()),
        f.makeQualified(uri, workingDir),
        getDefaultBlockSize(f.makeQualified(uri, workingDir)));
  }

  /** Resolves the status for the key with a trailing slash appended. */
  private S3AFileStatus resolveKeyWithSlashStatus(Path f, String key) throws IOException {
    if (key.endsWith("/")) {
      return null;
    }
    try {
      String newKey = key + "/";
      ObjectMetadata meta = s3.getObjectMetadata(bucket, newKey);
      statistics.incrementReadOps(1);
      return statusFromSlashMetadata(f, newKey, meta);
    } catch (AmazonServiceException e) {
      if (!isNotFound(e)) {
        printAmazonServiceException(e);
        throw e;
      }
    } catch (AmazonClientException e) {
      printAmazonClientException(e);
      throw e;
    }
    return null;
  }

  /** Builds a file status from object metadata for the slash-appended key. */
  private S3AFileStatus statusFromSlashMetadata(Path f, String key, ObjectMetadata meta) {
    if (objectRepresentsDirectory(key, meta.getContentLength())) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Found file (with /): fake directory");
      }
      return new S3AFileStatus(true, true, f.makeQualified(uri, workingDir));
    }
    LOG.warn("Found file (with /): real file? should not happen: {}", key);
    return new S3AFileStatus(meta.getContentLength(),
        dateToLong(meta.getLastModified()),
        f.makeQualified(uri, workingDir),
        getDefaultBlockSize(f.makeQualified(uri, workingDir)));
  }

  /** Resolves the status by listing the path as a directory prefix. */
  private S3AFileStatus resolveDirectoryStatus(Path f, String key) throws IOException {
    try {
      String prefix = ensureDirectoryPrefix(key);
      ListObjectsRequest request = buildListStatusRequest(prefix);
      request.setMaxKeys(1);

      ObjectListing objects = s3.listObjects(request);
      statistics.incrementReadOps(1);

      if (hasAnyResult(objects)) {
        logFoundAsDirectory(objects);
        return new S3AFileStatus(true, false,
            f.makeQualified(uri, workingDir));
      }
    } catch (AmazonServiceException e) {
      if (!isNotFound(e)) {
        printAmazonServiceException(e);
        throw e;
      }
    } catch (AmazonClientException e) {
      printAmazonClientException(e);
      throw e;
    }
    return null;
  }

  /** Returns true if the listing contains any common prefixes or object summaries. */
  private boolean hasAnyResult(ObjectListing objects) {
    if (!objects.getCommonPrefixes().isEmpty()) {
      return true;
    }
    return objects.getObjectSummaries().size() > 0;
  }

  /** Logs the contents of a directory listing at debug level. */
  private void logFoundAsDirectory(ObjectListing objects) {
    if (!LOG.isDebugEnabled()) {
      return;
    }
    LOG.debug("Found path as directory (with /): " +
        objects.getCommonPrefixes().size() + "/" +
        objects.getObjectSummaries().size());

    for (S3ObjectSummary summary : objects.getObjectSummaries()) {
      LOG.debug("Summary: " + summary.getKey() + " " + summary.getSize());
    }
    for (String prefix : objects.getCommonPrefixes()) {
      LOG.debug("Prefix: " + prefix);
    }
  }

  /** Returns true if the service exception indicates a missing object. */
  private boolean isNotFound(AmazonServiceException e) {
    return e.getStatusCode() == 404;
  }

  /**
   * The src file is on the local disk.  Add it to FS at
   * the given dst name.
   *
   * This version doesn't need to create a temporary file to calculate the md5.
   * Sadly this doesn't seem to be used by the shell cp :(
   *
   * delSrc indicates if the source should be removed
   * @param delSrc whether to delete the src
   * @param overwrite whether to overwrite an existing file
   * @param src path
   * @param dst path
   */
  @Override
  public void copyFromLocalFile(boolean delSrc, boolean overwrite, Path src,
      Path dst) throws IOException {
    String key = pathToKey(dst);

    if (fileExistsAndCannotOverwrite(dst, overwrite)) {
      throw new IOException(dst + " already exists");
    }
    if (LOG.isDebugEnabled()) {
      LOG.debug("Copying local file from " + src + " to " + dst);
    }

    // Since we have a local file, we don't need to stream into a temporary file
    LocalFileSystem local = getLocal(getConf());
    File srcfile = local.pathToFile(src);

    uploadFile(srcfile, key);

    // This will delete unnecessary fake parent directories
    finishedWrite(key);

    if (delSrc) {
      local.delete(src, false);
    }
  }

  /** Uploads a local file to S3 and waits for the upload to complete. */
  private void uploadFile(File srcfile, String key) throws IOException {
    PutObjectRequest putObjectRequest = buildPutObjectRequest(srcfile, key);
    Upload up = transfers.upload(putObjectRequest);
    up.addProgressListener(new ProgressOperationListener());
    try {
      up.waitForUploadResult();
      statistics.incrementWriteOps(1);
    } catch (InterruptedException e) {
      throw new IOException("Got interrupted, cancelling");
    }
  }

  /** Builds a PutObjectRequest for uploading a local file. */
  private PutObjectRequest buildPutObjectRequest(File srcfile, String key) {
    ObjectMetadata om = new ObjectMetadata();
    if (StringUtils.isNotBlank(serverSideEncryptionAlgorithm)) {
      om.setServerSideEncryption(serverSideEncryptionAlgorithm);
    }
    PutObjectRequest putObjectRequest = new PutObjectRequest(bucket, key, srcfile);
    putObjectRequest.setCannedAcl(cannedACL);
    putObjectRequest.setMetadata(om);
    return putObjectRequest;
  }

  /** Listener that records completed parts as write operations. */
  private final class ProgressOperationListener implements ProgressListener {
    @Override
    public void progressChanged(ProgressEvent progressEvent) {
      if (progressEvent.getEventCode() == ProgressEvent.PART_COMPLETED_EVENT_CODE) {
        statistics.incrementWriteOps(1);
      }
    }
  }

  @Override
  public void close() throws IOException {
    try {
      super.close();
    } finally {
      if (transfers != null) {
        transfers.shutdownNow(true);
        transfers = null;
      }
    }
  }

  /**
  * Override getCononicalServiceName because we don't support token in S3A
  */
  @Override
  public String getCanonicalServiceName() {
    // Does not support Token
    return null;
  }

  private void copyFile(String srcKey, String dstKey) throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("copyFile " + srcKey + " -> " + dstKey);
    }

    CopyObjectRequest copyObjectRequest = buildCopyObjectRequest(srcKey, dstKey);
    Copy copy = transfers.copy(copyObjectRequest);
    copy.addProgressListener(new ProgressOperationListener());
    try {
      copy.waitForCopyResult();
      statistics.incrementWriteOps(1);
    } catch (InterruptedException e) {
      throw new IOException("Got interrupted, cancelling");
    }
  }

  /** Builds a CopyObjectRequest for copying an S3 object. */
  private CopyObjectRequest buildCopyObjectRequest(String srcKey, String dstKey) {
    ObjectMetadata srcom = s3.getObjectMetadata(bucket, srcKey);
    ObjectMetadata dstom = srcom.clone();
    if (StringUtils.isNotBlank(serverSideEncryptionAlgorithm)) {
      dstom.setServerSideEncryption(serverSideEncryptionAlgorithm);
    }
    CopyObjectRequest copyObjectRequest = new CopyObjectRequest(bucket, srcKey, bucket, dstKey);
    copyObjectRequest.setCannedAccessControlList(cannedACL);
    copyObjectRequest.setNewObjectMetadata(dstom);
    return copyObjectRequest;
  }

  /** Returns true if the name represents a directory marker (trailing slash, zero size). */
  private boolean objectRepresentsDirectory(final String name, final long size) {
    if (name.isEmpty()) {
      return false;
    }
    if (name.charAt(name.length() - 1) != '/') {
      return false;
    }
    return size == 0L;
  }

  // Handles null Dates that can be returned by AWS
  private static long dateToLong(final Date date) {
    if (date == null) {
      return 0L;
    }
    return date.getTime();
  }

  public void finishedWrite(String key) throws IOException {
    deleteUnnecessaryFakeDirectories(keyToPath(key).getParent());
  }

  private void deleteUnnecessaryFakeDirectories(Path f) throws IOException {
    Path current = f;
    while (true) {
      String key = pathToKey(current);
      if (key.isEmpty()) {
        break;
      }

      deleteFakeDirectoryIfEmpty(current, key);

      if (current.isRoot()) {
        break;
      }
      current = current.getParent();
    }
  }

  /** Deletes a fake directory marker if the path is an empty directory. */
  private void deleteFakeDirectoryIfEmpty(Path f, String key) {
    try {
      S3AFileStatus status = getFileStatus(f);
      if (isEmptyDirectory(status)) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("Deleting fake directory " + key + "/");
        }
        s3.deleteObject(bucket, key + "/");
        statistics.incrementWriteOps(1);
      }
    } catch (FileNotFoundException | AmazonServiceException e) {
    }
  }

  private void createFakeDirectory(final String bucketName, final String objectName)
      throws AmazonClientException, AmazonServiceException {
    if (!objectName.endsWith("/")) {
      createEmptyObject(bucketName, objectName + "/");
    } else {
      createEmptyObject(bucketName, objectName);
    }
  }

  // Used to create an empty file that represents an empty directory
  private void createEmptyObject(final String bucketName, final String objectName)
      throws AmazonClientException, AmazonServiceException {
    final InputStream im = new InputStream() {
      @Override
      public int read() throws IOException {
        return -1;
      }
    };

    final ObjectMetadata om = new ObjectMetadata();
    om.setContentLength(0L);
    if (StringUtils.isNotBlank(serverSideEncryptionAlgorithm)) {
      om.setServerSideEncryption(serverSideEncryptionAlgorithm);
    }
    PutObjectRequest putObjectRequest = new PutObjectRequest(bucketName, objectName, im, om);
    putObjectRequest.setCannedAcl(cannedACL);
    s3.putObject(putObjectRequest);
    statistics.incrementWriteOps(1);
  }

  /**
   * Return the number of bytes that large input files should be optimally
   * be split into to minimize i/o time.
   * @deprecated use {@link #getDefaultBlockSize(Path)} instead
   */
  @Deprecated
  public long getDefaultBlockSize() {
    // default to 32MB: large enough to minimize the impact of seeks
    return getConf().getLong(FS_S3A_BLOCK_SIZE, DEFAULT_BLOCKSIZE);
  }

  private void printAmazonServiceException(AmazonServiceException ase) {
    LOG.info("Caught an AmazonServiceException, which means your request made it " +
        "to Amazon S3, but was rejected with an error response for some reason.");
    LOG.info("Error Message: " + ase.getMessage());
    LOG.info("HTTP Status Code: " + ase.getStatusCode());
    LOG.info("AWS Error Code: " + ase.getErrorCode());
    LOG.info("Error Type: " + ase.getErrorType());
    LOG.info("Request ID: " + ase.getRequestId());
    LOG.info("Class Name: " + ase.getClass().getName());
  }

  private void printAmazonClientException(AmazonClientException ace) {
    LOG.info("Caught an AmazonClientException, which means the client encountered " +
        "a serious internal problem while trying to communicate with S3, " +
        "such as not being able to access the network.");
    LOG.info("Error Message: {}" + ace, ace);
  }
}

