private ClientConfiguration createClientConfiguration(Configuration conf) {
  ClientConfiguration awsConf = new ClientConfiguration();
  awsConf.setMaxConnections(conf.getInt(MAXIMUM_CONNECTIONS, DEFAULT_MAXIMUM_CONNECTIONS));
  boolean secureConnections = conf.getBoolean(SECURE_CONNECTIONS, DEFAULT_SECURE_CONNECTIONS);
  Protocol protocol = secureConnections ? Protocol.HTTPS : Protocol.HTTP; // ternary. Replace.
  if (secureConnections) {
    awsConf.setProtocol(Protocol.HTTPS);
  } else {
    awsConf.setProtocol(Protocol.HTTP);
  }
  awsConf.setMaxErrorRetry(conf.getInt(MAX_ERROR_RETRIES, DEFAULT_MAX_ERROR_RETRIES));
  awsConf.setConnectionTimeout(conf.getInt(ESTABLISH_TIMEOUT, DEFAULT_ESTABLISH_TIMEOUT));
  awsConf.setSocketTimeout(conf.getInt(SOCKET_TIMEOUT, DEFAULT_SOCKET_TIMEOUT));
  configureProxy(awsConf, conf, secureConnections);
  return awsConf;
}

configureProxy:
private void configureProxy(ClientConfiguration awsConf, Configuration conf, boolean secureConnections) {
  String proxyHost = conf.getTrimmed(PROXY_HOST, "");
  int proxyPort = conf.getInt(PROXY_PORT, -1);
  if (proxyHost.isEmpty()) {
    if (proxyPort >= 0) {
      throwProxyError(PROXY_PORT + " set without " + PROXY_HOST);
    }
    return;
  }
  awsConf.setProxyHost(proxyHost);
  if (proxyPort < 0) {
    proxyPort = defaultProxyPort(secureConnections);
  }
  awsConf.setProxyPort(proxyPort);
  configureProxyCredentials(awsConf, conf);
  awsConf.setProxyDomain(conf.getTrimmed(PROXY_DOMAIN));
  awsConf.setProxyWorkstation(conf.getTrimmed(PROXY_WORKSTATION));
  logProxySettings(awsConf);
}

