private void initThreadPool(Configuration conf) {
  int maxThreads = conf.getInt(MAX_THREADS, DEFAULT_MAX_THREADS);
  int coreThreads = conf.getInt(CORE_THREADS, DEFAULT_CORE_THREADS);
  if (maxThreads == 0) {
    maxThreads = Runtime.getRuntime().availableProcessors() * 8;
  }
  if (coreThreads == 0) {
    coreThreads = Runtime.getRuntime().availableProcessors() * 8;
  }
  long keepAliveTime = conf.getLong(KEEPALIVE_TIME, DEFAULT_KEEPALIVE_TIME);
  int totalTasks = conf.getInt(MAX_TOTAL_TASKS, DEFAULT_MAX_TOTAL_TASKS);
  LinkedBlockingQueue<Runnable> workQueue = new LinkedBlockingQueue<>(maxThreads * totalTasks);
  threadPoolExecutor = new ThreadPoolExecutor(coreThreads, maxThreads, keepAliveTime, TimeUnit.SECONDS, workQueue, newDaemonThreadFactory("s3a-transfer-shared-"));
  threadPoolExecutor.allowCoreThreadTimeOut(true);
}

