private static int resolveProxyPort(int proxyPort, boolean secureConnections) {
  if (proxyPort >= 0) {
    return proxyPort;
  }
  if (secureConnections) {
    LOG.warn("Proxy host set without port. Using HTTPS default 443");
    return 443;
  }
  LOG.warn("Proxy host set without port. Using HTTP default 80");
  return 80;
}

private static void rejectMismatchedProxyCredentials(String proxyUsername, String proxyPassword) {
  if ((proxyUsername == null) == (proxyPassword == null)) {
    return;
  }
  String msg = "Proxy error: " + PROXY_USERNAME + " or " + PROXY_PASSWORD + " set without the other.";
  LOG.error(msg);
  throw new IllegalArgumentException(msg);
}

private static void rejectProxyPortWithoutHost(int proxyPort) {
  if (proxyPort < 0) {
    return;
  }
  String msg = "Proxy error: " + PROXY_PORT + " set without " + PROXY_HOST;
  LOG.error(msg);
  throw new IllegalArgumentException(msg);
}

private void logProxyConfiguration(ClientConfiguration awsConf) {
  if (LOG.isDebugEnabled()) {
    LOG.debug("Using proxy server {}:{} as user {} with password {} on domain {} as workstation {}", awsConf.getProxyHost(), awsConf.getProxyPort(), String.valueOf(awsConf.getProxyUsername()), awsConf.getProxyPassword(), awsConf.getProxyDomain(), awsConf.getProxyWorkstation());
  }
}

private void configureEndpoint(Configuration conf) {
  String endPoint = conf.getTrimmed(ENDPOINT, "");
  if (endPoint.isEmpty()) {
    return;
  }
  try {
    s3.setEndpoint(endPoint);
  } catch (IllegalArgumentException e) {
    String msg = "Incorrect endpoint: " + e.getMessage();
    LOG.error(msg);
    throw new IllegalArgumentException(msg, e);
  }
}

