private class ListFilesIterator implements RemoteIterator<LocatedFileStatus> {
  private final Stack<RemoteIterator<LocatedFileStatus>> itors =
      new Stack<RemoteIterator<LocatedFileStatus>>();
  private RemoteIterator<LocatedFileStatus> curItor;
  private LocatedFileStatus curFile;
  private final Path path;
  private final boolean recursive;

  ListFilesIterator(Path f, boolean recursive) throws IOException {
    this.path = f;
    this.recursive = recursive;
    this.curItor = FileContext.this.listLocatedStatus(f);
  }

  @Override
  public boolean hasNext() throws IOException {
    while (curFile == null) {
      if (curItor.hasNext()) {
        handleFileStat(curItor.next());
      } else if (!itors.empty()) {
        curItor = itors.pop();
      } else {
        return false;
      }
    }
    return true;
  }

  private void handleFileStat(LocatedFileStatus stat) throws IOException {
    if (stat.isFile()) {
      curFile = stat;
      return;
    }
    if (stat.isSymlink()) {
      FileStatus symstat = FileContext.this.getFileStatus(stat.getSymlink());
      if (shouldTraverse(symstat)) {
        descend(stat.getPath());
      }
      return;
    }
    if (recursive) {
      descend(stat.getPath());
    }
  }

  private boolean shouldTraverse(FileStatus status) {
    return status.isFile() || (recursive && status.isDirectory());
  }

  private void descend(Path path) throws IOException {
    itors.push(curItor);
    curItor = FileContext.this.listLocatedStatus(path);
  }

  @Override
  public LocatedFileStatus next() throws IOException {
    if (hasNext()) {
      LocatedFileStatus result = curFile;
      curFile = null;
      return result;
    }
    throw new java.util.NoSuchElementException("No more entry in " + path);
  }
}
