    /**
     * Iterator that traverses the file tree rooted at a path, yielding
     * {@link LocatedFileStatus} objects. Symbolic links are followed and,
     * when recursive, directories are descended.
     */
    private class LocatedFileStatusIterator
        implements RemoteIterator<LocatedFileStatus> {
      private final boolean recursive;
      private final Path root;
      private final Stack<RemoteIterator<LocatedFileStatus>> itors =
          new Stack<RemoteIterator<LocatedFileStatus>>();
      private RemoteIterator<LocatedFileStatus> curItor;
      private LocatedFileStatus curFile;

      LocatedFileStatusIterator(final Path f, final boolean recursive)
          throws IOException {
        this.recursive = recursive;
        this.root = f;
        this.curItor = listLocatedStatus(f);
      }

      @Override
      public boolean hasNext() throws IOException {
        while (curFile == null) {
          if (curItor.hasNext()) {
            processStatus(curItor.next());
          } else if (!itors.empty()) {
            curItor = itors.pop();
          } else {
            return false;
          }
        }
        return true;
      }

      private void processStatus(LocatedFileStatus stat) throws IOException {
        if (stat.isFile()) {
          curFile = stat;
        } else if (stat.isSymlink()) {
          processSymlink(stat);
        } else if (recursive) {
          enterDirectory(stat);
        }
      }

      private void processSymlink(LocatedFileStatus stat) throws IOException {
        FileStatus target = FileContext.this.getFileStatus(stat.getSymlink());
        if (shouldFollowSymlink(target)) {
          enterDirectory(stat);
        }
      }

      private boolean shouldFollowSymlink(FileStatus target) {
        return target.isFile() || (recursive && target.isDirectory());
      }

      private void enterDirectory(LocatedFileStatus stat) throws IOException {
        itors.push(curItor);
        curItor = listLocatedStatus(stat.getPath());
      }

      @Override
      public LocatedFileStatus next() throws IOException {
        if (hasNext()) {
          LocatedFileStatus result = curFile;
          curFile = null;
          return result;
        }
        throw new java.util.NoSuchElementException("No more entry in " + root);
      }
    }

    /**
     * <p>Return all the files that match filePattern and are not checksum
     * files. Results are sorted by their names.
     * 
     * <p>
     * A filename pattern is composed of <i>regular</i> characters and
     * <i>special pattern matching</i> characters, which are:
     *
     * <dl>
     *  <dd>
     *   <dl>
     *    <p>
     *    <dt> <tt> ? </tt>
     *    <dd> Matches any single character.
     *
     *    <p>
     *    <dt> <tt> * </tt>
     *    <dd> Matches zero or more characters.
     *
     *    <p>
     *    <dt> <tt> [<i>abc</i>] </tt>
     *    <dd> Matches a single character from character set
     *     <tt>{<i>a,b,c</i>}</tt>.
     *
     *    <p>
     *    <dt> <tt> [<i>a</i>-<i>b</i>] </tt>
     *    <dd> Matches a single character from the character range
     *     <tt>{<i>a...b</i>}</tt>. Note: character <tt><i>a</i></tt> must be
     *     lexicographically less than or equal to character <tt><i>b</i></tt>.
     *
     *    <p>
     *    <dt> <tt> [^<i>a</i>] </tt>
     *    <dd> Matches a single char that is not from character set or range
     *     <tt>{<i>a</i>}</tt>.  Note that the <tt>^</tt> character must occur
