  /**
   * Iterator that recursively lists files with their block locations.
   * Directories are traversed depth-first when recursive listing is enabled.
   * Symbolic links are followed and their targets are listed as appropriate.
   */
  private static class LocatedFileStatusIterator
      implements RemoteIterator<LocatedFileStatus> {
    private final FileContext fc;
    private final Path path;
    private final boolean recursive;
    private final Stack<RemoteIterator<LocatedFileStatus>> itors =
        new Stack<RemoteIterator<LocatedFileStatus>>();
    private RemoteIterator<LocatedFileStatus> curItor;
    private LocatedFileStatus curFile;

    LocatedFileStatusIterator(FileContext fc, Path path, boolean recursive)
        throws IOException {
      this.fc = fc;
      this.path = path;
      this.recursive = recursive;
      this.curItor = fc.listLocatedStatus(path);
    }

    @Override
    public boolean hasNext() throws IOException {
      while (curFile == null) {
        if (curItor.hasNext()) {
          handleFileStat(curItor.next());
        } else if (!itors.empty()) {
          curItor = itors.pop();
        } else {
          return false;
        }
      }
      return true;
    }

    /**
     * Process a returned status: files are returned next, directories are
     * queued for traversal when recursive, and symlinks are resolved and
     * handled according to their target type.
     */
    private void handleFileStat(LocatedFileStatus stat) throws IOException {
      if (stat.isFile()) {
        curFile = stat;
      } else if (stat.isSymlink()) {
        FileStatus symstat = fc.getFileStatus(stat.getSymlink());
        if (symstat.isFile() || (recursive && symstat.isDirectory())) {
          itors.push(curItor);
          curItor = fc.listLocatedStatus(stat.getPath());
        }
      } else if (recursive) {
        itors.push(curItor);
        curItor = fc.listLocatedStatus(stat.getPath());
      }
    }

    @Override
    public LocatedFileStatus next() throws IOException {
      if (hasNext()) {
        LocatedFileStatus result = curFile;
        curFile = null;
        return result;
      }
      throw new java.util.NoSuchElementException("No more entry in " + path);
    }
  }

