    /**
     * List the statuses and block locations of the files in the given path.
     * 
     * If the path is a directory, 
     *   if recursive is false, returns files in the directory;
     *   if recursive is true, return files in the subtree rooted at the path.
     *   The subtree is traversed in the depth-first order.
     * If the path is a file, return the file's status and block locations.
     * Files across symbolic links are also returned.
     * 
     * @param f is the path
     * @param recursive if the subdirectories need to be traversed recursively
     *
     * @return an iterator that traverses statuses of the files
     * If any IO exception (for example a sub-directory gets deleted while
     * listing is being executed), next() or hasNext() of the returned iterator
     * may throw a RuntimeException with the IO exception as the cause.
     *
     * @throws AccessControlException If access is denied
     * @throws FileNotFoundException If <code>f</code> does not exist
     * @throws UnsupportedFileSystemException If file system for <code>f</code>
     *         is not supported
     * @throws IOException If an I/O error occurred
     * 
     * Exceptions applicable to file systems accessed over RPC:
     * @throws RpcClientException If an exception occurred in the RPC client
     * @throws RpcServerException If an exception occurred in the RPC server
     * @throws UnexpectedServerException If server implementation throws 
     *           undeclared exception to RPC server
     */
    public RemoteIterator<LocatedFileStatus> listFiles(
        final Path f, final boolean recursive) throws AccessControlException,
        FileNotFoundException, UnsupportedFileSystemException, 
        IOException {
      return new RemoteIterator<LocatedFileStatus>() {
        private Stack<RemoteIterator<LocatedFileStatus>> itors = 
          new Stack<RemoteIterator<LocatedFileStatus>>();
        private RemoteIterator<LocatedFileStatus> curItor = listLocatedStatus(f);
        private LocatedFileStatus curFile;

        /**
         * Returns <tt>true</tt> if the iterator has more files.
         *
         * @return <tt>true</tt> if the iterator has more files.
         * @throws AccessControlException if not allowed to access next
         *                                file's status or locations
         * @throws FileNotFoundException if next file does not exist any more
         * @throws UnsupportedFileSystemException if next file's 
         *                                        fs is unsupported
         * @throws IOException for all other IO errors
         *                     for example, NameNode is not avaialbe or
         *                     NameNode throws IOException due to an error
         *                     while getting the status or block locations
         */
        @Override
        public boolean hasNext() throws IOException {
          findNextFile();
          return curFile != null;
        }

        /**
         * Advances the iterator until the next file is found or no entries
         * remain.
         *
         * @throws IOException if an I/O error occurs while listing
         */
        private void findNextFile() throws IOException {
          while (curFile == null) {
            if (curItor.hasNext()) {
              processStatus(curItor.next());
            } else if (!itors.empty()) {
              curItor = itors.pop();
            } else {
              return;
            }
          }
        }

        /**
         * Dispatches the given status to the appropriate handler based on its
         * type.
         *
         * @param stat the status to process
         * @throws IOException if an I/O error occurs while resolving
         *                     symlinks or listing directories
         */
        private void processStatus(LocatedFileStatus stat) throws IOException {
          if (stat.isFile()) {
            handleFile(stat);
          } else if (stat.isSymlink()) {
            handleSymlink(stat);
          } else if (recursive) {
            descendIntoDirectory(stat.getPath());
          }
        }

        /**
         * Records the given file status as the next result to return.
         *
         * @param stat the file status
         */
        private void handleFile(LocatedFileStatus stat) {
          curFile = stat;
        }

        /**
         * Resolves the given symlink and, if appropriate, descends into it.
         *
         * @param stat the symlink status
         * @throws IOException if the symlink target cannot be resolved
         */
        private void handleSymlink(LocatedFileStatus stat) throws IOException {
          FileStatus target = FileContext.this.getFileStatus(stat.getSymlink());
          if (target.isFile() || (recursive && target.isDirectory())) {
            descendIntoDirectory(stat.getPath());
          }
        }

        /**
         * Pushes the current iterator and starts iterating the given directory.
         *
         * @param dir the directory path to list
         * @throws IOException if the directory cannot be listed
         */
        private void descendIntoDirectory(Path dir) throws IOException {
          itors.push(curItor);
          curItor = listLocatedStatus(dir);
        }

        /**
         * Returns the next file's status with its block locations
         *
         * @throws AccessControlException if not allowed to access next
         *                                file's status or locations
         * @throws FileNotFoundException if next file does not exist any more
         * @throws UnsupportedFileSystemException if next file's 
         *                                        fs is unsupported
         * @throws IOException for all other IO errors
         *                     for example, NameNode is not avaialbe or
         *                     NameNode throws IOException due to an error
         *                     while getting the status or block locations
         */
        @Override
        public LocatedFileStatus next() throws IOException {
          if (hasNext()) {
            LocatedFileStatus result = curFile;
            curFile = null;
            return result;
          } 
          throw new java.util.NoSuchElementException("No more entry in " + f);
        }
      };
    }

