       *
       * @param f the path to list
       * @param recursive whether to recurse into subdirectories
       * @throws IOException if the initial listing fails
       */
      ListFilesIterator(final Path f, final boolean recursive) throws IOException {
        this.recursive = recursive;
        this.rootPath = f;
        this.curItor = listLocatedStatus(f);
      }

      /**
