       * appropriate; directories are traversed when recursive is enabled.
       *
       * @param stat the status to process
       * @throws IOException if resolving or listing fails
       */
      private void processStatus(LocatedFileStatus stat) throws IOException {
        if (stat.isFile()) {
          curFile = stat;
        } else if (stat.isSymlink()) {
          processSymlink(stat);
        } else if (recursive) {
          descendIntoDirectory(stat.getPath());
        }
      }

      /**
       * Resolves a symbolic link and traverses it when the target is a file or,
       * if recursive, a directory.
       *
       * @param stat the symlink status to process
       * @throws IOException if resolving or listing fails
       */
      private void processSymlink(LocatedFileStatus stat) throws IOException {
        FileStatus symstat = FileContext.this.getFileStatus(stat.getSymlink());
        if (symstat.isFile() || (recursive && symstat.isDirectory())) {
          descendIntoDirectory(stat.getPath());
        }
      }

