  /**
   * Verify that the edit log is in the expected state.
   *
   * @param expected the state that the edit log must be in
   */
  private void checkState(State expected) {
    Preconditions.checkState(state == expected, BAD_STATE_FORMAT, state);
  }

  /**
   * Initialize the output stream for logging, opening the first
   * log segment.
   */
  synchronized void openForWrite() throws IOException {
    checkState(State.BETWEEN_LOG_SEGMENTS);

    long segmentTxId = getLastWrittenTxId() + 1;
    // Safety check: we should never start a segment if there are
    // newer txids readable.
    List<EditLogInputStream> streams = new ArrayList<EditLogInputStream>();
    journalSet.selectInputStreams(streams, segmentTxId, true);
    if (!streams.isEmpty()) {
      String error = String.format("Cannot start writing at txid %s " +
        "when there is a stream available for read: %s",
        segmentTxId, streams.get(0));
      IOUtils.cleanup(LOG, streams.toArray(new EditLogInputStream[0]));
      throw new IllegalStateException(error);
    }

    startLogSegment(segmentTxId, true);
    assert state == State.IN_SEGMENT : "Bad state: " + state;
  }

  /**
   * @return true if the log is currently open in write mode, regardless
   * of whether it actually has an open segment.
   */
  synchronized boolean isOpenForWrite() {
    return state == State.IN_SEGMENT ||
      state == State.BETWEEN_LOG_SEGMENTS;
  }

  /**
   * @return true if the log is open in write mode and has a segment open
   * ready to take edits.
   */
  synchronized boolean isSegmentOpen() {
    return state == State.IN_SEGMENT;
  }

  /**
   * @return true if the log is open in read mode.
   */
  public synchronized boolean isOpenForRead() {
    return state == State.OPEN_FOR_READING;
  }

  /**
   * Shutdown the file store.
   */
  synchronized void close() {
    if (state == State.CLOSED) {
      LOG.debug("Closing log when already closed");
      return;
    }

    try {
      if (state == State.IN_SEGMENT) {
        assert editLogStream != null;
        waitForSyncToFinish();
        endCurrentLogSegment(true);
      }
    } finally {
      if (journalSet != null && !journalSet.isEmpty()) {
        try {
          synchronized(journalSetLock) {
            journalSet.close();
          }
        } catch (IOException ioe) {
          LOG.warn("Error closing journalSet", ioe);
        }
      }
      state = State.CLOSED;
    }
  }


  /**
   * Format all configured journals which are not file-based.
   * 
   * File-based journals are skipped, since they are formatted by the
   * Storage format code.
   */
  synchronized void formatNonFileJournals(NamespaceInfo nsInfo) throws IOException {
    checkState(State.BETWEEN_LOG_SEGMENTS);

    for (JournalManager jm : journalSet.getJournalManagers()) {
      if (!(jm instanceof FileJournalManager)) {
        jm.format(nsInfo);
      }
    }
  }

  synchronized List<FormatConfirmable> getFormatConfirmables() {
    checkState(State.BETWEEN_LOG_SEGMENTS);

    List<FormatConfirmable> ret = Lists.newArrayList();
    for (final JournalManager jm : journalSet.getJournalManagers()) {
      // The FJMs are confirmed separately since they are also
      // StorageDirectories
      if (!(jm instanceof FileJournalManager)) {
        ret.add(jm);
      }
    }
    return ret;
  }

  /**
   * Write an operation to the edit log. Do not sync to persistent
   * store yet.
   */
  void logEdit(final FSEditLogOp op) {
    synchronized (this) {
      assert isOpenForWrite() :
        "bad state: " + state;

      // wait if an automatic sync is scheduled
      waitIfAutoSyncScheduled();

      long start = beginTransaction();
      op.setTransactionId(txid);

      try {
        editLogStream.write(op);
      } catch (IOException ex) {
        // All journals failed, it is handled in logSync.
      } finally {
        op.reset();
      }

      endTransaction(start);

      // check if it is time to schedule an automatic sync
      if (!shouldForceSync()) {
        return;
      }
      isAutoSyncScheduled = true;
    }

    // sync buffered edit log entries to persistent store
    logSync();
  }

  /**
   * Wait if an automatic sync is scheduled
   */
  synchronized void waitIfAutoSyncScheduled() {
    try {
      while (isAutoSyncScheduled) {
        this.wait(1000);
      }
    } catch (InterruptedException e) {
    }
  }

  /**
   * Signal that an automatic sync scheduling is done if it is scheduled
   */
  synchronized void doneWithAutoSyncScheduling() {
    if (isAutoSyncScheduled) {
      isAutoSyncScheduled = false;
      notifyAll();
    }
  }

  /**
   * Check if should automatically sync buffered edits to 
   * persistent store
   * 
   * @return true if any of the edit stream says that it should sync
   */
  private boolean shouldForceSync() {
    return editLogStream.shouldForceSync();
  }

  private long beginTransaction() {
    assert Thread.holdsLock(this);
    // get a new transactionId
    txid++;

    //
    // record the transactionId when new data was written to the edits log
    //
    TransactionId id = myTransactionId.get();
    id.txid = txid;
    return monotonicNow();
  }

  private void endTransaction(long start) {
    assert Thread.holdsLock(this);

    // update statistics
    long end = monotonicNow();
    numTransactions++;
    totalTimeTransactions += (end-start);
    if (metrics != null) // Metrics is non-null only when used inside name node
      metrics.addTransaction(end-start);
  }

  /**
   * Return the transaction ID of the last transaction written to the log.
   */
  public synchronized long getLastWrittenTxId() {
    return txid;
  }

  /**
   * @return the first transaction ID in the current log segment
   */
  synchronized long getCurSegmentTxId() {
    checkState(State.IN_SEGMENT);
    return curSegmentTxId;
  }

  /**
   * Set the transaction ID to use for the next transaction written.
   */
  synchronized void setNextTxId(long nextTxId) {
    Preconditions.checkArgument(synctxid <= txid &&
       nextTxId >= txid,
       "May not decrease txid." +
      " synctxid=%s txid=%s nextTxId=%s",
      synctxid, txid, nextTxId);

    txid = nextTxId - 1;
  }

  /**
   * Blocks until all ongoing edits have been synced to disk.
   * This differs from logSync in that it waits for edits that have been
   * written by other threads, not just edits from the calling thread.
   *
   * NOTE: this should be done while holding the FSNamesystem lock, or
   * else more operations can start writing while this is in progress.
   */
  void logSyncAll() {
    // Record the most recent transaction ID as our own id
    synchronized (this) {
      TransactionId id = myTransactionId.get();
      id.txid = txid;
    }
    // Then make sure we're synced up to this point
    logSync();
  }

  /** Context describing a single log sync operation. */
  private static class SyncContext {
    final long syncStart;
    final EditLogOutputStream logStream;

    SyncContext(long syncStart, EditLogOutputStream logStream) {
      this.syncStart = syncStart;
      this.logStream = logStream;
    }
  }

  /**
   * Prepare for a log sync.
   *
   * @param mytxid the transaction ID that must be synced
   * @return a context describing the sync if this thread must perform it,
   *         or null if the relevant transactions have already been synced
   */
  private SyncContext beginLogSync(long mytxid) {
    synchronized (this) {
      try {
        printStatistics(false);

        // if somebody is already syncing, then wait
        while (mytxid > synctxid && isSyncRunning) {
          try {
            wait(1000);
          } catch (InterruptedException ie) {
          }
        }

        //
        // If this transaction was already flushed, then nothing to do
        //
        if (mytxid <= synctxid) {
          numTransactionsBatchedInSync++;
          if (metrics != null) {
            // Metrics is non-null only when used inside name node
            metrics.incrTransactionsBatchedInSync();
          }
          return null;
        }

        // now, this thread will do the sync
        long syncStart = txid;
        isSyncRunning = true;

        // swap buffers
        try {
          if (journalSet.isEmpty()) {
            throw new IOException("No journals available to flush");
          }
          editLogStream.setReadyToFlush();
        } catch (IOException e) {
          throw newSyncFailure(
              "Could not sync enough journals to persistent storage due to "
              + e.getMessage() + ". ", e);
        }

        // editLogStream may become null, so store a local variable for flush.
        return new SyncContext(syncStart, editLogStream);
      } finally {
        // Prevent RuntimeException from blocking other log edit write
        doneWithAutoSyncScheduling();
      }
    }
  }

  /**
   * Flush the prepared edit log buffers to persistent storage.
   *
   * @param ctx the sync context returned by beginLogSync
   */
  private void flushLogSync(SyncContext ctx) {
    long start = monotonicNow();
    try {
      if (ctx.logStream != null) {
        ctx.logStream.flush();
      }
    } catch (IOException ex) {
      synchronized (this) {
        throw newSyncFailure(
            "Could not sync enough journals to persistent storage. ", ex);
      }
    }
    long elapsed = monotonicNow() - start;

    if (metrics != null) { // Metrics non-null only when used inside name node
      metrics.addSync(elapsed);
    }
  }

  /**
   * Complete a log sync by updating the synced transaction ID and
   * notifying waiting threads.
   *
   * @param ctx the sync context, or null if no sync was performed
   */
  private void finishLogSync(SyncContext ctx) {
    synchronized (this) {
      if (ctx != null) {
        synctxid = ctx.syncStart;
        isSyncRunning = false;
      }
      this.notifyAll();
    }
  }

  /**
   * Report a fatal sync failure, clean up the journal set, and terminate.
   * The returned exception is only used so that callers can write
   * {@code throw newSyncFailure(...)}; this method never returns normally.
   *
   * @param messagePrefix prefix to prepend to the fatal message
   * @param e the IOException that caused the failure
   * @return never returned
   */
  private RuntimeException newSyncFailure(String messagePrefix, IOException e) {
    String msg = messagePrefix + "Unsynced transactions: " + (txid - synctxid);
    LOG.fatal(msg, new Exception());
    synchronized (journalSetLock) {
      IOUtils.cleanup(LOG, journalSet);
    }
    terminate(1, msg);
    throw new AssertionError("unreachable");
  }

  /**
   * Sync all modifications done by this thread.
   *
   * The internal concurrency design of this class is as follows:
   *   - Log items are written synchronized into an in-memory buffer,
   *     and each assigned a transaction ID.
   *   - When a thread (client) would like to sync all of its edits, logSync()
   *     uses a ThreadLocal transaction ID to determine what edit number must
   *     be synced to.
   *   - The isSyncRunning volatile boolean tracks whether a sync is currently
   *     under progress.
   *
   * The data is double-buffered within each edit log implementation so that
   * in-memory writing can occur in parallel with the on-disk writing.
   *
   * Each sync occurs in three steps:
   *   1. synchronized, it swaps the double buffer and sets the isSyncRunning
   *      flag.
   *   2. unsynchronized, it flushes the data to storage
   *   3. synchronized, it resets the flag and notifies anyone waiting on the
   *      sync.
   *
   * The lack of synchronization on step 2 allows other threads to continue
   * to write into the memory buffer while the sync is in progress.
   * Because this step is unsynchronized, actions that need to avoid
   * concurrency with sync() should be synchronized and also call
   * waitForSyncToFinish() before assuming they are running alone.
   */
  public void logSync() {
    long mytxid = myTransactionId.get().txid;
    SyncContext ctx = beginLogSync(mytxid);
    try {
      if (ctx != null) {
        flushLogSync(ctx);
      }
    } finally {
      finishLogSync(ctx);
    }
  }

  //
  // print statistics every 1 minute.
  //
  private void printStatistics(boolean force) {
    long now = monotonicNow();
    if (lastPrintTime + 60000 > now && !force) {
      return;
    }
    lastPrintTime = now;
    StringBuilder buf = new StringBuilder();
    buf.append("Number of transactions: ");
    buf.append(numTransactions);
    buf.append(" Total time for transactions(ms): ");
    buf.append(totalTimeTransactions);
    buf.append(" Number of transactions batched in Syncs: ");
    buf.append(numTransactionsBatchedInSync);
    buf.append(" Number of syncs: ");
    buf.append(editLogStream.getNumSync());
    buf.append(" SyncTimes(ms): ");
    buf.append(journalSet.getSyncTimes());
    LOG.info(buf);
  }

