   * empty directories, symlinks to directories and non-empty directories.
   *
   * @param file the file or directory to delete
   * @param tryGrantPermissions if 'true', try grant +rwx permissions before
   *        deleting non-empty directories
   * @return true on success, false on failure
   */
  private static boolean deleteContent(final File file, final boolean tryGrantPermissions) {
    if (file.isFile()) {
      // normal file or symlink to another file
      return deleteImpl(file, true);
    }

    // Either directory or symlink to another directory.
    // Try deleting the directory as this might be a symlink or empty directory.
    if (deleteImpl(file, false)) {
      return true;
    }

    // if not an empty directory or symlink let fullyDelete handle it.
    return fullyDelete(file, tryGrantPermissions);
  }

  /**
