```
public static boolean fullyDeleteContents(final File dir, final boolean tryGrantPermissions) {
    if (tryGrantPermissions) {
      // to be able to list the dir and delete files from it
      // we must grant the dir rwx permissions:
      grantPermissions(dir);
    }
    final File[] contents = dir.listFiles();
    if (isContentsMissing(contents)) {
      return true;
    }
    return deleteDirectoryContents(contents, tryGrantPermissions);
  }

  /**
   * Returns true if the directory listing is null, indicating the directory
   * could not be read or is not a directory.
   */
  private static boolean isContentsMissing(final File[] contents) {
    return contents == null;
  }

  /**
   * Deletes each entry in the provided directory listing. Returns true only if
   * every entry was deleted successfully.
   */
  private static boolean deleteDirectoryContents(final File[] contents,
      final boolean tryGrantPermissions) {
    boolean deletionSucceeded = true;
    for (File content : contents) {
      if (!deleteDirectoryEntry(content, tryGrantPermissions)) {
        deletionSucceeded = false;
      }
    }
    return deletionSucceeded;
  }

  /**
   * Deletes a single directory entry. Returns true if the entry was deleted
   * successfully, false otherwise.
   */
  private static boolean deleteDirectoryEntry(final File entry,
      final boolean tryGrantPermissions) {
    if (entry.isFile()) {
      return deleteFileEntry(entry);
    }
    return deleteDirectoryEntryRecursive(entry, tryGrantPermissions);
  }

  /**
   * Deletes a regular file or symlink to a file. Returns true if the file
   * was deleted successfully.
   */
  private static boolean deleteFileEntry(final File file) {
    return deleteImpl(file, true);
  }

  /**
   * Deletes a directory entry that is not a regular file. First attempts a
   * direct deletion (which succeeds for symlinks and empty directories), then
   * falls back to recursive deletion.
   */
  private static boolean deleteDirectoryEntryRecursive(final File entry,
      final boolean tryGrantPermissions) {
    if (deleteImpl(entry, false)) {
      return true;
    }
    return fullyDelete(entry, tryGrantPermissions);
  }
```

