  private static boolean deleteDirectoryContents(final File dir, final boolean tryGrantPermissions) {
    final File[] contents = dir.listFiles();
    if (isMissingContents(contents)) {
      return true;
    }
    return deleteAllContents(contents, tryGrantPermissions);
  }

  /**
