   * @return true if every entry was deleted, false otherwise
   */
  private static boolean deleteAllContents(final File[] contents, final boolean tryGrantPermissions) {
    boolean deletionSucceeded = true;
    for (int i = 0; i < contents.length; i++) {
      if (!deleteContent(contents[i], tryGrantPermissions)) {
        deletionSucceeded = false;
      }
    }
    return deletionSucceeded;
  }

