public COMMIT_STATUS checkCommit(DFSClient dfsClient, long commitOffset,
    Channel channel, int xid, Nfs3FileAttributes preOpAttr, boolean fromRead) {
  CommitRequestContext ctx = new CommitRequestContext.Builder()
      .withCommitOffset(commitOffset)
      .withChannel(channel)
      .withXid(xid)
      .withPreOpAttr(preOpAttr)
      .withFromRead(fromRead)
      .build();
  return checkCommit(dfsClient, ctx);
}

private COMMIT_STATUS checkCommit(DFSClient dfsClient, CommitRequestContext ctx) {
  if (!ctx.fromRead) {
    Preconditions.checkState(ctx.channel != null && ctx.preOpAttr != null);
    updateLastAccessTime();
  }
  Preconditions.checkState(ctx.commitOffset >= 0);

  COMMIT_STATUS ret = checkCommitInternal(ctx);
  if (LOG.isDebugEnabled()) {
    LOG.debug("Got commit status: " + ret.name());
  }
  if (ret == COMMIT_STATUS.COMMIT_DO_SYNC
      || ret == COMMIT_STATUS.COMMIT_FINISHED) {
    try {
      fos.hsync(EnumSet.of(SyncFlag.UPDATE_LENGTH));
      ret = COMMIT_STATUS.COMMIT_FINISHED;
    } catch (ClosedChannelException cce) {
      if (pendingWrites.isEmpty()) {
        ret = COMMIT_STATUS.COMMIT_FINISHED;
      } else {
        ret = COMMIT_STATUS.COMMIT_ERROR;
      }
    } catch (IOException e) {
      LOG.error("Got stream error during data sync: " + e);
      ret = COMMIT_STATUS.COMMIT_ERROR;
    }
  }
  return ret;
}
