public void receivedNewWrite(DFSClient dfsClient, WRITE3Request request,
    Channel channel, int xid, AsyncDataService asyncDataService,
    IdMappingServiceProvider iug) {
  WriteRequestContext ctx = new WriteRequestContext.Builder()
      .withDfsClient(dfsClient)
      .withRequest(request)
      .withChannel(channel)
      .withXid(xid)
      .withAsyncDataService(asyncDataService)
      .withIug(iug)
      .build();
  receivedNewWrite(ctx);
}

private void receivedNewWrite(WriteRequestContext ctx) {
  if (!activeState) {
    sendInactiveWriteResponse(ctx);
    return;
  }
  updateLastAccessTime();
  WriteCtx existing = checkRepeatedWriteRequest(ctx.request, ctx.channel, ctx.xid);
  if (existing != null) {
    handleRepeatedWrite(ctx, existing);
  } else {
    receivedNewWriteInternal(ctx);
  }
}

private void sendInactiveWriteResponse(WriteRequestContext ctx) {
  LOG.info("OpenFileCtx is inactive, fileId: "
      + ctx.request.getHandle().getFileId());
  WccData fileWcc = new WccData(latestAttr.getWccAttr(), latestAttr);
  WRITE3Response response = new WRITE3Response(Nfs3Status.NFS3ERR_IO,
      fileWcc, 0, ctx.request.getStableHow(), Nfs3Constant.WRITE_COMMIT_VERF);
  Nfs3Utils.writeChannel(ctx.channel,
      response.serialize(new XDR(), ctx.xid, new VerifierNone()),
      ctx.xid);
}

private void handleRepeatedWrite(WriteRequestContext ctx, WriteCtx existing) {
  if (!existing.getReplied()) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Repeated write request which hasn't been served: xid="
          + ctx.xid + ", drop it.");
    }
  } else {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Repeated write request which is already served: xid="
          + ctx.xid + ", resend response.");
    }
    WccData fileWcc = new WccData(latestAttr.getWccAttr(), latestAttr);
    WRITE3Response response = new WRITE3Response(Nfs3Status.NFS3_OK,
        fileWcc, ctx.request.getCount(), ctx.request.getStableHow(),
        Nfs3Constant.WRITE_COMMIT_VERF);
    Nfs3Utils.writeChannel(ctx.channel, response.serialize(
        new XDR(), ctx.xid, new VerifierNone()), ctx.xid);
  }
}
