private <M extends HttpMethod> int exec(M method) throws IOException {
  final HttpClient client = createHttpClient();
  int statusCode = execWithDebugOutput(method, client);
  statusCode = tryKeystoneAuthentication(method, statusCode, client);
  statusCode = reauthenticateIfUnauthorized(method, statusCode, client);
  return statusCode;
}

private HttpClient createHttpClient() {
  final HttpClient client = new HttpClient();
  if (proxyHost != null) {
    client.getParams().setParameter(ConnRoutePNames.DEFAULT_PROXY, new HttpHost(proxyHost, proxyPort));
  }
  return client;
}

private <M extends HttpMethod> int tryKeystoneAuthentication(M method, int statusCode, HttpClient client) throws IOException {
  if ((statusCode == HttpStatus.SC_UNAUTHORIZED || statusCode == HttpStatus.SC_BAD_REQUEST)
      && method instanceof AuthPostMethod
      && !useKeystoneAuthentication
      && keystoneAuthRequest != null) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Operation failed with status " + method.getStatusCode() + " attempting keystone auth");
    }
    useKeystoneAuthentication = true;
    final AuthPostMethod authentication = (AuthPostMethod) method;
    authentication.setRequestEntity(getAuthenticationRequst(keystoneAuthRequest));
    return execWithDebugOutput(method, client);
  }
  return statusCode;
}

private <M extends HttpMethod> int reauthenticateIfUnauthorized(M method, int statusCode, HttpClient client) throws IOException {
  if (statusCode == HttpStatus.SC_UNAUTHORIZED) {
    if (method instanceof AuthPostMethod) {
      throw new SwiftAuthenticationFailedException(authRequest.toString(), "auth", authUri, method);
    }
    if (LOG.isDebugEnabled()) {
      LOG.debug("Reauthenticating");
    }
    authenticate();
    if (LOG.isDebugEnabled()) {
      LOG.debug("Retrying original request");
    }
    return execWithDebugOutput(method, client);
  }
  return statusCode;
}

