private static String buildDirectoryQueryURI(String endpoint, SwiftObjectPath path, boolean listDeep) {
  StringBuilder dataLocationURI = new StringBuilder(endpoint);
  String object = path.getObject();
  if (object.startsWith("/")) {
    object = object.substring(1);
  }
  if (!object.endsWith("/")) {
    object = object.concat("/");
  }
  if (object.equals("/")) {
    object = "";
  }
  dataLocationURI.append("/").append(path.getContainer()).append("/?prefix=").append(object).append("&format=json");
  if (!listDeep) {
    dataLocationURI.append("&delimiter=/");
  }
  return dataLocationURI.toString();
}

