private static final class ExceptionFactory {
  static IOException createException(URI uri, HttpMethod method, int statusCode, AccessToken token) {
    String errorMessage = formatErrorMessage(uri, method, statusCode);
    if (LOG.isDebugEnabled()) {
      LOG.debug(errorMessage);
    }
    switch (statusCode) {
      case SC_NOT_FOUND:
        return new FileNotFoundException("Operation " + method.getName() + " on " + uri);
      case SC_BAD_REQUEST:
        return new SwiftBadRequestException("Bad request against " + uri, method.getName(), uri, method);
      case SC_REQUESTED_RANGE_NOT_SATISFIABLE:
        return buildRangeException(method);
      case SC_UNAUTHORIZED:
        return new SwiftAuthenticationFailedException("Operation not authorized- current access token =" + token, method.getName(), uri, method);
      case SwiftProtocolConstants.SC_TOO_MANY_REQUESTS_429:
      case SwiftProtocolConstants.SC_THROTTLED_498:
        return new SwiftThrottledRequestException("Client is being throttled: too many requests", method.getName(), uri, method);
      default:
        return new SwiftInvalidResponseException(errorMessage, method.getName(), uri, method);
    }
  }

  private static String formatErrorMessage(URI uri, HttpMethod method, int statusCode) {
    return String.format("Method %s on %s failed, status code: %d, status line: %s", method.getName(), uri, statusCode, method.getStatusLine());
  }

  private static IOException buildRangeException(HttpMethod method) {
    StringBuilder errorText = new StringBuilder(method.getStatusText());
    Header requestContentLen = method.getRequestHeader(HEADER_CONTENT_LENGTH);
    if (requestContentLen != null) {
      errorText.append(" requested ").append(requestContentLen.getValue());
    }
    Header availableContentRange = method.getResponseHeader(HEADER_CONTENT_RANGE);
    if (availableContentRange != null) {
      errorText.append(" available ").append(availableContentRange.getValue());
    }
    return new EOFException(errorText.toString());
  }
}

