  static ClientConfig from(URI filesystemURI, Configuration conf) throws SwiftConfigurationException {
    Properties props = RestClientBindings.bind(filesystemURI, conf);
    String stringAuthUri = getOption(props, SWIFT_AUTH_PROPERTY);
    String username = getOption(props, SWIFT_USERNAME_PROPERTY);
    String password = props.getProperty(SWIFT_PASSWORD_PROPERTY);
    String apiKey = props.getProperty(SWIFT_APIKEY_PROPERTY);
    validateCredentials(filesystemURI, password, apiKey);

    String region = props.getProperty(SWIFT_REGION_PROPERTY);
    String tenant = props.getProperty(SWIFT_TENANT_PROPERTY);
    String serviceProvider = props.getProperty(SWIFT_SERVICE_PROPERTY);
    String container = props.getProperty(SWIFT_CONTAINER_PROPERTY);
    boolean usePublicURL = "true".equals(props.getProperty(SWIFT_PUBLIC_PROPERTY, "false"));
    boolean locationAware = "true".equals(props.getProperty(SWIFT_LOCATION_AWARE_PROPERTY, "false"));

    int retryCount = readInt(conf, SWIFT_RETRY_COUNT, DEFAULT_RETRY_COUNT);
    int connectTimeout = readInt(conf, SWIFT_CONNECTION_TIMEOUT, DEFAULT_CONNECT_TIMEOUT);
    int socketTimeout = readInt(conf, SWIFT_SOCKET_TIMEOUT, DEFAULT_SOCKET_TIMEOUT);
    int throttleDelay = readInt(conf, SWIFT_THROTTLE_DELAY, DEFAULT_THROTTLE_DELAY);

    String proxyHost = conf.get(SWIFT_PROXY_HOST_PROPERTY);
    int proxyPort = conf.getInt(SWIFT_PROXY_PORT_PROPERTY, 8080);

    int blocksizeKB = readPositiveInt(conf, SWIFT_BLOCKSIZE, DEFAULT_SWIFT_BLOCKSIZE);
    int partSizeKB = readPositiveInt(conf, SWIFT_PARTITION_SIZE, DEFAULT_SWIFT_PARTITION_SIZE);
    int bufferSizeKB = readPositiveInt(conf, SWIFT_REQUEST_SIZE, DEFAULT_SWIFT_REQUEST_SIZE);

    URI authUri = parseAuthUri(stringAuthUri);
    String serviceDescription = buildServiceDescription(serviceProvider, container, stringAuthUri,
        tenant, username, region, usePublicURL, locationAware, partSizeKB, bufferSizeKB,
        blocksizeKB, connectTimeout, retryCount, socketTimeout, throttleDelay);

    return new ClientConfig(authUri, region, tenant, username, password, apiKey, container,
        serviceProvider, usePublicURL, locationAware, retryCount, connectTimeout, socketTimeout,
        throttleDelay, proxyHost, proxyPort, partSizeKB, blocksizeKB, bufferSizeKB,
        serviceDescription);
  }
}

