   *
   * @param method methot to exec
   * @param <M> Method type
   * @return the status code
   * @throws IOException on any failure
   */
  private <M extends HttpMethod> int exec(M method) throws IOException {
    final HttpClient client = createHttpClient();
    int statusCode = execWithDebugOutput(method, client);
    statusCode = tryKeystoneAuthentication(method, client, statusCode);
    return reauthenticateIfUnauthorized(method, client, statusCode);
  }

  private HttpClient createHttpClient() {
    final HttpClient client = new HttpClient();
    if (proxyHost != null) {
      client.getParams().setParameter(ConnRoutePNames.DEFAULT_PROXY,
              new HttpHost(proxyHost, proxyPort));
    }
    return client;
  }

  private <M extends HttpMethod> int tryKeystoneAuthentication(M method,
                                                               HttpClient client,
                                                               int statusCode)
          throws IOException {
    if (isKeystoneFallbackNeeded(statusCode, method)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Operation failed with status " + statusCode +
                " attempting keystone auth");
      }
      useKeystoneAuthentication = true;
      final AuthPostMethod authentication = (AuthPostMethod) method;
      authentication.setRequestEntity(getAuthenticationRequest(keystoneAuthRequest));
      return execWithDebugOutput(method, client);
    }
    return statusCode;
  }

  private <M extends HttpMethod> boolean isKeystoneFallbackNeeded(int statusCode, M method) {
    return (statusCode == HttpStatus.SC_UNAUTHORIZED
            || statusCode == HttpStatus.SC_BAD_REQUEST)
            && method instanceof AuthPostMethod
            && !useKeystoneAuthentication;
  }

  private <M extends HttpMethod> int reauthenticateIfUnauthorized(M method,
                                                                  HttpClient client,
                                                                  int statusCode)
          throws IOException {
    if (statusCode != HttpStatus.SC_UNAUTHORIZED) {
      return statusCode;
    }
    if (method instanceof AuthPostMethod) {
      throw new SwiftAuthenticationFailedException(authRequest.toString(),
              "auth",
              authUri,
              method);
    }
    if (LOG.isDebugEnabled()) {
      LOG.debug("Reauthenticating");
    }
    authenticate();
    if (LOG.isDebugEnabled()) {
      LOG.debug("Retrying original request");
    }
    return execWithDebugOutput(method, client);
  }

