      ((AuthPostMethod) method).setRequestEntity(getAuthenticationRequst(keystoneAuthRequest));
      return execWithDebugOutput(method, client);
    }
    return statusCode;
}

private <M extends HttpMethod> boolean isKeystoneFallbackNeeded(int statusCode, M method) {
    return (statusCode == HttpStatus.SC_UNAUTHORIZED || statusCode == HttpStatus.SC_BAD_REQUEST)
            && method instanceof AuthPostMethod
            && !useKeystoneAuthentication;
}

private <M extends HttpMethod> int reauthenticateIfUnauthorized(M method, HttpClient client, int statusCode) throws IOException {
    if (statusCode != HttpStatus.SC_UNAUTHORIZED) {
      return statusCode;
    }
    if (method instanceof AuthPostMethod) {
      throw new SwiftAuthenticationFailedException(authRequest.toString(), "auth", authUri, method);
    }
    authenticate();
    return execWithDebugOutput(method, client);
}
