  /**
   * Create a Swift Rest Client instance.
   *
   * @param filesystemURI filesystem URI
   * @param conf The configuration to use to extract the binding
   * @throws SwiftConfigurationException the configuration is not valid for
   * defining a rest client against the service
   */
  private SwiftRestClient(URI filesystemURI,
                          Configuration conf)
      throws SwiftConfigurationException {
    this.filesystemURI = filesystemURI;
    Properties props = RestClientBindings.bind(filesystemURI, conf);
    this.username = getOption(props, SWIFT_USERNAME_PROPERTY);
    this.password = props.getProperty(SWIFT_PASSWORD_PROPERTY);
    this.apiKey = props.getProperty(SWIFT_APIKEY_PROPERTY);
    this.region = props.getProperty(SWIFT_REGION_PROPERTY);
    this.tenant = props.getProperty(SWIFT_TENANT_PROPERTY);
    this.serviceProvider = props.getProperty(SWIFT_SERVICE_PROPERTY);
    this.container = props.getProperty(SWIFT_CONTAINER_PROPERTY);
    this.usePublicURL = parseBoolean(props.getProperty(SWIFT_PUBLIC_PROPERTY, "false"));
    this.authRequest = buildAuthRequest();
    this.locationAware = parseBoolean(props.getProperty(SWIFT_LOCATION_AWARE_PROPERTY, "false"));

    String stringAuthUri = getOption(props, SWIFT_AUTH_PROPERTY);
    this.authUri = parseAuthUri(stringAuthUri);
    loadConnectionSettings(conf);
    this.serviceDescription = buildServiceDescription(stringAuthUri);

    if (LOG.isDebugEnabled()) {
      LOG.debug(serviceDescription);
    }
  }

  private AuthenticationRequest buildAuthRequest() throws SwiftConfigurationException {
    if (apiKey == null && password == null) {
      throw new SwiftConfigurationException(
              "Configuration for " + filesystemURI +" must contain either "
                      + SWIFT_PASSWORD_PROPERTY + " or "
                      + SWIFT_APIKEY_PROPERTY);
    }
    if (password != null) {
      return new PasswordAuthenticationRequest(tenant,
              new PasswordCredentials(username, password));
    }
    keystoneAuthRequest = new KeyStoneAuthRequest(tenant,
            new KeystoneApiKeyCredentials(username, apiKey));
    return new ApiKeyAuthenticationRequest(tenant,
            new ApiKeyCredentials(username, apiKey));
  }

  private static boolean parseBoolean(String value) {
    return "true".equals(value);
  }

  private static URI parseAuthUri(String stringAuthUri) throws SwiftConfigurationException {
    try {
      return new URI(stringAuthUri);
    } catch (URISyntaxException e) {
      throw new SwiftConfigurationException("The " + SWIFT_AUTH_PROPERTY
              + " property was incorrect: "
              + stringAuthUri, e);
    }
  }

  private void loadConnectionSettings(Configuration conf) throws SwiftConfigurationException {
    try {
      retryCount = conf.getInt(SWIFT_RETRY_COUNT, DEFAULT_RETRY_COUNT);
      connectTimeout = conf.getInt(SWIFT_CONNECTION_TIMEOUT,
              DEFAULT_CONNECT_TIMEOUT);
      socketTimeout = conf.getInt(SWIFT_SOCKET_TIMEOUT,
              DEFAULT_SOCKET_TIMEOUT);

      throttleDelay = conf.getInt(SWIFT_THROTTLE_DELAY,
              DEFAULT_THROTTLE_DELAY);

      proxyHost = conf.get(SWIFT_PROXY_HOST_PROPERTY);
      proxyPort = conf.getInt(SWIFT_PROXY_PORT_PROPERTY, 8080);

      blocksizeKB = conf.getInt(SWIFT_BLOCKSIZE,
              DEFAULT_SWIFT_BLOCKSIZE);
      validatePositive(blocksizeKB, SWIFT_BLOCKSIZE, "blocksize");

      partSizeKB = conf.getInt(SWIFT_PARTITION_SIZE,
              DEFAULT_SWIFT_PARTITION_SIZE);
      validatePositive(partSizeKB, SWIFT_PARTITION_SIZE, "partition size");

      bufferSizeKB = conf.getInt(SWIFT_REQUEST_SIZE,
              DEFAULT_SWIFT_REQUEST_SIZE);
      validatePositive(bufferSizeKB, SWIFT_REQUEST_SIZE, "buffer size");
    } catch (NumberFormatException e) {
      throw new SwiftConfigurationException(e.toString(), e);
    }
  }

  private static void validatePositive(int value, String property, String description)
          throws SwiftConfigurationException {
    if (value <= 0) {
      throw new SwiftConfigurationException("Invalid " + description + " set in "
              + property
              + ": " + value);
    }
  }

  private String buildServiceDescription(String stringAuthUri) {
    return String.format(
            "Service={%s} container={%s} uri={%s}"
                    + " tenant={%s} user={%s} region={%s}"
                    + " publicURL={%b}"
                    + " location aware={%b}"
                    + " partition size={%d KB}, buffer size={%d KB}"
                    + " block size={%d KB}"
                    + " connect timeout={%d}, retry count={%d}"
                    + " socket timeout={%d}"
                    + " throttle delay={%d}"
                    ,
            serviceProvider,
            container,
            stringAuthUri,
            tenant,
            username,
            region != null ? region : "(none)",
            usePublicURL,
            locationAware,
            partSizeKB,
            bufferSizeKB,
            blocksizeKB,
            connectTimeout,
            retryCount,
            socketTimeout,
            throttleDelay
    );
  }

