  private <M extends HttpMethod> IOException buildException(URI uri,
                                                            M method,
                                                            int statusCode) {
    String errorMessage = formatErrorMessage(uri, method, statusCode);
    logDebug(errorMessage);

    if (statusCode == SC_NOT_FOUND) {
      return createNotFoundFault(uri, method);
    }
    if (statusCode == SC_BAD_REQUEST) {
      return createBadRequestFault(uri, method);
    }
    if (statusCode == SC_REQUESTED_RANGE_NOT_SATISFIABLE) {
      return createRangeFault(method);
    }
    if (statusCode == SC_UNAUTHORIZED) {
      return createUnauthorizedFault(uri, method);
    }
    if (isThrottled(statusCode)) {
      return createThrottledFault(uri, method);
    }
    return new SwiftInvalidResponseException(
            errorMessage,
            method.getName(),
            uri,
            method);
