  private String formatErrorMessage(URI uri, HttpMethod method, int statusCode) {
    return String.format("Method %s on %s failed, status code: %d," +
            " status line: %s",
            method.getName(),
            uri,
            statusCode,
            method.getStatusLine()
    );
  }

  private void logDebug(String message) {
    if (LOG.isDebugEnabled()) {
      LOG.debug(message);
    }
  }

  private static IOException createNotFoundFault(URI uri, HttpMethod method) {
    return new FileNotFoundException("Operation " + method.getName()
            + " on " + uri);
  }

  private static IOException createBadRequestFault(URI uri, HttpMethod method) {
    return new SwiftBadRequestException(
            "Bad request against " + uri,
            method.getName(),
            uri,
            method);
  }

  private static IOException createRangeFault(HttpMethod method) {
    StringBuilder errorText = new StringBuilder(method.getStatusText());
    Header requestContentLen = method.getRequestHeader(HEADER_CONTENT_LENGTH);
    if (requestContentLen != null) {
      errorText.append(" requested ").append(requestContentLen.getValue());
    }
    Header availableContentRange = method.getResponseHeader(HEADER_CONTENT_RANGE);
    if (availableContentRange != null) {
      errorText.append(" available ").append(availableContentRange.getValue());
    }
    return new EOFException(errorText.toString());
  }

  private IOException createUnauthorizedFault(URI uri, HttpMethod method) {
    return new SwiftAuthenticationFailedException(
            "Operation not authorized- current access token ="
                    + getToken(),
            method.getName(),
            uri,
            method);
  }

  private static boolean isThrottled(int statusCode) {
    return statusCode == SwiftProtocolConstants.SC_TOO_MANY_REQUESTS_429
            || statusCode == SwiftProtocolConstants.SC_THROTTLED_498;
  }

  private static IOException createThrottledFault(URI uri, HttpMethod method) {
