  private <M extends HttpMethod> int attemptKeystoneFallback(M method,
                                                             HttpClient client,
                                                             int statusCode)
          throws IOException {
    if (isKeystoneFallbackNeeded(statusCode, method)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Operation failed with status " + statusCode +
                " attempting keystone auth");
