Refactor:
```
private <M extends HttpMethod> int exec(M method) throws IOException {
    HttpClient client = createHttpClient();
    int statusCode = execWithDebugOutput(method, client);
    statusCode = tryKeystoneFallback(method, client, statusCode);
    statusCode = reauthenticateIfNeeded(method, client, statusCode);
    return statusCode;
}

private HttpClient createHttpClient() {
    HttpClient client = new HttpClient();
    if (proxyHost != null) {
        client.getParams().setParameter(ConnRoutePNames.DEFAULT_PROXY, new HttpHost(proxyHost, proxyPort));
    }
    return client;
}

private <M extends HttpMethod> int tryKeystoneFallback(M method, HttpClient client, int statusCode) throws IOException {
    if (isKeystoneFallbackNeeded(statusCode, method)) {
        logKeystoneFallback();
        useKeystoneAuthentication = true;
        AuthPostMethod authentication = (AuthPostMethod) method;
        authentication.setRequestEntity(getAuthenticationRequst(keystoneAuthRequest));
        statusCode = execWithDebugOutput(method, client);
    }
    return statusCode;
}

private <M extends HttpMethod> boolean isKeystoneFallbackNeeded(int statusCode, M method) {
    return (statusCode == SC_UNAUTHORIZED || statusCode == SC_BAD_REQUEST)
            && method instanceof AuthPostMethod
            && !useKeystoneAuthentication;
}

private <M extends HttpMethod> int reauthenticateIfNeeded(M method, HttpClient client, int statusCode) throws IOException {
    if (statusCode == SC_UNAUTHORIZED) {
        if (method instanceof AuthPostMethod) {
            throw new SwiftAuthenticationFailedException(authRequest.toString(), "auth", authUri, method);
        }
        logReauth();
        authenticate();
        logRetry();
        statusCode = execWithDebugOutput(method, client);
    }
    return statusCode;
}
```
