```
private class AuthenticationPost extends AuthMethodProcessor<AccessToken> {
    final AuthenticationRequest authenticationRequest;

    private AuthenticationPost(AuthenticationRequest authenticationRequest) {
        this.authenticationRequest = authenticationRequest;
    }

    @Override
    protected void setup(AuthPostMethod method) throws IOException {
        method.setRequestEntity(getAuthenticationRequest(authenticationRequest));
    }

    @Override
    protected int[] getAllowedStatusCodes() {
        return new int[]{
                SC_OK,
                SC_BAD_REQUEST,
                SC_CREATED,
                SC_ACCEPTED,
                SC_NON_AUTHORITATIVE_INFORMATION,
                SC_NO_CONTENT,
                SC_RESET_CONTENT,
                SC_PARTIAL_CONTENT,
                SC_MULTI_STATUS,
                SC_UNAUTHORIZED
        };
    }

    @Override
    public AccessToken extractResult(AuthPostMethod method) throws IOException {
        validateAuthResponse(method);
        AuthenticationResponse access = parseAuthResponse(method);
        Endpoint swiftEndpoint = locateSwiftEndpoint(access.getServiceCatalog());
        URI endpoint = selectEndpointURI(swiftEndpoint);
        URI objectLocation = buildObjectLocation(endpoint, swiftEndpoint);
        AccessToken accessToken = access.getToken();
        setAuthDetails(endpoint, objectLocation, accessToken);
        logAuthSuccess(endpoint);
        createDefaultContainer();
        return accessToken;
    }

    private void validateAuthResponse(AuthPostMethod method) throws SwiftAuthenticationFailedException {
        if (method.getStatusCode() == SC_BAD_REQUEST) {
            throw new SwiftAuthenticationFailedException(authenticationRequest.toString(), "POST", authUri, method);
        }
    }

    private AuthenticationResponse parseAuthResponse(AuthPostMethod method) throws IOException {
        return JSONUtil.toObject(method.getResponseBodyAsString(), AuthenticationWrapper.class).getAccess();
    }

    private Endpoint locateSwiftEndpoint(List<Catalog> serviceCatalog) {
        StringBuilder catList = new StringBuilder();
        StringBuilder regionList = new StringBuilder();
        for (Catalog catalog : serviceCatalog) {
            String name = catalog.getName();
            String type = catalog.getType();
            appendCatalogDescription(catList, name, type);
            logCatalogEntry(name, type);
            if (isSwiftCatalog(name, type)) {
                logSwiftCatalogFound(name, type);
                Endpoint endpoint = findMatchingEndpoint(catalog, regionList);
                if (endpoint != null) {
                    return endpoint;
                }
            }
        }
        throw new SwiftInvalidResponseException(buildEndpointNotFoundMessage(catList, regionList),
                SC_OK, "authenticating", authUri);
    }

    private void appendCatalogDescription(StringBuilder catList, String name, String type) {
        catList.append(String.format("[%s: %s]; ", name, type));
    }

    private void logCatalogEntry(String name, String type) {
        if (LOG.isDebugEnabled()) {
            LOG.debug("Catalog entry [" + name + ": " + type + "]");
        }
    }

    private boolean isSwiftCatalog(String name, String type) {
        return name.equals(SERVICE_CATALOG_SWIFT)
                || name.equals(SERVICE_CATALOG_CLOUD_FILES)
                || type.equals(SERVICE_CATALOG_OBJECT_STORE);
    }

    private void logSwiftCatalogFound(String name, String type) {
        if (LOG.isDebugEnabled()) {
            LOG.debug("Found swift catalog as " + name + " => " + type);
        }
    }

    private Endpoint findMatchingEndpoint(Catalog catalog, StringBuilder regionList) {
        for (Endpoint endpoint : catalog.getEndpoints()) {
            String endpointRegion = endpoint.getRegion();
            URI publicURL = endpoint.getPublicURL();
            URI internalURL = endpoint.getInternalURL();
            appendEndpointDescription(regionList, endpointRegion, publicURL, internalURL);
            logEndpoint(endpointRegion, publicURL, internalURL);
            if (region == null || endpointRegion.equals(region)) {
                return endpoint;
            }
        }
        return null;
    }

    private void appendEndpointDescription(StringBuilder regionList, String endpointRegion, URI publicURL, URI internalURL) {
        regionList.append(String.format("[%s => %s / %s]; ", endpointRegion, publicURL, internalURL));
    }

    private void logEndpoint(String endpointRegion, URI publicURL, URI internalURL) {
        if (LOG.isDebugEnabled()) {
            LOG.debug("Endpoint [" + endpointRegion + " => " + publicURL + " / " + internalURL + "]");
        }
    }

    private String buildEndpointNotFoundMessage(StringBuilder catList, StringBuilder regionList) {
        String message = "Could not find swift service from auth URL " + authUri
                + " and region '" + region + "'. "
                + "Categories: " + catList;
        if (regionList.length() > 0) {
            message += "regions: " + regionList;
        } else {
            message += "No regions";
        }
        return message;
    }

    private URI selectEndpointURI(Endpoint swiftEndpoint) {
        endpointURI = usePublicURL ? swiftEndpoint.getPublicURL() : swiftEndpoint.getInternalURL();
        return endpointURI;
    }

    private URI buildObjectLocation(URI endpoint, Endpoint swiftEndpoint) throws SwiftException {
        String path = SWIFT_OBJECT_AUTH_ENDPOINT + swiftEndpoint.getTenantId();
        String host = endpoint.getHost();
        try {
            return new URI(endpoint.getScheme(), null, host, endpoint.getPort(), path, null, null);
        } catch (URISyntaxException e) {
            throw new SwiftException("object endpoint URI is incorrect: " + endpoint + " + " + path, e);
        }
    }

    private void logAuthSuccess(URI endpoint) {
        if (LOG.isDebugEnabled()) {
            LOG.debug("authenticated against " + endpoint);
        }
    }
}
```
