```
private <M extends HttpMethod> int exec(M method) throws IOException {
    HttpClient client = createHttpClient();
    int statusCode = execWithDebugOutput(method, client);
    statusCode = attemptKeystoneFallback(method, client, statusCode);
    statusCode = reauthenticateIfUnauthorized(method, client, statusCode);
    return statusCode;
}

private HttpClient createHttpClient() {
    HttpClient client = new HttpClient();
    if (proxyHost != null) {
        client.getParams().setParameter(ConnRoutePNames.DEFAULT_PROXY, new HttpHost(proxyHost, proxyPort));
    }
    return client;
}

private <M extends HttpMethod> int attemptKeystoneFallback(M method, HttpClient client, int statusCode) throws IOException {
    if (isKeystoneFallbackNeeded(statusCode, method)) {
        if (LOG.isDebugEnabled()) {
            LOG.debug("Operation failed with status " + statusCode + " attempting keystone auth");
        }
        useKeystoneAuthentication = true;
        AuthPostMethod authentication = (AuthPostMethod) method;
        authentication.setRequestEntity(getAuthenticationRequest(keystoneAuthRequest));
        statusCode = execWithDebugOutput(method, client);
    }
    return statusCode;
}

private <M extends HttpMethod> boolean isKeystoneFallbackNeeded(int statusCode, M method) {
    return keystoneAuthRequest != null
            && (statusCode == SC_UNAUTHORIZED || statusCode == SC_BAD_REQUEST)
            && method instanceof AuthPostMethod
            && !useKeystoneAuthentication;
}

private <M extends HttpMethod> int reauthenticateIfUnauthorized(M method, HttpClient client, int statusCode) throws IOException {
    if (statusCode == SC_UNAUTHORIZED) {
        if (method instanceof AuthPostMethod) {
            throw new SwiftAuthenticationFailedException(authRequest.toString(), "auth", authUri, method);
        }
        if (LOG.isDebugEnabled()) {
            LOG.debug("Reauthenticating");
        }
        authenticate();
        if (LOG.isDebugEnabled()) {
            LOG.debug("Retrying original request");
        }
        statusCode = execWithDebugOutput(method, client);
    }
    return statusCode;
}
```
This reduces `exec` complexity. The null check for keystoneAuthRequest is a behavior change but safe.

