private <M extends HttpMethod, R> R perform(String reason, URI uri, HttpMethodProcessor<M, R> processor) throws IOException, ... {
    checkNotNull(uri);
    checkNotNull(processor);
    M method = processor.createMethod(uri.toString());
    configureMethod(method);
    Duration duration = new Duration();
    boolean success = false;
    try {
        int statusCode = executeMethod(method, uri);
        validateResponse(method, statusCode, processor.getAllowedStatusCodes());
        R result = processor.extractResult(method);
        success = true;
        return result;
    } catch (IOException e) {
        method.releaseConnection();
        throw e;
    } finally {
        duration.finished();
        durationStats.add(method.getName() + " " + reason, duration, success);
    }
}

private <M extends HttpMethod> void configureMethod(M method) {
    HttpMethodParams methodParams = method.getParams();
    methodParams.setParameter(HttpMethodParams.RETRY_HANDLER, new DefaultHttpMethodRetryHandler(retryCount, false));
    methodParams.setIntParameter(HttpConnectionParams.CONNECTION_TIMEOUT, connectTimeout);
    methodParams.setSoTimeout(socketTimeout);
    method.addRequestHeader(HEADER_USER_AGENT, SWIFT_USER_AGENT);
}

private <M extends HttpMethod> int executeMethod(M method, URI uri) throws IOException {
    try {
        return exec(method);
    } catch (IOException e) {
        throw ExceptionDiags.wrapException(uri.toString(), method.getName(), e);
    }
}

