  /**
   * Authenticate to Openstack Keystone
   * As well as returning the access token, the member fields {@link #token},
   * {@link #endpointURI} and {@link #objectLocationURI} are set up for re-use.
   * <p>
   * This method is re-entrant -if more than one thread attempts to authenticate
   * neither will block -but the field values with have those of the last caller.
   *
   * @return authenticated access token
   */
  public AccessToken authenticate() throws IOException {
    final AuthenticationRequest authenticationRequest;
    if (useKeystoneAuthentication) {
      authenticationRequest = keystoneAuthRequest;
    } else {
      authenticationRequest = authRequest;
    }

    LOG.debug("started authentication");
    return perform("authentication",
                   authUri,
                   new AuthenticationPost(authenticationRequest));
  }

  private class AuthenticationPost extends AuthMethodProcessor<AccessToken> {
    final AuthenticationRequest authenticationRequest;

    private AuthenticationPost(AuthenticationRequest authenticationRequest) {
      this.authenticationRequest = authenticationRequest;
    }

    @Override
    protected void setup(AuthPostMethod method) throws IOException {

      method.setRequestEntity(getAuthenticationRequst(authenticationRequest));
    }

    /**
     * specification says any of the 2xxs are OK, so list all
     * the standard ones
     * @return a set of 2XX status codes.
     */
    @Override
    protected int[] getAllowedStatusCodes() {
      return new int[]{
        SC_OK,
        SC_BAD_REQUEST,
        SC_CREATED,
        SC_ACCEPTED,
        SC_NON_AUTHORITATIVE_INFORMATION,
        SC_NO_CONTENT,
        SC_RESET_CONTENT,
        SC_PARTIAL_CONTENT,
        SC_MULTI_STATUS,
        SC_UNAUTHORIZED //if request unauthorized, try another method
      };
    }

    @Override
    public AccessToken extractResult(AuthPostMethod method) throws IOException {
      validateAuthResponse(method);
      final AuthenticationResponse access = parseAuthResponse(method);
      final SwiftEndpoint swiftEndpoint = findSwiftEndpoint(access.getServiceCatalog());
      final URI objectLocation = buildObjectLocationURI(
          swiftEndpoint.getEndpointURI(), swiftEndpoint.getEndpoint());
      final AccessToken accessToken = access.getToken();

      setAuthDetails(swiftEndpoint.getEndpointURI(), objectLocation, accessToken);

      if (LOG.isDebugEnabled()) {
        LOG.debug("authenticated against " + swiftEndpoint.getEndpointURI());
      }
      createDefaultContainer();
      return accessToken;
    }

    /**
     * Validate the initial auth response, converting a bad request into a
     * Swift authentication failure.
     *
     * @param method auth method
     * @throws SwiftAuthenticationFailedException if the request was rejected
     */
    private void validateAuthResponse(AuthPostMethod method)
        throws SwiftAuthenticationFailedException {
      if (method.getStatusCode() == SC_BAD_REQUEST) {
        throw new SwiftAuthenticationFailedException(
          authenticationRequest.toString(), "POST", authUri, method);
      }
    }

    /**
     * Parse the JSON authentication response body.
     *
     * @param method auth method
     * @return parsed authentication response
     * @throws IOException if parsing fails
     */
    private AuthenticationResponse parseAuthResponse(AuthPostMethod method) throws IOException {
      return JSONUtil.toObject(method.getResponseBodyAsString(),
                               AuthenticationWrapper.class).getAccess();
    }
  }

  /**
   * Locate the Swift endpoint in the service catalog.
   *
   * @param serviceCatalog catalog returned by the auth service
   * @return the selected endpoint and its URI
   * @throws SwiftInvalidResponseException if no matching endpoint is found
   */
  private SwiftEndpoint findSwiftEndpoint(List<Catalog> serviceCatalog)
      throws SwiftInvalidResponseException {
    StringBuilder catList = new StringBuilder();
    StringBuilder regionList = new StringBuilder();
    URI endpointURI = null;
    Endpoint swiftEndpoint = null;

    for (Catalog catalog : serviceCatalog) {
      String name = catalog.getName();
      String type = catalog.getType();
      String descr = String.format("[%s: %s]; ", name, type);
      catList.append(descr);
      if (LOG.isDebugEnabled()) {
        LOG.debug("Catalog entry " + descr);
      }
      if (isSwiftCatalog(name, type)) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("Found swift catalog as " + name + " => " + type);
        }
        //now go through the endpoints
        for (Endpoint endpoint : catalog.getEndpoints()) {
          String endpointRegion = endpoint.getRegion();
          URI publicURL = endpoint.getPublicURL();
          URI internalURL = endpoint.getInternalURL();
          descr = String.format("[%s => %s / %s]; ",
                                endpointRegion,
                                publicURL,
                                internalURL);
          regionList.append(descr);
          if (LOG.isDebugEnabled()) {
            LOG.debug("Endpoint " + descr);
          }
          if (region == null || endpointRegion.equals(region)) {
            endpointURI = usePublicURL ? publicURL : internalURL;
            swiftEndpoint = endpoint;
            break;
          }
        }
      }
    }
    if (endpointURI == null) {
      throw buildEndpointNotFoundException(catList, regionList);
    }
    return new SwiftEndpoint(endpointURI, swiftEndpoint);
  }

  /**
   * Determine whether a catalog entry represents the Swift object store.
   *
   * @param name catalog name
   * @param type catalog type
   * @return true if this catalog entry is for Swift
   */
  private static boolean isSwiftCatalog(String name, String type) {
    return name.equals(SERVICE_CATALOG_SWIFT)
        || name.equals(SERVICE_CATALOG_CLOUD_FILES)
        || type.equals(SERVICE_CATALOG_OBJECT_STORE);
  }

  /**
   * Build the exception thrown when no Swift endpoint can be located.
   *
   * @param catList collected catalog descriptions
   * @param regionList collected endpoint descriptions
   * @return exception describing the failure
   */
  private SwiftInvalidResponseException buildEndpointNotFoundException(
      StringBuilder catList,
      StringBuilder regionList) {
    String message = "Could not find swift service from auth URL "
                     + authUri
                     + " and region '" + region + "'. "
                     + "Categories: " + catList
                     + ((regionList.length() > 0) ?
                        ("regions: " + regionList)
                                                    : "No regions");
    return new SwiftInvalidResponseException(message,
                                             SC_OK,
                                             "authenticating",
                                             authUri);
  }

  /**
   * Build the object location URI from the selected Swift endpoint.
   *
   * @param endpointURI selected endpoint URI
   * @param swiftEndpoint selected endpoint details
   * @return object location URI
   * @throws SwiftException if the URI cannot be constructed
   */
  private static URI buildObjectLocationURI(URI endpointURI, Endpoint swiftEndpoint)
      throws SwiftException {
    String path = SWIFT_OBJECT_AUTH_ENDPOINT
                  + swiftEndpoint.getTenantId();
    String host = endpointURI.getHost();
    try {
      return new URI(endpointURI.getScheme(),
                     null,
                     host,
                     endpointURI.getPort(),
                     path,
                     null,
                     null);
    } catch (URISyntaxException e) {
      throw new SwiftException("object endpoint URI is incorrect: "
                               + endpointURI
                               + " + " + path,
                               e);
    }
  }

  private StringRequestEntity getAuthenticationRequst(AuthenticationRequest authenticationRequest)
    throws IOException {
    final String data = JSONUtil.toJSON(new AuthenticationRequestWrapper(
            authenticationRequest));
    if (LOG.isDebugEnabled()) {
      LOG.debug("Authenticating with " + authenticationRequest);
    }
    return toJsonEntity(data);
  }

  /**
   * create default container if it doesn't exist for Hadoop Swift integration.
   * non-reentrant, as this should only be needed once.
   *
   * @throws IOException IO problems.
   */
  private synchronized void createDefaultContainer() throws IOException {
    createContainer(container);
  }

  /**
   * Create a container -if it already exists, do nothing
   *
   * @param containerName the container name
   * @throws IOException IO problems
   * @throws SwiftBadRequestException invalid container name
   * @throws SwiftInvalidResponseException error from the server
   */
  public void createContainer(String containerName) throws IOException {
    SwiftObjectPath objectPath = new SwiftObjectPath(containerName, "");
    try {
      //see if the data is there
      headRequest("createContainer", objectPath, NEWEST);
    } catch (FileNotFoundException ex) {
      createMissingContainer(objectPath, ex);
    }
  }

  /**
   * Create a container that is known to be missing and validate the result.
   *
   * @param objectPath path representing the container
   * @param ex original not-found exception to re-throw on success
   * @throws IOException on any failure
   */
  private void createMissingContainer(SwiftObjectPath objectPath,
                                      FileNotFoundException ex)
      throws IOException {
    int status = executeContainerPut(objectPath);
    validateContainerCreateStatus(status, objectPath.getContainer());
    throw ex;
  }

  /**
   * Execute the PUT request to create a container, mapping a 404 response
   * to the NOT_FOUND status code.
   *
   * @param objectPath container path
   * @return HTTP status code
   * @throws IOException on IO problems
   */
  private int executeContainerPut(SwiftObjectPath objectPath) throws IOException {
    try {
      return putRequest(objectPath);
    } catch (FileNotFoundException e) {
      //triggered by a very bad container name.
      //re-insert the 404 result into the status
      return SC_NOT_FOUND;
    }
  }

  /**
   * Validate the status code returned by a container creation attempt.
   *
   * @param status HTTP status code
   * @param containerName name of the container being created
   * @throws SwiftBadRequestException on a bad request status
   * @throws SwiftInvalidResponseException on an unexpected status
   */
  private void validateContainerCreateStatus(int status, String containerName)
      throws SwiftBadRequestException, SwiftInvalidResponseException {
    if (status == SC_BAD_REQUEST) {
      throw new SwiftBadRequestException(
        "Bad request -authentication failure or bad container name?",
        status,
        "PUT",
        null);
    }
    if (!isStatusCodeExpected(status,
            SC_OK,
            SC_CREATED,
            SC_ACCEPTED,
            SC_NO_CONTENT)) {
      throw new SwiftInvalidResponseException("Couldn't create container "
              + containerName +
              " for storing data in Swift." +
              " Try to create container " +
              containerName + " manually ",
              status,
              "PUT",
              null);
    }
  }

