   * @param <M> method type
   * @param <R> result type
   * @return extracted result
   * @throws IOException on any failure
   */
  private <M extends HttpMethod, R> R processResponse(URI uri,
                                                      M method,
                                                      int statusCode,
                                                      HttpMethodProcessor<M, R> processor)
      throws IOException {
    //validate the allowed status code for this operation
    int[] allowedStatusCodes = processor.getAllowedStatusCodes();
    boolean validResponse = isStatusCodeExpected(statusCode,
            allowedStatusCodes);

    if (!validResponse) {
      throw buildException(uri, method, statusCode);
