  /**
   * Locate the Swift endpoint matching the configured region and public URL
   * preference.
   */
  private EndpointMatch findSwiftEndpoint(List<Catalog> serviceCatalog)
      throws SwiftInvalidResponseException {
    StringBuilder catList = new StringBuilder();
    StringBuilder regionList = new StringBuilder();

    for (Catalog catalog : serviceCatalog) {
      String name = catalog.getName();
      String type = catalog.getType();
      String descr = String.format("[%s: %s]; ", name, type);
      catList.append(descr);
      if (LOG.isDebugEnabled()) {
        LOG.debug("Catalog entry " + descr);
      }
      if (isSwiftCatalog(name, type)) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("Found swift catalog as " + name + " => " + type);
        }
        EndpointMatch match = findMatchingEndpoint(catalog, regionList);
        if (match != null) {
          return match;
        }
      }
    }
    throw new SwiftInvalidResponseException(buildNoEndpointMessage(catList, regionList),
                                            SC_OK,
                                            "authenticating",
                                            authUri);
  }

  /**
   * Determine whether a service catalog entry represents Swift.
   */
  private boolean isSwiftCatalog(String name, String type) {
    return name.equals(SERVICE_CATALOG_SWIFT)
        || name.equals(SERVICE_CATALOG_CLOUD_FILES)
        || type.equals(SERVICE_CATALOG_OBJECT_STORE);
  }

  /**
   * Find the first endpoint in a catalog that matches the configured region.
   */
  private EndpointMatch findMatchingEndpoint(Catalog catalog,
                                             StringBuilder regionList) {
    for (Endpoint endpoint : catalog.getEndpoints()) {
      String endpointRegion = endpoint.getRegion();
      URI publicURL = endpoint.getPublicURL();
      URI internalURL = endpoint.getInternalURL();
      String descr = String.format("[%s => %s / %s]; ",
                                   endpointRegion,
                                   publicURL,
                                   internalURL);
      regionList.append(descr);
      if (LOG.isDebugEnabled()) {
        LOG.debug("Endpoint " + descr);
      }
      if (region == null || endpointRegion.equals(region)) {
        URI endpointURI = usePublicURL ? publicURL : internalURL;
        return new EndpointMatch(endpointURI, endpoint);
      }
    }
    return null;
  }

