private EndpointMatch findSwiftEndpoint(List<Catalog> serviceCatalog) throws SwiftInvalidResponseException {
  StringBuilder catList = new StringBuilder();
  StringBuilder regionList = new StringBuilder();
  for (Catalog catalog : serviceCatalog) {
    String name = catalog.getName();
    String type = catalog.getType();
    String descr = String.format("[%s: %s]; ", name, type);
    catList.append(descr);
    if (LOG.isDebugEnabled()) { LOG.debug("Catalog entry " + descr); }
    if (isSwiftCatalog(name, type)) {
      if (LOG.isDebugEnabled()) { LOG.debug("Found swift catalog as " + name + " => " + type); }
      EndpointMatch match = findMatchingEndpoint(catalog, regionList);
      if (match != null) { return match; }
    }
  }
  throw new SwiftInvalidResponseException(buildNoEndpointMessage(catList, regionList), SC_OK, "authenticating", authUri);
}
