   * @param path   path to object
   * @param offset offset from file beginning
   * @param length number of bytes to read
   * @throws SwiftException if the offset or length is invalid
   */
  private void validateOffsetAndLength(SwiftObjectPath path, long offset, long length)
      throws SwiftException {
    if (offset < 0) {
      throw new SwiftException("Invalid offset: " + offset
                            + " in getDataAsInputStream( path=" + path
                            + ", offset=" + offset
                            + ", length =" + length + ")");
    }
    if (length <= 0) {
      throw new SwiftException("Invalid length: " + length
                + " in getDataAsInputStream( path="+ path
                            + ", offset=" + offset
                            + ", length ="+ length + ")");
    }
  }

