  private static final ExceptionFactory DEFAULT_EXCEPTION_FACTORY =
      new DefaultExceptionFactory();

  private static final Map<Integer, ExceptionFactory> EXCEPTION_FACTORIES =
      new HashMap<Integer, ExceptionFactory>();
  static {
    EXCEPTION_FACTORIES.put(SC_NOT_FOUND, new NotFoundFactory());
    EXCEPTION_FACTORIES.put(SC_BAD_REQUEST, new BadRequestFactory());
    EXCEPTION_FACTORIES.put(SC_REQUESTED_RANGE_NOT_SATISFIABLE,
        new RangeNotSatisfiableFactory());
    EXCEPTION_FACTORIES.put(SC_UNAUTHORIZED, new UnauthorizedFactory());
    ExceptionFactory throttledFactory = new ThrottledRequestFactory();
    EXCEPTION_FACTORIES.put(SwiftProtocolConstants.SC_TOO_MANY_REQUESTS_429,
        throttledFactory);
    EXCEPTION_FACTORIES.put(SwiftProtocolConstants.SC_THROTTLED_498,
        throttledFactory);
  }

  /**
   * Build an exception from a failed operation. This can include generating
   * specific exceptions (e.g. FileNotFound), as well as the default
   * {@link SwiftInvalidResponseException}.
   *
   * @param uri URI for operation
   * @param method operation that failed
   * @param statusCode status code
   * @return an exception to throw
   */
  private IOException buildException(URI uri,
                                     HttpMethodBase method,
                                     int statusCode) {
    //log the failure @debug level
    String errorMessage = String.format("Method %s on %s failed, status code: %d," +
            " status line: %s",
            method.getName(),
            uri,
            statusCode,
            method.getStatusLine()
    );
    if (LOG.isDebugEnabled()) {
      LOG.debug(errorMessage);
    }

    ExceptionFactory factory = EXCEPTION_FACTORIES.get(statusCode);
    if (factory == null) {
      factory = DEFAULT_EXCEPTION_FACTORY;
    }
    return factory.create(this, uri, method, statusCode, errorMessage);
  }

  /**
   * Exec a GET request and return the input stream of the response
   *
   * @param uri URI to GET
   * @param requestHeaders request headers
   * @return the input stream. This must be closed to avoid log errors
   * @throws IOException
   */
  private HttpBodyContent doGet(final URI uri, final Header... requestHeaders) throws IOException {
    return perform("", uri, new GetMethodProcessor<HttpBodyContent>() {
      @Override
      public HttpBodyContent extractResult(GetMethod method) throws IOException {
        return
          new HttpBodyContent(
            new HttpInputStreamWithRelease(uri, method), method.getResponseContentLength()
          );
      }

      @Override
      protected void setup(GetMethod method) throws
                    SwiftInternalStateException {
        setHeaders(method, requestHeaders);
      }
    });
  }

