   * @return the status code after any retry
   * @throws IOException on IO problems
   */
  private int attemptKeystoneAuth(int statusCode,
                                  HttpMethod method,
                                  HttpClient client) throws IOException {
    if (isAuthFailureRetryableWithKeystone(statusCode, method)) {
      if (LOG.isDebugEnabled()) {
        LOG.debug("Operation failed with status " + statusCode +
                 " attempting keystone auth");
      }
      useKeystoneAuthentication = true;
      final AuthPostMethod authentication = (AuthPostMethod) method;
      //replace rackspace auth with keystone one
      authentication.setRequestEntity(getAuthenticationRequst(keystoneAuthRequest));
      statusCode = execWithDebugOutput(method, client);
    }
    return statusCode;
  }

  /**
   * Checks whether a failed auth response should be retried with Keystone.
   *
   * @param statusCode HTTP status code
   * @param method     method being executed
   * @return true if Keystone retry is appropriate
   */
  private boolean isAuthFailureRetryableWithKeystone(int statusCode, HttpMethod method) {
    return (statusCode == HttpStatus.SC_UNAUTHORIZED
            || statusCode == HttpStatus.SC_BAD_REQUEST)
            && method instanceof AuthPostMethod
            && !useKeystoneAuthentication;
