private EndpointSearchResult findSwiftEndpoint(List<Catalog> serviceCatalog) {
  StringBuilder catList = new StringBuilder();
  StringBuilder regionList = new StringBuilder();
  for (Catalog catalog : serviceCatalog) {
    String name = catalog.getName();
    String type = catalog.getType();
    String descr = String.format("[%s: %s]; ", name, type);
    catList.append(descr);
    debugLog("Catalog entry " + descr);
    if (isSwiftCatalog(name, type)) {
      debugLog("Found swift catalog as " + name + " => " + type);
      EndpointMatch match = findEndpointInCatalog(catalog, regionList);
      if (match != null) {
        return new EndpointSearchResult(match, catList, regionList);
      }
    }
  }
  return new EndpointSearchResult(null, catList, regionList);
}
