@Override
public AccessToken extractResult(AuthPostMethod method) throws IOException {
  if (method.getStatusCode() == SC_BAD_REQUEST) {
    throw new SwiftAuthenticationFailedException(
        authenticationRequest.toString(), "POST", authUri, method);
  }

  final AuthenticationResponse access =
      JSONUtil.toObject(method.getResponseBodyAsString(),
          AuthenticationWrapper.class).getAccess();
  final EndpointSearchResult result = findSwiftEndpoint(access.getServiceCatalog());

  if (result.match == null) {
    throw new SwiftInvalidResponseException(
        buildNoEndpointMessage(result.catList, result.regionList),
        SC_OK,
        "authenticating",
        authUri);
  }

  AccessToken accessToken = access.getToken();
  URI objectLocation = buildObjectLocationURI(result.match.endpointURI, result.match.endpoint);
  setAuthDetails(result.match.endpointURI, objectLocation, accessToken);

  debugLog("authenticated against " + result.match.endpointURI);
  createDefaultContainer();
  return accessToken;
