public void createContainer(String containerName) throws IOException {
  SwiftObjectPath objectPath = new SwiftObjectPath(containerName, "");
  try {
    //see if the data is there
    headRequest("createContainer", objectPath, NEWEST);
  } catch (FileNotFoundException ex) {
    int status = createContainerWithPut(objectPath);
    if (status == SC_BAD_REQUEST) {
      throw new SwiftBadRequestException(
          "Bad request -authentication failure or bad container name?",
          status,
          "PUT",
          null);
    }
    if (!isSuccessfulContainerCreation(status)) {
      throw new SwiftInvalidResponseException("Couldn't create container "
          + containerName +
          " for storing data in Swift." +
          " Try to create container " +
          containerName + " manually ",
          status,
          "PUT",
          null);
    }
    throw ex;
  }
}

/**
 * Attempts to create a container with a PUT request, translating a
 * {@link FileNotFoundException} into the expected 404 status.
 */
private int createContainerWithPut(SwiftObjectPath objectPath) throws IOException {
  try {
    return putRequest(objectPath);
  } catch (FileNotFoundException e) {
    //triggered by a very bad container name.
    //re-insert the 404 result into the status
    return SC_NOT_FOUND;
  }
}

/**
 * Checks whether a PUT response status indicates successful container creation.
 */
private boolean isSuccessfulContainerCreation(int status) {
  return isStatusCodeExpected(status,
      SC_OK,
      SC_CREATED,
      SC_ACCEPTED,
      SC_NO_CONTENT);
}
