private String buildListObjectsUri(SwiftObjectPath path, boolean listDeep) {
  StringBuilder dataLocationURI = new StringBuilder();
  dataLocationURI.append(getEndpointURI().toString());
  String object = normalizeDirectoryPrefix(path.getObject());
  dataLocationURI.append("/")
      .append(path.getContainer())
      .append("/?prefix=")
      .append(object)
      .append("&format=json");

  if (!listDeep) {
    dataLocationURI.append("&delimiter=/");
  }

  return dataLocationURI.toString();
}

private String normalizeDirectoryPrefix(String object) {
  if (object.startsWith("/")) {
    object = object.substring(1);
  }
  if (!object.endsWith("/")) {
    object = object.concat("/");
  }
  if (object.equals("/")) {
    object = "";
  }
  return object;
}
