private static String encodeUrl(String url) throws SwiftException {
  if (containsWhitespace(url)) {
    try {
      url = URLEncoder.encode(url, "UTF-8");
      url = url.replace("+", "%20");
    } catch (UnsupportedEncodingException e) {
      throw new SwiftException("failed to encode URI", e);
    }
  }
  return url;
}

/**
 * Checks whether a URL string contains whitespace.
 */
private static boolean containsWhitespace(String url) {
  return url.matches(".*\\s+.*");
}
