  /**
   * Authenticate to Openstack Keystone
   * As well as returning the access token, the member fields {@link #token},
   * {@link #endpointURI} and {@link #objectLocationURI} are set up for re-use.
   * <p>
   * This method is re-entrant -if more than one thread attempts to authenticate
   * neither will block -but the field values with have those of the last caller.
   *
   * @return authenticated access token
   */
  public AccessToken authenticate() throws IOException {
    final AuthenticationRequest authenticationRequest;
    if (useKeystoneAuthentication) {
      authenticationRequest = keystoneAuthRequest;
    } else {
      authenticationRequest = authRequest;
    }

    LOG.debug("started authentication");
    return perform("authentication",
                   authUri,
                   new AuthenticationPost(authenticationRequest));
  }

  private class AuthenticationPost extends AuthMethodProcessor<AccessToken> {
    final AuthenticationRequest authenticationRequest;

    private AuthenticationPost(AuthenticationRequest authenticationRequest) {
      this.authenticationRequest = authenticationRequest;
    }

    @Override
    protected void setup(AuthPostMethod method) throws IOException {

      method.setRequestEntity(getAuthenticationRequst(authenticationRequest));
    }

    /**
     * specification says any of the 2xxs are OK, so list all
     * the standard ones
     * @return a set of 2XX status codes.
     */
    @Override
    protected int[] getAllowedStatusCodes() {
      return new int[]{
        SC_OK,
        SC_BAD_REQUEST,
        SC_CREATED,
        SC_ACCEPTED,
        SC_NON_AUTHORITATIVE_INFORMATION,
        SC_NO_CONTENT,
        SC_RESET_CONTENT,
        SC_PARTIAL_CONTENT,
        SC_MULTI_STATUS,
        SC_UNAUTHORIZED //if request unauthorized, try another method
      };
    }

    @Override
    public AccessToken extractResult(AuthPostMethod method) throws IOException {
      throwIfBadRequest(method, authenticationRequest);

      final AuthenticationResponse access =
        JSONUtil.toObject(method.getResponseBodyAsString(),
                          AuthenticationWrapper.class).getAccess();
      final List<Catalog> serviceCatalog = access.getServiceCatalog();

      StringBuilder catList = new StringBuilder();
      StringBuilder regionList = new StringBuilder();

      Endpoint swiftEndpoint = findSwiftEndpoint(serviceCatalog,
                                                 catList,
                                                 regionList);
      if (swiftEndpoint == null) {
        throw buildNoEndpointException(catList, regionList);
      }

      URI endpointURI = usePublicURL
          ? swiftEndpoint.getPublicURL()
          : swiftEndpoint.getInternalURL();
      URI objectLocation = buildObjectLocation(endpointURI, swiftEndpoint);
      AccessToken accessToken = access.getToken();

      setAuthDetails(endpointURI, objectLocation, accessToken);

      if (LOG.isDebugEnabled()) {
        LOG.debug("authenticated against " + endpointURI);
      }
      createDefaultContainer();
      return accessToken;
    }
  }

  /**
   * Throw an authentication failure exception when the server rejects the
   * request as a bad request.
   *
   * @param method the executed auth method
   * @param request the authentication request that was sent
   * @throws SwiftAuthenticationFailedException the auth request was rejected
   */
  private void throwIfBadRequest(AuthPostMethod method,
                                 AuthenticationRequest request)
      throws SwiftAuthenticationFailedException {
    if (method.getStatusCode() == SC_BAD_REQUEST) {
      throw new SwiftAuthenticationFailedException(
          request.toString(), "POST", authUri, method);
    }
  }

  /**
   * Search the service catalog for a Swift endpoint matching the configured
   * region.
   *
   * @param serviceCatalog catalog returned by the authentication service
   * @param catList builder receiving catalog descriptions for diagnostics
   * @param regionList builder receiving endpoint descriptions for diagnostics
   * @return the matching Swift endpoint, or null if none was found
   */
  private Endpoint findSwiftEndpoint(List<Catalog> serviceCatalog,
                                     StringBuilder catList,
                                     StringBuilder regionList) {
    for (Catalog catalog : serviceCatalog) {
      appendCatalogInfo(catalog, catList);
      if (isSwiftCatalog(catalog)) {
        Endpoint endpoint = findMatchingEndpoint(catalog, regionList);
        if (endpoint != null) {
          return endpoint;
        }
      }
    }
    return null;
  }

  /**
   * Determine whether a catalog entry represents the Swift object store.
   *
   * @param catalog catalog entry
   * @return true if this catalog entry is a Swift service
   */
  private boolean isSwiftCatalog(Catalog catalog) {
    String name = catalog.getName();
    String type = catalog.getType();
    return name.equals(SERVICE_CATALOG_SWIFT)
        || name.equals(SERVICE_CATALOG_CLOUD_FILES)
        || type.equals(SERVICE_CATALOG_OBJECT_STORE);
  }

