  /**
   * Find the first endpoint within a Swift catalog that matches the configured
   * region.
   *
   * @param catalog Swift catalog entry
   * @param regionList builder receiving endpoint descriptions for diagnostics
   * @return the matching endpoint, or null if none was found
   */
  private Endpoint findMatchingEndpoint(Catalog catalog,
                                          StringBuilder regionList) {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Found swift catalog as " + catalog.getName()
                + " => " + catalog.getType());
    }
    for (Endpoint endpoint : catalog.getEndpoints()) {
      appendEndpointInfo(endpoint, regionList);
      if (region == null || region.equals(endpoint.getRegion())) {
        return endpoint;
      }
    }
    return null;
  }

