   *
   * @return a new HttpClient instance
   */
  private HttpClient createHttpClient() {
    final HttpClient client = new HttpClient();
    if (proxyHost != null) {
      client.getParams().setParameter(ConnRoutePNames.DEFAULT_PROXY,
              new HttpHost(proxyHost, proxyPort));
    }
    return client;
  }

  /**
   * Determine whether a failed auth response should trigger a Keystone fallback.
   *
   * @param statusCode HTTP status code
   * @param method executed method
   * @return true if Keystone authentication should be attempted
   */
  private boolean shouldFallbackToKeystone(int statusCode, HttpMethod method) {
    return (statusCode == HttpStatus.SC_UNAUTHORIZED
            || statusCode == HttpStatus.SC_BAD_REQUEST)
            && method instanceof AuthPostMethod
            && !useKeystoneAuthentication;
  }

  /**
