   *
   * @param method auth method to update and re-execute
   * @param client HTTP client to execute the request with
   * @return the status code of the retried request
   * @throws IOException on any failure
   */
  private int attemptKeystoneAuth(AuthPostMethod method, HttpClient client)
      throws IOException {
    if (LOG.isDebugEnabled()) {
      LOG.debug("Operation failed with status " + method.getStatusCode() +
               " attempting keystone auth");
    }
    useKeystoneAuthentication = true;
    method.setRequestEntity(getAuthenticationRequst(keystoneAuthRequest));
    return execWithDebugOutput(method, client);
