  /**
   * Determine whether the status code indicates an unauthorized request.
   *
   * @param statusCode HTTP status code
   * @return true if the status is unauthorized
   */
  private boolean isUnauthorized(int statusCode) {
    return statusCode == HttpStatus.SC_UNAUTHORIZED;
  }

  /**
   * Handle an unauthorized response by either failing (for auth requests) or
   * re-authenticating and retrying the original request.
   *
   * @param method original method to retry
   * @param client HTTP client to execute the retry with
   * @param <M> method type
   * @return the status code of the retried request
   * @throws IOException on any failure
   */
  private <M extends HttpMethod> int handleUnauthorized(M method,
                                                        HttpClient client)
      throws IOException {
    if (method instanceof AuthPostMethod) {
      throw new SwiftAuthenticationFailedException(authRequest.toString(),
                                                   "auth",
                                                   authUri,
                                                   method);
    }
    if (LOG.isDebugEnabled()) {
      LOG.debug("Reauthenticating");
    }
    authenticate();
    if (LOG.isDebugEnabled()) {
      LOG.debug("Retrying original request");
    }
    return execWithDebugOutput(method, client);
  }

  /**
   * Execute the request with the request and response logged at debug level
   * @param method method to execute
   * @param client client to use
   * @param <M> method type
   * @return the status code
   * @throws IOException any failure reported by the HTTP client.
   */
  private <M extends HttpMethod> int execWithDebugOutput(M method,
                                                         HttpClient client) throws
          IOException {
    if (LOG.isDebugEnabled()) {
      StringBuilder builder = new StringBuilder(
              method.getName() + " " + method.getURI() + "\n");
      for (Header header : method.getRequestHeaders()) {
        builder.append(header.toString());
      }
      LOG.debug(builder);
    }
    int statusCode = client.executeMethod(method);
    if (LOG.isDebugEnabled()) {
      LOG.debug("Status code = " + statusCode);
    }
    return statusCode;
  }

