  /**
   * Authenticate to Openstack Keystone
   * As well as returning the access token, the member fields {@link #token},
   * {@link #endpointURI} and {@link #objectLocationURI} are set up for re-use.
   * <p>
   * This method is re-entrant -if more than one thread attempts to authenticate
   * neither will block -but the field values with have those of the last caller.
   *
   * @return authenticated access token
   */
  public AccessToken authenticate() throws IOException {
    final AuthenticationRequest authenticationRequest;
    if (useKeystoneAuthentication) {
      authenticationRequest = keystoneAuthRequest;
    } else {
      authenticationRequest = authRequest;
    }

    LOG.debug("started authentication");
    return perform("authentication",
                   authUri,
                   new AuthenticationPost(authenticationRequest));
  }

  /**
   * Holds the result of searching the service catalog for a Swift endpoint.
   */
  private static class EndpointSelection {
    final URI endpointURI;
    final Endpoint swiftEndpoint;
    final StringBuilder catalogList;
    final StringBuilder regionList;

    private EndpointSelection(URI endpointURI,
                              Endpoint swiftEndpoint,
                              StringBuilder catalogList,
                              StringBuilder regionList) {
      this.endpointURI = endpointURI;
      this.swiftEndpoint = swiftEndpoint;
      this.catalogList = catalogList;
      this.regionList = regionList;
    }
  }

  /**
   * Determine whether a catalog entry represents a Swift service.
   *
   * @param catalog catalog entry
   * @return true if the catalog is a Swift service
   */
  private static boolean isSwiftCatalog(Catalog catalog) {
    String name = catalog.getName();
    String type = catalog.getType();
    return name.equals(SERVICE_CATALOG_SWIFT)
        || name.equals(SERVICE_CATALOG_CLOUD_FILES)
        || type.equals(SERVICE_CATALOG_OBJECT_STORE);
  }

  /**
   * Select the endpoint URI for an endpoint if it matches the configured region.
   *
   * @param endpoint endpoint candidate
   * @return the chosen URI, or null if the region does not match
   */
  private URI selectEndpointURI(Endpoint endpoint) {
    String endpointRegion = endpoint.getRegion();
    if (region == null || endpointRegion.equals(region)) {
      return usePublicURL ? endpoint.getPublicURL() : endpoint.getInternalURL();
    }
    return null;
  }

  /**
   * Search the service catalog for a Swift endpoint matching the configured region.
   *
   * @param serviceCatalog catalog of services
   * @return selection containing the chosen endpoint and diagnostic lists
   */
  private EndpointSelection findSwiftEndpoint(List<Catalog> serviceCatalog) {
    URI endpointURI = null;
    Endpoint swiftEndpoint = null;
    StringBuilder catList = new StringBuilder();
    StringBuilder regionList = new StringBuilder();

    for (Catalog catalog : serviceCatalog) {
      String name = catalog.getName();
      String type = catalog.getType();
      String descr = String.format("[%s: %s]; ", name, type);
      catList.append(descr);
      if (LOG.isDebugEnabled()) {
        LOG.debug("Catalog entry " + descr);
      }
      if (isSwiftCatalog(catalog)) {
        if (LOG.isDebugEnabled()) {
          LOG.debug("Found swift catalog as " + name + " => " + type);
        }
        for (Endpoint endpoint : catalog.getEndpoints()) {
          String endpointRegion = endpoint.getRegion();
          URI publicURL = endpoint.getPublicURL();
          URI internalURL = endpoint.getInternalURL();
          descr = String.format("[%s => %s / %s]; ",
                                endpointRegion,
                                publicURL,
                                internalURL);
          regionList.append(descr);
          if (LOG.isDebugEnabled()) {
            LOG.debug("Endpoint " + descr);
          }
          URI selected = selectEndpointURI(endpoint);
          if (selected != null) {
            endpointURI = selected;
            swiftEndpoint = endpoint;
            break;
          }
        }
      }
    }
    return new EndpointSelection(endpointURI, swiftEndpoint, catList, regionList);
  }

  /**
   * Build the diagnostic message used when no Swift endpoint is found.
   *
   * @param selection endpoint search result
   * @return diagnostic message
   */
  private String buildNoEndpointMessage(EndpointSelection selection) {
    return "Could not find swift service from auth URL "
           + authUri
           + " and region '" + region + "'. "
           + "Categories: " + selection.catalogList
           + ((selection.regionList.length() > 0) ?
              ("regions: " + selection.regionList)
              : "No regions");
  }

  /**
   * Build the object-location URI from the chosen Swift endpoint.
   *
   * @param endpointURI swift endpoint URI
   * @param swiftEndpoint swift endpoint details
   * @return object location URI
   * @throws SwiftException if the URI cannot be constructed
   */
  private URI buildObjectLocation(URI endpointURI, Endpoint swiftEndpoint) throws SwiftException {
    String path = SWIFT_OBJECT_AUTH_ENDPOINT + swiftEndpoint.getTenantId();
    String host = endpointURI.getHost();
    try {
      return new URI(endpointURI.getScheme(),
                     null,
                     host,
                     endpointURI.getPort(),
                     path,
                     null,
                     null);
    } catch (URISyntaxException e) {
      throw new SwiftException("object endpoint URI is incorrect: "
                               + endpointURI
                               + " + " + path,
                               e);
    }
  }

  private class AuthenticationPost extends AuthMethodProcessor<AccessToken> {
    final AuthenticationRequest authenticationRequest;

    private AuthenticationPost(AuthenticationRequest authenticationRequest) {
      this.authenticationRequest = authenticationRequest;
    }

    @Override
    protected void setup(AuthPostMethod method) throws IOException {

      method.setRequestEntity(getAuthenticationRequst(authenticationRequest));
    }

    /**
     * specification says any of the 2xxs are OK, so list all
     * the standard ones
     * @return a set of 2XX status codes.
     */
    @Override
    protected int[] getAllowedStatusCodes() {
      return new int[]{
        SC_OK,
        SC_BAD_REQUEST,
        SC_CREATED,
        SC_ACCEPTED,
        SC_NON_AUTHORITATIVE_INFORMATION,
        SC_NO_CONTENT,
        SC_RESET_CONTENT,
        SC_PARTIAL_CONTENT,
        SC_MULTI_STATUS,
        SC_UNAUTHORIZED //if request unauthorized, try another method
      };
    }

    @Override
    public AccessToken extractResult(AuthPostMethod method) throws IOException {
      validateAuthenticationResponse(method);

      final AuthenticationResponse access =
        JSONUtil.toObject(method.getResponseBodyAsString(),
                          AuthenticationWrapper.class).getAccess();
      EndpointSelection selection = findSwiftEndpoint(access.getServiceCatalog());

      if (selection.endpointURI == null) {
        throw new SwiftInvalidResponseException(
            buildNoEndpointMessage(selection),
            SC_OK,
            "authenticating",
            authUri);
      }

      URI objectLocation = buildObjectLocation(selection.endpointURI, selection.swiftEndpoint);
      AccessToken accessToken = access.getToken();

      setAuthDetails(selection.endpointURI, objectLocation, accessToken);

      if (LOG.isDebugEnabled()) {
        LOG.debug("authenticated against " + selection.endpointURI);
      }
      createDefaultContainer();
      return accessToken;
    }

    /**
     * Validate the authentication response, throwing on bad request.
     *
     * @param method authentication POST method
     * @throws SwiftAuthenticationFailedException if the request was rejected
     */
    private void validateAuthenticationResponse(AuthPostMethod method)
        throws SwiftAuthenticationFailedException {
      if (method.getStatusCode() == SC_BAD_REQUEST) {
        throw new SwiftAuthenticationFailedException(
          authenticationRequest.toString(), "POST", authUri, method);
      }
    }
  }

  private StringRequestEntity getAuthenticationRequst(AuthenticationRequest authenticationRequest)
    throws IOException {
    final String data = JSONUtil.toJSON(new AuthenticationRequestWrapper(
            authenticationRequest));
    if (LOG.isDebugEnabled()) {
      LOG.debug("Authenticating with " + authenticationRequest);
    }
    return toJsonEntity(data);
  }

  /**
   * create default container if it doesn't exist for Hadoop Swift integration.
   * non-reentrant, as this should only be needed once.
   *
   * @throws IOException IO problems.
   */
  private synchronized void createDefaultContainer() throws IOException {
    createContainer(container);
  }

  /**
   * Create a container -if it already exists, do nothing
   *
   * @param containerName the container name
   * @throws IOException IO problems
   * @throws SwiftBadRequestException invalid container name
   * @throws SwiftInvalidResponseException error from the server
   */
  public void createContainer(String containerName) throws IOException {
    SwiftObjectPath objectPath = new SwiftObjectPath(containerName, "");
    try {
      //see if the data is there
      headRequest("createContainer", objectPath, NEWEST);
    } catch (FileNotFoundException ex) {
      int status = createContainerWithPut(objectPath);
      if (status == SC_BAD_REQUEST) {
        throw new SwiftBadRequestException(
          "Bad request -authentication failure or bad container name?",
          status,
          "PUT",
          null);
      }
      if (!isSuccessfulContainerCreation(status)) {
        throw new SwiftInvalidResponseException("Couldn't create container "
                + containerName +
                " for storing data in Swift." +
                " Try to create container " +
                containerName + " manually ",
                status,
                "PUT",
                null);
      } else {
        throw ex;
      }
    }
  }

  /**
   * Attempt to create a container with a PUT request.
   *
   * @param objectPath path to the container
   * @return the HTTP status code, or {@link #SC_NOT_FOUND} if the request failed
   * @throws IOException on other IO problems
   */
  private int createContainerWithPut(SwiftObjectPath objectPath) throws IOException {
    try {
      return putRequest(objectPath);
    } catch (FileNotFoundException e) {
      return SC_NOT_FOUND;
    }
  }

  /**
   * Check whether a status code indicates a successful container creation.
   *
   * @param status HTTP status code
   * @return true if the container was created successfully
   */
  private boolean isSuccessfulContainerCreation(int status) {
    return isStatusCodeExpected(status,
                                SC_OK,
                                SC_CREATED,
                                SC_ACCEPTED,
                                SC_NO_CONTENT);
  }

  /**
   * Trigger an initial auth operation if some of the needed
   * fields are missing
   *
   * @throws IOException on problems
   */
  private void authIfNeeded() throws IOException {
    if (getEndpointURI() == null) {
      authenticate();
    }
  }

  /**
   * Pre-execution actions to be performed by methods. Currently this
   * <ul>
   *   <li>Logs the operation at TRACE</li>
   *   <li>Authenticates the client -if needed</li>
   * </ul>
   * @throws IOException
   */
  private void preRemoteCommand(String operation) throws IOException {
    if (LOG.isTraceEnabled()) {
      LOG.trace("Executing " + operation);
