	//{{{ parseCommandLine() method
	private static StartupOptions parseCommandLine(String[] args)
	{
		StartupOptions options = new StartupOptions();
		options.settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");
		options.userDir = System.getProperty("user.dir");

		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				options.logLevel = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}

		boolean endOpts = false;
		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;
			if(arg.length() == 0)
			{
				args[i] = null;
				continue;
			}
			if(!arg.startsWith("-") || endOpts)
				continue;

			if(arg.equals("--"))
				endOpts = true;
			else if(arg.equals("-usage"))
				printUsageAndExit();
			else if(arg.equals("-version"))
				printVersionAndExit();
			else if(arg.equals("-nosettings"))
				options.settingsDirectory = null;
			else if(arg.startsWith("-settings="))
				options.settingsDirectory = arg.substring(10);
			else if(arg.startsWith("-noserver"))
				options.portFile = null;
			else if(arg.equals("-server"))
				options.portFile = "server";
			else if(arg.startsWith("-server="))
				options.portFile = arg.substring(8);
			else if(arg.startsWith("-background"))
				background = true;
			else if(arg.equals("-nogui"))
				options.gui = false;
			else if(arg.equals("-norestore"))
				options.restore = false;
			else if(arg.equals("-noplugins"))
				options.noPlugins = true;
			else if(arg.equals("-nostartupscripts"))
				options.noStartupScripts = true;
			else if(arg.startsWith("-run="))
				options.scriptFile = arg.substring(5);
			else
				unknownOption(arg);

			args[i] = null;
		}

		return options;
	} //}}}

