	//{{{ parseCommandLine() method
	private static CommandLineOptions parseCommandLine(String[] args)
	{
		CommandLineOptions opts = new CommandLineOptions();
		opts.level = Log.WARNING;

		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				opts.level = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}

		opts.settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");
		opts.portFile = "server";
		opts.restore = true;
		opts.gui = true;
		opts.noPlugins = false;
		opts.noStartupScripts = false;
		opts.scriptFile = null;
		opts.userDir = System.getProperty("user.dir");

		boolean endOpts = false;
		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;
			if(arg.length() == 0)
			{
				args[i] = null;
				continue;
			}
			if(arg.startsWith("-") && !endOpts)
			{
				if(arg.equals("--"))
					endOpts = true;
				else
					processCommandLineOption(arg,opts);
				args[i] = null;
			}
		}

		return opts;
	} //}}}

	//{{{ processCommandLineOption() method
	private static void processCommandLineOption(String arg,
		CommandLineOptions opts)
	{
		if(arg.equals("-usage"))
		{
			version();
			System.err.println();
			usage();
			System.exit(1);
		}
		else if(arg.equals("-version"))
		{
			version();
			System.exit(1);
		}
		else if(arg.equals("-nosettings"))
			opts.settingsDirectory = null;
		else if(arg.startsWith("-settings="))
			opts.settingsDirectory = arg.substring(10);
		else if(arg.startsWith("-noserver"))
			opts.portFile = null;
		else if(arg.equals("-server"))
			opts.portFile = "server";
		else if(arg.startsWith("-server="))
			opts.portFile = arg.substring(8);
		else if(arg.startsWith("-background"))
			opts.background = true;
		else if(arg.equals("-nogui"))
			opts.gui = false;
		else if(arg.equals("-norestore"))
			opts.restore = false;
		else if(arg.equals("-noplugins"))
			opts.noPlugins = true;
		else if(arg.equals("-nostartupscripts"))
			opts.noStartupScripts = true;
		else if(arg.startsWith("-run="))
			opts.scriptFile = arg.substring(5);
		else
		{
			System.err.println("Unknown option: " + arg);
			usage();
			System.exit(1);
		}
	} //}}}

	//{{{ tryConnectServer() method
	private static boolean tryConnectServer(String portFile,
		boolean restore, String[] args, String scriptFile)
	{
		if(portFile == null || !new File(portFile).exists())
			return false;

		try
		{
			BufferedReader in = new BufferedReader(new FileReader(portFile));
			String check = in.readLine();
			if(!check.equals("b"))
				throw new Exception("Wrong port file format");

			int port = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"),port);
			DataOutputStream out = new DataOutputStream(
				socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(restore,args,scriptFile);

			out.writeUTF(script);

			out.close();

			System.exit(0);
			return true;
		}
		catch(Exception e)
		{
			// ok, this one seems to confuse newbies
			// endlessly, so log it as NOTICE, not
			// ERROR
			Log.log(Log.NOTICE,jEdit.class,"An error occurred"
				+ " while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE,jEdit.class,"This probably means that"
				+ " jEdit crashed and/or exited abnormally");
			Log.log(Log.NOTICE,jEdit.class,"the last time it was run.");
			Log.log(Log.NOTICE,jEdit.class,"If you don't"
				+ " know what this means, don't worry.");
			Log.log(Log.NOTICE,jEdit.class,e);
			return false;
		}
	} //}}}

