	//{{{ main() method
	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		checkJavaVersion();

		settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");
		StartupOptions opts = parseCommandLine(args);

		if(settingsDirectory != null && opts.portFile != null)
			opts.portFile = MiscUtilities.constructPath(settingsDirectory,opts.portFile);
		else
			opts.portFile = null;

		Log.init(true,opts.level);

		if(tryConnectToRunningInstance(opts,args))
			return;

		if(settingsDirectory != null && !new File(settingsDirectory,"nosplash").exists())
			GUIUtilities.showSplashScreen();

		Writer stream = initSettingsDirectory();

		Log.setLogWriter(stream);

		Log.log(Log.NOTICE,jEdit.class,"jEdit version " + getVersion());
		Log.log(Log.MESSAGE,jEdit.class,"Settings directory is "
			+ settingsDirectory);

		initServer(opts);

		initCore(opts);

		startPlugins();

		runStartupScripts(opts);

		runScript(opts);

		propertiesChanged();

		GUIUtilities.advanceSplashProgress();

		StartupResult result = openFilesAndRestore(opts,args);

		createInitialView(result.buffer,result.splitConfig,opts.gui);
	} //}}}

	//{{{ checkJavaVersion() method
	private static void checkJavaVersion()
	{
		String javaVersion = System.getProperty("java.version");
		if(javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version "
				+ javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			System.exit(1);
		}
	} //}}}

	//{{{ StartupOptions class
	private static class StartupOptions
	{
		int level = Log.WARNING;
		boolean restore = true;
		boolean gui = true;
		boolean noPlugins = false;
		boolean noStartupScripts = false;
		String portFile = "server";
		String scriptFile = null;
		String userDir = System.getProperty("user.dir");
	} //}}}

	//{{{ parseCommandLine() method
	private static StartupOptions parseCommandLine(String[] args)
	{
		StartupOptions opts = new StartupOptions();

		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				opts.level = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}

		boolean endOpts = false;

		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;
			if(arg.length() == 0)
			{
				args[i] = null;
				continue;
			}
			if(!arg.startsWith("-") || endOpts)
				continue;

			if(arg.equals("--"))
				endOpts = true;
			else if(arg.equals("-usage"))
			{
				version();
				System.err.println();
				usage();
				System.exit(1);
			}
			else if(arg.equals("-version"))
			{
				version();
				System.exit(1);
			}
			else if(arg.equals("-nosettings"))
				settingsDirectory = null;
			else if(arg.startsWith("-settings="))
				settingsDirectory = arg.substring(10);
			else if(arg.startsWith("-noserver"))
				opts.portFile = null;
			else if(arg.equals("-server"))
				opts.portFile = "server";
			else if(arg.startsWith("-server="))
				opts.portFile = arg.substring(8);
			else if(arg.startsWith("-background"))
				background = true;
			else if(arg.equals("-nogui"))
				opts.gui = false;
			else if(arg.equals("-norestore"))
				opts.restore = false;
			else if(arg.equals("-noplugins"))
				opts.noPlugins = true;
			else if(arg.equals("-nostartupscripts"))
				opts.noStartupScripts = true;
			else if(arg.startsWith("-run="))
				opts.scriptFile = arg.substring(5);
			else
			{
				System.err.println("Unknown option: "
					+ arg);
				usage();
				System.exit(1);
			}
			args[i] = null;
		}

		return opts;
	} //}}}

	//{{{ tryConnectToRunningInstance() method
	private static boolean tryConnectToRunningInstance(StartupOptions opts,
		String[] args)
	{
		if(opts.portFile == null || !new File(opts.portFile).exists())
			return false;

		try
		{
			BufferedReader in = new BufferedReader(new FileReader(opts.portFile));
			String check = in.readLine();
			if(!check.equals("b"))
				throw new Exception("Wrong port file format");

			int port = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"),port);
			DataOutputStream out = new DataOutputStream(
				socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(opts.restore,args,opts.scriptFile);

			out.writeUTF(script);

			out.close();

			System.exit(0);
		}
		catch(Exception e)
		{
			Log.log(Log.NOTICE,jEdit.class,"An error occurred"
				+ " while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE,jEdit.class,"This probably means that"
				+ " jEdit crashed and/or exited abnormally");
			Log.log(Log.NOTICE,jEdit.class,"the last time it was run.");
			Log.log(Log.NOTICE,jEdit.class,"If you don't"
				+ " know what this means, don't worry.");
			Log.log(Log.NOTICE,jEdit.class,e);
		}

		return false;
	} //}}}

	//{{{ initSettingsDirectory() method
	private static Writer initSettingsDirectory()
	{
		if(settingsDirectory == null)
			return null;

		File _settingsDirectory = new File(settingsDirectory);
		if(!_settingsDirectory.exists())
			_settingsDirectory.mkdirs();
		File _macrosDirectory = new File(settingsDirectory,"macros");
		if(!_macrosDirectory.exists())
			_macrosDirectory.mkdir();

		String logPath = MiscUtilities.constructPath(
			settingsDirectory,"activity.log");

		backupSettingsFile(new File(logPath));

		try
		{
			return new BufferedWriter(new FileWriter(logPath));
		}
		catch(Exception e)
		{
			e.printStackTrace();
			return null;
		}
	} //}}}

	//{{{ initServer() method
	private static void initServer(StartupOptions opts)
	{
		if(opts.portFile != null)
		{
			server = new EditServer(opts.portFile);
			if(!server.isOK())
				server = null;
		}
		else if(background)
		{
			background = false;
			System.err.println("You cannot specify both the"
				+ " -background and -noserver switches");
		}
	} //}}}

	//{{{ initCore() method
	private static void initCore(StartupOptions opts)
	{
		initMisc();
		initSystemProperties();
		if(jEditHome != null)
			initSiteProperties();
		GUIUtilities.advanceSplashProgress();

		BeanShell.init();

		initUserProperties();
		initPLAF();

		initJava14();

		initActions();
		initDockables();

		GUIUtilities.advanceSplashProgress();

		VFSManager.init();

		if(!opts.noPlugins)
			initPlugins();

		loadHistoryAndRecent();

		GUIUtilities.advanceSplashProgress();

		initModesAndSearch();

		GUIUtilities.advanceSplashProgress();

		SearchAndReplace.load();

		GUIUtilities.advanceSplashProgress();
	} //}}}

	//{{{ initJava14() method
	private static void initJava14()
	{
		if(OperatingSystem.hasJava14()
			&& System.getProperty("jedit.nojava14") == null)
		{
			try
			{
				ClassLoader loader = jEdit.class.getClassLoader();
				Class clazz;
				if(loader != null)
					clazz = loader.loadClass("org.gjt.sp.jedit.Java14");
				else
					clazz = Class.forName("org.gjt.sp.jedit.Java14");
				java.lang.reflect.Method meth = clazz
					.getMethod("init",new Class[0]);
				meth.invoke(null,new Object[0]);
			}
			catch(Exception e)
			{
				Log.log(Log.ERROR,jEdit.class,e);
				System.exit(1);
			}
		}
	} //}}}

	//{{{ loadHistoryAndRecent() method
	private static void loadHistoryAndRecent()
	{
		if(settingsDirectory != null)
		{
			File history = new File(MiscUtilities.constructPath(
				settingsDirectory,"history"));
			if(history.exists())
				historyModTime = history.lastModified();
			HistoryModel.loadHistory(history);

			File recent = new File(MiscUtilities.constructPath(
				settingsDirectory,"recent.xml"));
			if(recent.exists())
				recentModTime = recent.lastModified();
			BufferHistory.load(recent);
		}
	} //}}}

	//{{{ initModesAndSearch() method
	private static void initModesAndSearch()
	{
		sortBuffers = getBooleanProperty("sortBuffers");
		sortByName = getBooleanProperty("sortByName");

		reloadModes();
	} //}}}

	//{{{ startPlugins() method
	private static void startPlugins()
	{
		for(int i = 0; i < jars.size(); i++)
		{
			((EditPlugin.JAR)jars.elementAt(i)).getClassLoader()
				.startAllPlugins();
		}
	} //}}}

	//{{{ runStartupScripts() method
	private static void runStartupScripts(StartupOptions opts)
	{
		Macros.loadMacros();

		if(!opts.noStartupScripts && jEditHome != null)
		{
			String path = MiscUtilities.constructPath(jEditHome,"startup");
			File file = new File(path);
			if(file.exists())
				runStartupScriptsInDirectory(file);
		}

		if(!opts.noStartupScripts && settingsDirectory != null)
		{
			String path = MiscUtilities.constructPath(settingsDirectory,"startup");
			File file = new File(path);
			if(!file.exists())
				file.mkdirs();
			else
				runStartupScriptsInDirectory(file);
		}
	} //}}}

	//{{{ StartupResult class
	private static class StartupResult
