		Buffer buffer;
		String splitConfig;
	} //}}}

	//{{{ openFilesAndRestore() method
	private static StartupResult openFilesAndRestore(StartupOptions opts,
		String[] args)
	{
		StartupResult result = new StartupResult();

		result.buffer = openFiles(null,opts.userDir,args);
		if(result.buffer != null)
			opts.gui = true;

		if(opts.restore && settingsDirectory != null
			&& jEdit.getBooleanProperty("restore")
			&& (bufferCount == 0 || jEdit.getBooleanProperty("restore.cli")))
		{
			result.splitConfig = restoreOpenFiles();
		}

		if(bufferCount == 0 && opts.gui)
			newFile(null);

		return result;
	} //}}}

	//{{{ createInitialView() method
	private static void createInitialView(final Buffer buffer,
		final String splitConfig, final boolean gui)
	{
		GUIUtilities.advanceSplashProgress();

		SwingUtilities.invokeLater(new Runnable() {
			public void run()
			{
				EditBus.send(new EditorStarted(null));

				if(gui)
				{
					if(buffer != null)
						newView(null,buffer);
					else
						newView(null,splitConfig);
				}

				// Start I/O threads
				VFSManager.start();

				// Start edit server
				if(server != null)
					server.start();

				GUIUtilities.hideSplashScreen();

				Log.log(Log.MESSAGE,jEdit.class,"Startup "
					+ "complete");

				reportPluginErrors();

				// in one case not a single AWT class will
				// have been touched (splash screen off +
				// -nogui -nobackground switches on command
				// line)
				Toolkit.getDefaultToolkit();
			}
		});
	} //}}}

	//{{{ reportPluginErrors() method
	private static void reportPluginErrors()
	{
		if(pluginErrors != null)
		{
			String caption = jEdit.getProperty(
				"plugin-error.caption" + (pluginErrors.size() == 1
				? "-1" : ""),new Integer[] {
				new Integer(pluginErrors.size()) });

			new ErrorListDialog(
				jEdit.getFirstView(),
				jEdit.getProperty("plugin-error.title"),
				caption,pluginErrors,true);
			pluginErrors.removeAllElements();
		}
	} //}}}

