	//{{{ main() method
	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		checkJavaVersion();

		StartupOptions options = new StartupOptions();
		options.logLevel = parseLogLevel(args);
		parseCommandLine(args, options);

		String portFile = computePortFilePath(options.portFileName);

		Log.init(true, options.logLevel);

		tryConnectToRunningInstance(portFile, options.restore,
			args, options.scriptFile);

		showSplashScreenIfAllowed();

		Writer stream = initSettingsDirectoryAndLog();
		Log.setLogWriter(stream);

		Log.log(Log.NOTICE,jEdit.class,"jEdit version " + getVersion());
		Log.log(Log.MESSAGE,jEdit.class,"Settings directory is "
			+ settingsDirectory);

		initEditServer(portFile);

		initCoreSubsystems(options.noPlugins);
		initJava14Support();

		startPluginsAndRunStartupScripts(options.noStartupScripts,
			options.scriptFile, options.userDir);

		propertiesChanged();
		GUIUtilities.advanceSplashProgress();

		Buffer buffer = openFiles(null, options.userDir, args);
		boolean gui = options.gui;
		if(buffer != null)
			gui = true;

		String splitConfig = restoreOpenFilesIfNeeded(options.restore);

		if(bufferCount == 0 && gui)
			newFile(null);

		createInitialView(buffer, splitConfig, gui);
	} //}}}

	//{{{ StartupOptions class
	/**
	 * Holds command-line options parsed during startup.
	 */
	private static class StartupOptions
	{
		int logLevel = Log.WARNING;
		String portFileName = "server";
		boolean restore = true;
		boolean gui = true;
		boolean noPlugins = false;
		boolean noStartupScripts = false;
		String scriptFile = null;
		String userDir = System.getProperty("user.dir");
		boolean endOpts = false;
	} //}}}

	//{{{ checkJavaVersion() method
	/**
	 * Ensures the JVM is new enough to run jEdit.
	 */
	private static void checkJavaVersion()
	{
		String javaVersion = System.getProperty("java.version");
		if(javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version "
				+ javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			System.exit(1);
		}
	} //}}}

	//{{{ parseLogLevel() method
	/**
	 * Reads the optional numeric log level from the first argument.
	 */
	private static int parseLogLevel(String[] args)
	{
		int level = Log.WARNING;
		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				level = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}
		return level;
	} //}}}

	//{{{ parseCommandLine() method
	/**
	 * Parses command-line arguments and updates startup state.
	 */
	private static void parseCommandLine(String[] args, StartupOptions options)
	{
		settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");

		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;
			else if(arg.length() == 0)
				args[i] = null;
			else if(arg.startsWith("-") && !options.endOpts)
			{
				if(!processOption(arg, options))
				{
					System.err.println("Unknown option: "
						+ arg);
					usage();
					System.exit(1);
				}
				args[i] = null;
			}
		}
	} //}}}

	//{{{ processOption() method
	/**
	 * Dispatches a single command-line option to the appropriate handler.
	 * @return true if the option was recognised
	 */
	private static boolean processOption(String arg, StartupOptions options)
	{
		if(arg.equals("--"))
		{
			options.endOpts = true;
			return true;
		}

		if(handleInformationOption(arg))
			return true;
		if(handleSettingsOption(arg))
			return true;
		if(handleServerOption(arg, options))
			return true;
		if(handleRuntimeOption(arg, options))
			return true;

		return false;
	} //}}}

	//{{{ handleInformationOption() method
	/**
	 * Handles options that print information and exit.
	 */
	private static boolean handleInformationOption(String arg)
	{
		if(arg.equals("-usage"))
		{
			version();
			System.err.println();
			usage();
			System.exit(1);
			return true;
		}

		if(arg.equals("-version"))
		{
			version();
			System.exit(1);
			return true;
		}

		return false;
	} //}}}

	//{{{ handleSettingsOption() method
	/**
	 * Handles options that control the settings directory.
	 */
	private static boolean handleSettingsOption(String arg)
	{
		if(arg.equals("-nosettings"))
		{
			settingsDirectory = null;
			return true;
		}

		if(arg.startsWith("-settings="))
		{
			settingsDirectory = arg.substring(10);
			return true;
		}

		return false;
	} //}}}

	//{{{ handleServerOption() method
	/**
	 * Handles options that control the edit server port file.
	 */
	private static boolean handleServerOption(String arg, StartupOptions options)
	{
		if(arg.startsWith("-noserver"))
		{
			options.portFileName = null;
			return true;
		}

		if(arg.equals("-server"))
		{
			options.portFileName = "server";
			return true;
		}

		if(arg.startsWith("-server="))
		{
			options.portFileName = arg.substring(8);
			return true;
		}

		return false;
	} //}}}

	//{{{ handleRuntimeOption() method
	/**
	 * Handles runtime and plugin-related command-line options.
	 */
	private static boolean handleRuntimeOption(String arg, StartupOptions options)
	{
		if(arg.startsWith("-background"))
		{
			background = true;
			return true;
		}

		if(arg.equals("-nogui"))
		{
			options.gui = false;
			return true;
		}

		if(arg.equals("-norestore"))
		{
			options.restore = false;
			return true;
		}

		if(arg.equals("-noplugins"))
		{
			options.noPlugins = true;
			return true;
		}

		if(arg.equals("-nostartupscripts"))
		{
			options.noStartupScripts = true;
			return true;
		}

		if(arg.startsWith("-run="))
		{
			options.scriptFile = arg.substring(5);
			return true;
		}

		return false;
	} //}}}

	//{{{ computePortFilePath() method
	/**
	 * Builds the full path to the server port file.
	 */
	private static String computePortFilePath(String portFileName)
	{
		if(settingsDirectory != null && portFileName != null)
			return MiscUtilities.constructPath(settingsDirectory,portFileName);
		else
			return null;
	} //}}}

	//{{{ tryConnectToRunningInstance() method
	/**
	 * Attempts to hand off startup to an already running jEdit instance.
	 */
	private static void tryConnectToRunningInstance(String portFile,
		boolean restore, String[] args, String scriptFile)
	{
		if(portFile == null || !new File(portFile).exists())
			return;

		try
		{
			BufferedReader in = new BufferedReader(new FileReader(portFile));
			String check = in.readLine();
			if(!check.equals("b"))
				throw new Exception("Wrong port file format");

			int port = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"),port);
			DataOutputStream out = new DataOutputStream(
				socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(restore,args,scriptFile);

			out.writeUTF(script);

			out.close();

			System.exit(0);
		}
		catch(Exception e)
		{
			// ok, this one seems to confuse newbies
			// endlessly, so log it as NOTICE, not
			// ERROR
			Log.log(Log.NOTICE,jEdit.class,"An error occurred"
				+ " while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE,jEdit.class,"This probably means that"
				+ " jEdit crashed and/or exited abnormally");
			Log.log(Log.NOTICE,jEdit.class,"the last time it was run.");
			Log.log(Log.NOTICE,jEdit.class,"If you don't"
				+ " know what this means, don't worry.");
			Log.log(Log.NOTICE,jEdit.class,e);
		}
	} //}}}

	//{{{ showSplashScreenIfAllowed() method
	/**
	 * Shows the splash screen unless the user has disabled it.
	 */
	private static void showSplashScreenIfAllowed()
	{
		// don't show splash screen if there is a file named
