private static void parseCommandLine(String[] args, StartupOptions options)
{
  settingsDirectory = MiscUtilities.constructPath(System.getProperty("user.home"),".jedit");
  for(int i = 0; i < args.length; i++)
  {
    String arg = args[i];
    if(arg == null)
      continue;
    else if(arg.length() == 0)
      args[i] = null;
    else if(arg.startsWith("-") && !options.endOpts)
    {
      if(!processOption(arg, options))
      {
        System.err.println("Unknown option: " + arg);
        usage();
        System.exit(1);
      }
      args[i] = null;
    }
  }
}

