	//{{{ parseCommandLine() method
	/**
	 * Parses the command-line arguments and returns the parsed options.
	 * @param args The command line arguments
	 */
	private static CommandLineOptions parseCommandLine(String[] args)
	{
		CommandLineOptions options = new CommandLineOptions();

		options.logLevel = parseLogLevel(args);
		options.args = args;
		settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");
		options.portFile = "server";
		options.restore = true;
		options.gui = true;
		options.noPlugins = false;
		options.noStartupScripts = false;
		options.userDir = System.getProperty("user.dir");
		options.scriptFile = null;

		boolean endOpts = false;
		for(int i = 0; i < args.length; i++)
			endOpts = processArgument(options,i,endOpts);

		if(settingsDirectory != null && options.portFile != null)
			options.portFile = MiscUtilities.constructPath(settingsDirectory,options.portFile);
		else
			options.portFile = null;

		return options;
	} //}}}

	//{{{ parseLogLevel() method
	/**
	 * Parses the optional numeric log level from the first argument.
	 * @param args The command line arguments
	 */
	private static int parseLogLevel(String[] args)
	{
		int level = Log.WARNING;
		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				level = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}
		return level;
	} //}}}

	//{{{ processArgument() method
	/**
	 * Processes a single command-line argument.
	 * @param options The parsed options
	 * @param index The argument index
	 * @param endOpts True if option processing has ended
	 * @return The updated end-of-options flag
	 */
	private static boolean processArgument(CommandLineOptions options,
		int index, boolean endOpts)
	{
		String arg = options.args[index];
		if(arg == null)
			return endOpts;
		if(arg.length() == 0)
		{
			options.args[index] = null;
			return endOpts;
		}
		if(arg.equals("--"))
		{
			options.args[index] = null;
			return true;
		}
		if(arg.startsWith("-") && !endOpts)
		{
			if(!processOption(arg,options))
			{
				System.err.println("Unknown option: "
					+ arg);
				usage();
				System.exit(1);
			}
			options.args[index] = null;
		}
		return endOpts;
	} //}}}

	//{{{ processOption() method
	/**
	 * Processes a single command-line option.
	 * @param arg The option argument
	 * @param options The options object to update
	 * @return True if the option was recognized, false otherwise
	 */
	private static boolean processOption(String arg, CommandLineOptions options)
	{
		if(arg.equals("-usage"))
		{
			version();
			System.err.println();
			usage();
			System.exit(1);
		}
		else if(arg.equals("-version"))
		{
			version();
			System.exit(1);
		}
		else if(arg.equals("-nosettings"))
			settingsDirectory = null;
		else if(arg.startsWith("-settings="))
			settingsDirectory = arg.substring(10);
		else if(arg.startsWith("-noserver"))
			options.portFile = null;
		else if(arg.equals("-server"))
			options.portFile = "server";
		else if(arg.startsWith("-server="))
			options.portFile = arg.substring(8);
		else if(arg.startsWith("-background"))
			background = true;
		else if(arg.equals("-nogui"))
			options.gui = false;
		else if(arg.equals("-norestore"))
			options.restore = false;
		else if(arg.equals("-noplugins"))
			options.noPlugins = true;
		else if(arg.equals("-nostartupscripts"))
			options.noStartupScripts = true;
		else if(arg.startsWith("-run="))
			options.scriptFile = arg.substring(5);
		else
			return false;

		return true;
	} //}}}

	//{{{ tryConnectToRunningInstance() method
	/**
	 * Attempts to connect to an already running jEdit instance.
	 * If the connection succeeds, this method does not return.
	 * @param options The parsed command-line options
	 * @return True if the application should exit
	 */
	private static boolean tryConnectToRunningInstance(CommandLineOptions options)
	{
		if(options.portFile == null || !new File(options.portFile).exists())
			return false;

		try
		{
			sendScriptToRunningInstance(options);
			System.exit(0);
		}
		catch(Exception e)
		{
			logServerConnectionError(e);
		}

		return false;
	} //}}}

	//{{{ sendScriptToRunningInstance() method
	/**
	 * Sends a BeanShell script to a running edit server.
	 * @param options The parsed command-line options
	 * @exception Exception if the connection fails
	 */
	private static void sendScriptToRunningInstance(CommandLineOptions options)
		throws Exception
	{
		BufferedReader in = new BufferedReader(new FileReader(options.portFile));
		String check = in.readLine();
		if(!check.equals("b"))
			throw new Exception("Wrong port file format");

		int port = Integer.parseInt(in.readLine());
		int key = Integer.parseInt(in.readLine());
		in.close();

		Socket socket = new Socket(InetAddress.getByName("127.0.0.1"),port);
		DataOutputStream out = new DataOutputStream(
			socket.getOutputStream());
		out.writeInt(key);

		String script = makeServerScript(options.restore,options.args,
			options.scriptFile);

		out.writeUTF(script);

		out.close();
	} //}}}

	//{{{ logServerConnectionError() method
	/**
	 * Logs an error that occurred while connecting to a running jEdit instance.
	 * @param e The exception
	 */
	private static void logServerConnectionError(Exception e)
	{
		Log.log(Log.NOTICE,jEdit.class,"An error occurred"
			+ " while connecting to the jEdit server instance.");
		Log.log(Log.NOTICE,jEdit.class,"This probably means that"
			+ " jEdit crashed and/or exited abnormally");
		Log.log(Log.NOTICE,jEdit.class,"the last time it was run.");
		Log.log(Log.NOTICE,jEdit.class,"If you don't"
			+ " know what this means, don't worry.");
		Log.log(Log.NOTICE,jEdit.class,e);
	} //}}}

