	//{{{ createInitialView() method
	/**
	 * Creates the initial view and completes startup on the AWT thread.
	 * @param buffer The buffer to display
	 * @param splitConfig The split configuration to restore
	 * @param gui Whether to show the initial view
	 */
	private static void createInitialView(Buffer buffer, String splitConfig,
		boolean gui)
	{
		final Buffer _buffer = buffer;
		final String _splitConfig = splitConfig;
		final boolean _gui = gui;

		GUIUtilities.advanceSplashProgress();

		SwingUtilities.invokeLater(new Runnable() {
			public void run()
			{
				completeStartup(_gui,_buffer,_splitConfig);
			}
		});
	} //}}}

	//{{{ completeStartup() method
	/**
	 * Completes startup on the AWT event thread.
	 * @param gui Whether to show the initial view
	 * @param buffer The buffer to display
	 * @param splitConfig The split configuration to restore
	 */
	private static void completeStartup(boolean gui, Buffer buffer,
		String splitConfig)
	{
		EditBus.send(new EditorStarted(null));

		if(gui)
		{
			if(buffer != null)
				newView(null,buffer);
			else
				newView(null,splitConfig);
		}

		VFSManager.start();

		if(server != null)
			server.start();

		GUIUtilities.hideSplashScreen();

		Log.log(Log.MESSAGE,jEdit.class,"Startup "
			+ "complete");

		reportPluginErrors();

		Toolkit.getDefaultToolkit();
	} //}}}

	//{{{ reportPluginErrors() method
	/**
	 * Reports any plugin errors that occurred during startup.
	 */
	private static void reportPluginErrors()
	{
		if(pluginErrors != null)
		{
			String caption = jEdit.getProperty(
				"plugin-error.caption" + (pluginErrors.size() == 1
				? "-1" : ""),new Integer[] {
				new Integer(pluginErrors.size()) });

			new ErrorListDialog(
				jEdit.getFirstView(),
				jEdit.getProperty("plugin-error.title"),
				caption,pluginErrors,true);
			pluginErrors.removeAllElements();
		}
	} //}}}

