completeStartup:

private static void completeStartup(boolean gui, Buffer buffer, String splitConfig) {
    EditBus.send(new EditorStarted(null));

    if(gui) {
        if(buffer != null)
            newView(null, buffer);
        else
            newView(null, splitConfig);
    }

    VFSManager.start();

    if(server != null)
        server.start();

    GUIUtilities.hideSplashScreen();

    Log.log(Log.MESSAGE, jEdit.class, "Startup complete");

    reportPluginErrors();

    Toolkit.getDefaultToolkit();
}

