	//{{{ parseLogLevel() method
	/**
	 * Parses the optional numeric log level from the first argument.
	 * @param args The command line arguments
	 */
	private static int parseLogLevel(String[] args)
	{
		int level = Log.WARNING;
		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				level = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}
		return level;
	} //}}}
