private static StartupOptions parseCommandLine(String[] args)
{
	StartupOptions options = new StartupOptions();
	options.logLevel = Log.WARNING;
	options.restore = true;
	options.gui = true;
	options.userDir = System.getProperty("user.dir");

	if(args.length >= 1)
	{
		String levelStr = args[0];
		if(levelStr.length() == 1 && Character.isDigit(levelStr.charAt(0)))
		{
			options.logLevel = Integer.parseInt(levelStr);
			args[0] = null;
		}
	}

	settingsDirectory = MiscUtilities.constructPath(System.getProperty("user.home"),".jedit");
	options.portFile = "server";
	boolean endOpts = false;

	for(int i = 0; i < args.length; i++)
	{
		String arg = args[i];
		if(arg == null)
			continue;
		if(arg.length() == 0)
		{
			args[i] = null;
			continue;
		}

		if(arg.startsWith("-") && !endOpts)
		{
			endOpts = processOption(arg, options);
			args[i] = null;
		}
	}

	return options;
}

processOption(String arg, StartupOptions options) returns boolean endOpts.
{
	if(arg.equals("--"))
		return true;

	OptionHandler handler = (OptionHandler)optionHandlers.get(arg);
	if(handler != null)
	{
		handler.handle(arg, options);
		return false;
	}

	if(arg.startsWith("-settings="))
	{
		options.settingsDirectory = arg.substring(10);
		return false;
	}
	if(arg.startsWith("-server="))
	{
		options.portFile = arg.substring(8);
		return false;
	}
	if(arg.startsWith("-run="))
	{
		options.scriptFile = arg.substring(5);
		return false;
	}

	System.err.println("Unknown option: " + arg);
	usage();
	System.exit(1);
	return false; // unreachable
}

