createInitialView:
private static void createInitialView(StartupState state)
{
	final Buffer buffer = state.buffer;
	final String splitConfig = state.splitConfig;
	final boolean gui = state.gui;

	GUIUtilities.advanceSplashProgress();

	SwingUtilities.invokeLater(new Runnable()
	{
		public void run()
		{
			EditBus.send(new EditorStarted(null));

			if(gui)
			{
				if(buffer != null)
					newView(null,buffer);
				else
					newView(null,splitConfig);
			}

			VFSManager.start();

			if(server != null)
				server.start();

			GUIUtilities.hideSplashScreen();

			Log.log(Log.MESSAGE,jEdit.class,"Startup complete");

			showPluginErrors();

			Toolkit.getDefaultToolkit();
		}
	});
}

