package org.gjt.sp.jedit;

//{{{ Imports
import com.microstar.xml.*;
import javax.swing.plaf.metal.*;
import javax.swing.plaf.FontUIResource;
import javax.swing.text.DefaultEditorKit;
import javax.swing.text.Element;
import javax.swing.text.JTextComponent;
import javax.swing.text.Keymap;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.io.*;
import java.net.*;
import java.text.MessageFormat;
import java.util.*;
import org.gjt.sp.jedit.browser.VFSBrowser;
import org.gjt.sp.jedit.msg.*;
import org.gjt.sp.jedit.gui.*;
import org.gjt.sp.jedit.io.*;
import org.gjt.sp.jedit.search.SearchAndReplace;
import org.gjt.sp.jedit.syntax.*;
import org.gjt.sp.jedit.textarea.*;
import org.gjt.sp.util.Log;
//}}}

/**
 * The main class of the jEdit text editor.
 * @author Slava Pestov
 * @version $Id$
 */
public class jEdit
{
	//{{{ getVersion() method
	/**
	 * Returns the jEdit version as a human-readable string.
	 */
	public static String getVersion()
	{
		return MiscUtilities.buildToVersion(getBuild());
	} //}}}

	//{{{ getBuild() method
	/**
	 * Returns the internal version. MiscUtilities.compareStrings() can be used
	 * to compare different internal versions.
	 */
	public static String getBuild()
	{
		// (major).(minor).(<99 = preX, 99 = final).(bug fix)
		return "04.00.99.01";
	} //}}}

	//{{{ main() method
	/**
	 * The main method of the jEdit application.
	 * This should never be invoked directly.
	 * @param args The command line arguments
	 */
	public static void main(String[] args)
	{
		String javaVersion = System.getProperty("java.version");
		if(javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version "
				+ javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			System.exit(1);
		}

		int level = parseLogLevel(args);

		settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");
		portFile = "server";

		StartupOptions options = parseCommandLine(args);

		boolean restore = options.restore;
		boolean gui = options.gui;
		boolean noPlugins = options.noPlugins;
		boolean noStartupScripts = options.noStartupScripts;
		String scriptFile = options.scriptFile;
		String userDir = System.getProperty("user.dir");

		portFile = computePortFilePath(portFile);

		Log.init(true,level);

		if(connectToRunningInstance(restore,args,scriptFile))
			return;

		showSplashScreen();

		Writer stream = initSettingsDirectory();
		Log.setLogWriter(stream);

		Log.log(Log.NOTICE,jEdit.class,"jEdit version " + getVersion());
		Log.log(Log.MESSAGE,jEdit.class,"Settings directory is "
			+ settingsDirectory);

		initServer();

		initApplication(noPlugins);

		startPlugins();

		runStartupScripts(noStartupScripts);

		runScript(scriptFile,userDir);

		propertiesChanged();

		GUIUtilities.advanceSplashProgress();

		InitialViewState state = prepareInitialView(restore,gui,args,userDir);

		createViewAndStart(state.buffer,state.splitConfig,state.gui);
	} //}}}

	//{{{ Startup helpers

	/**
	 * Parses the optional first argument that sets the initial log level.
	 * @param args The command line arguments
	 * @return The requested log level, or {@link Log#WARNING} by default
	 */
	private static int parseLogLevel(String[] args)
	{
		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				args[0] = null;
				return Integer.parseInt(levelStr);
			}
		}

		return Log.WARNING;
	}

	/**
	 * Holds command-line options that are local to a single startup.
	 */
	private static class StartupOptions
	{
		boolean restore = true;
		boolean gui = true;
		boolean noPlugins = false;
		boolean noStartupScripts = false;
		String scriptFile = null;
	}

	/**
	 * Handles an exact command-line option.
	 */
	private static interface OptionHandler
	{
		/**
		 * Applies this option's effect.
		 * @param arg The option argument
		 * @param args The full argument array
		 * @param index The index of the current argument
		 * @param options Mutable startup options
		 */
		void handle(String arg, String[] args, int index, StartupOptions options);
	}

	/**
	 * Handles a command-line option identified by a prefix.
	 */
	private static interface PrefixHandler
	{
		/**
		 * Returns true if this handler recognises the argument.
		 * @param arg The option argument
		 */
		boolean matches(String arg);

		/**
		 * Applies this option's effect.
		 * @param arg The option argument
		 * @param args The full argument array
		 * @param index The index of the current argument
		 * @param options Mutable startup options
		 */
		void handle(String arg, String[] args, int index, StartupOptions options);
	}

	private static final Map optionHandlers = new HashMap();
	private static final Vector prefixHandlers = new Vector();

	static
	{
		optionHandlers.put("-usage", new OptionHandler() {
			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				version();
				System.err.println();
				usage();
				System.exit(1);
			}
		});

		optionHandlers.put("-version", new OptionHandler() {
			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				version();
				System.exit(1);
			}
		});

		optionHandlers.put("-nosettings", new OptionHandler() {
			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				settingsDirectory = null;
			}
		});

		optionHandlers.put("-server", new OptionHandler() {
			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				portFile = "server";
			}
		});

		optionHandlers.put("-nogui", new OptionHandler() {
			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				options.gui = false;
			}
		});

		optionHandlers.put("-norestore", new OptionHandler() {
			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				options.restore = false;
			}
		});

		optionHandlers.put("-noplugins", new OptionHandler() {
			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				options.noPlugins = true;
			}
		});

		optionHandlers.put("-nostartupscripts", new OptionHandler() {
			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				options.noStartupScripts = true;
			}
		});

		prefixHandlers.addElement(new PrefixHandler() {
			public boolean matches(String arg)
			{
				return arg.startsWith("-settings=");
			}

			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				settingsDirectory = arg.substring(10);
			}
		});

		prefixHandlers.addElement(new PrefixHandler() {
			public boolean matches(String arg)
			{
				return arg.startsWith("-noserver");
			}

			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				portFile = null;
			}
		});

		prefixHandlers.addElement(new PrefixHandler() {
			public boolean matches(String arg)
			{
				return arg.startsWith("-server=");
			}

			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				portFile = arg.substring(8);
			}
		});

		prefixHandlers.addElement(new PrefixHandler() {
			public boolean matches(String arg)
			{
				return arg.startsWith("-background");
			}

			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				background = true;
			}
		});

		prefixHandlers.addElement(new PrefixHandler() {
			public boolean matches(String arg)
			{
				return arg.startsWith("-run=");
			}

			public void handle(String arg, String[] args, int index, StartupOptions options)
			{
				options.scriptFile = arg.substring(5);
			}
		});
	}

	/**
	 * Parses command-line options, removing recognised arguments from the array.
	 * @param args The command line arguments
	 * @return The populated startup options
	 */
	private static StartupOptions parseCommandLine(String[] args)
	{
		StartupOptions options = new StartupOptions();
		boolean endOpts = false;

		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;
			if(arg.length() == 0)
			{
				args[i] = null;
				continue;
			}
			if(arg.startsWith("-") && !endOpts)
			{
				if(arg.equals("--"))
					endOpts = true;
				else
					handleOption(arg,args,i,options);
				args[i] = null;
			}
		}

		return options;
	}

	/**
	 * Dispatches a single command-line option to its handler.
	 * @param arg The current argument
	 * @param args The full argument array
	 * @param index The index of the current argument
	 * @param options Mutable startup options
	 */
	private static void handleOption(String arg, String[] args, int index, StartupOptions options)
	{
		OptionHandler handler = (OptionHandler)optionHandlers.get(arg);
		if(handler != null)
		{
			handler.handle(arg,args,index,options);
			return;
		}

		for(int i = 0; i < prefixHandlers.size(); i++)
		{
			PrefixHandler ph = (PrefixHandler)prefixHandlers.elementAt(i);
			if(ph.matches(arg))
			{
				ph.handle(arg,args,index,options);
				return;
			}
		}

		System.err.println("Unknown option: " + arg);
		usage();
		System.exit(1);
	}

	/**
	 * Computes the absolute path of the server port file.
	 * @param portFile The port file name
	 * @return The absolute path, or null if no server is used
	 */
	private static String computePortFilePath(String portFile)
	{
		if(settingsDirectory != null && portFile != null)
			return MiscUtilities.constructPath(settingsDirectory,portFile);
		else
			return null;
	}

	/**
	 * Attempts to connect to an already running jEdit instance.
	 * @param restore Whether to restore files on the running instance
	 * @param args Remaining command-line arguments
	 * @param scriptFile Optional script to run on the running instance
	 * @return True if a running instance was contacted
	 */
	private static boolean connectToRunningInstance(boolean restore,
		String[] args, String scriptFile)
	{
		if(portFile == null || !new File(portFile).exists())
			return false;

		int port, key;
		try
		{
			BufferedReader in = new BufferedReader(new FileReader(portFile));
			String check = in.readLine();
			if(!check.equals("b"))
				throw new Exception("Wrong port file format");

			port = Integer.parseInt(in.readLine());
			key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"),port);
			DataOutputStream out = new DataOutputStream(
				socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(restore,args,scriptFile);

			out.writeUTF(script);

			out.close();

			System.exit(0);
		}
		catch(Exception e)
		{
			Log.log(Log.NOTICE,jEdit.class,"An error occurred"
				+ " while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE,jEdit.class,"This probably means that"
				+ " jEdit crashed and/or exited abnormally");
			Log.log(Log.NOTICE,jEdit.class,"the last time it was run.");
			Log.log(Log.NOTICE,jEdit.class,"If you don't"
				+ " know what this means, don't worry.");
			Log.log(Log.NOTICE,jEdit.class,e);
		}

		return false;
	}

	/**
	 * Shows the splash screen unless the user has disabled it.
	 */
	private static void showSplashScreen()
	{
		if(!new File(settingsDirectory,"nosplash").exists())
			GUIUtilities.showSplashScreen();
	}

	/**
	 * Creates the settings directory and opens the activity log.
	 * @return A writer for the activity log, or null if there is no settings directory
	 */
	private static Writer initSettingsDirectory()
	{
		Writer stream;
		if(settingsDirectory != null)
		{
			File _settingsDirectory = new File(settingsDirectory);
			if(!_settingsDirectory.exists())
				_settingsDirectory.mkdirs();
			File _macrosDirectory = new File(settingsDirectory,"macros");
			if(!_macrosDirectory.exists())
				_macrosDirectory.mkdir();

			String logPath = MiscUtilities.constructPath(
				settingsDirectory,"activity.log");

			backupSettingsFile(new File(logPath));

			try
			{
				stream = new BufferedWriter(new FileWriter(logPath));
			}
			catch(Exception e)
			{
				e.printStackTrace();
				stream = null;
			}
		}
		else
		{
			stream = null;
		}
		return stream;
	}

	/**
	 * Starts the edit server, or warns if background mode cannot be used.
	 */
	private static void initServer()
	{
		if(portFile != null)
		{
			server = new EditServer(portFile);
			if(!server.isOK())
				server = null;
		}
		else
		{
			if(background)
			{
				background = false;
				System.err.println("You cannot specify both the"
					+ " -background and -noserver switches");
			}
		}
	}

	/**
	 * Initialises the core application services.
	 * @param noPlugins True if plugins should not be loaded
	 */
	private static void initApplication(boolean noPlugins)
	{
		initMisc();
		initSystemProperties();
		if(jEditHome != null)
			initSiteProperties();
		GUIUtilities.advanceSplashProgress();

		BeanShell.init();

		initUserProperties();
		initPLAF();

		if(OperatingSystem.hasJava14()
			&& System.getProperty("jedit.nojava14") == null)
		{
			initJava14();
		}

		initActions();
		initDockables();

		GUIUtilities.advanceSplashProgress();

		VFSManager.init();

		if(!noPlugins)
			initPlugins();

		if(settingsDirectory != null)
		{
			File history = new File(MiscUtilities.constructPath(
				settingsDirectory,"history"));
			if(history.exists())
				historyModTime = history.lastModified();
			HistoryModel.loadHistory(history);

			File recent = new File(MiscUtilities.constructPath(
				settingsDirectory,"recent.xml"));
			if(recent.exists())
				recentModTime = recent.lastModified();
			BufferHistory.load(recent);
		}

		GUIUtilities.advanceSplashProgress();

		sortBuffers = getBooleanProperty("sortBuffers");
		sortByName = getBooleanProperty("sortByName");

		reloadModes();

		GUIUtilities.advanceSplashProgress();

		SearchAndReplace.load();

		GUIUtilities.advanceSplashProgress();
	}

	/**
	 * Initialises Java 1.4 specific features via reflection.
	 */
	private static void initJava14()
	{
		try
		{
			ClassLoader loader = jEdit.class.getClassLoader();
			Class clazz;
			if(loader != null)
				clazz = loader.loadClass("org.gjt.sp.jedit.Java14");
			else
				clazz = Class.forName("org.gjt.sp.jedit.Java14");
			java.lang.reflect.Method meth = clazz
				.getMethod("init",new Class[0]);
			meth.invoke(null,new Object[0]);
		}
		catch(Exception e)
		{
			Log.log(Log.ERROR,jEdit.class,e);
			System.exit(1);
		}
	}

	/**
	 * Starts all loaded plugins.
	 */
	private static void startPlugins()
	{
		for(int i = 0; i < jars.size(); i++)
		{
			((EditPlugin.JAR)jars.elementAt(i)).getClassLoader()
				.startAllPlugins();
		}
	}

	/**
	 * Loads macros and runs startup scripts.
	 * @param noStartupScripts True if startup scripts should be skipped
	 */
	private static void runStartupScripts(boolean noStartupScripts)
	{
		Macros.loadMacros();

		if(!noStartupScripts && jEditHome != null)
		{
			String path = MiscUtilities.constructPath(jEditHome,"startup");
			File file = new File(path);
			if(file.exists())
				runStartupScripts(file);
		}

		if(!noStartupScripts && settingsDirectory != null)
		{
			String path = MiscUtilities.constructPath(settingsDirectory,"startup");
			File file = new File(path);
			if(!file.exists())
				file.mkdirs();
			else
				runStartupScripts(file);
		}
	}

	/**
	 * Runs the script specified with the -run= parameter.
	 * @param scriptFile The script file name
	 * @param userDir The current working directory
	 */
	private static void runScript(String scriptFile, String userDir)
	{
		if(scriptFile != null)
		{
			scriptFile = MiscUtilities.constructPath(userDir,scriptFile);
			BeanShell.runScript(null,scriptFile,null,false);
		}
	}

	/**
	 * Holds the state needed to create the initial view.
	 */
	private static class InitialViewState
	{
		final Buffer buffer;
		final String splitConfig;
		final boolean gui;

		InitialViewState(Buffer buffer, String splitConfig, boolean gui)
		{
			this.buffer = buffer;
			this.splitConfig = splitConfig;
			this.gui = gui;
		}
	}

	/**
	 * Opens command-line files, restores the previous session and decides
	 * whether to force the initial view.
	 * @param restore Whether session restoration is requested
	 * @param gui Whether the GUI should be shown
	 * @param args Remaining command-line arguments
	 * @param userDir The current working directory
	 * @return The populated initial view state
	 */
	private static InitialViewState prepareInitialView(boolean restore,
		boolean gui, String[] args, String userDir)
	{
		Buffer buffer = openFiles(null,userDir,args);
		if(buffer != null)
			gui = true;

		String splitConfig = null;

		if(restore && settingsDirectory != null
			&& jEdit.getBooleanProperty("restore")
			&& (bufferCount == 0 || jEdit.getBooleanProperty("restore.cli")))
		{
			splitConfig = restoreOpenFiles();
		}

		if(bufferCount == 0 && gui)
			newFile(null);

		return new InitialViewState(buffer,splitConfig,gui);
	}

	/**
	 * Creates the initial view and starts background services.
	 * @param buffer The buffer to display, or null
	 * @param splitConfig The split configuration to restore, or null
	 * @param gui True if a view should be created
	 */
	private static void createViewAndStart(final Buffer buffer,
		final String splitConfig, final boolean gui)
	{
		GUIUtilities.advanceSplashProgress();

		SwingUtilities.invokeLater(new Runnable() {
			public void run()
			{
				EditBus.send(new EditorStarted(null));

				if(gui)
				{
					View view;
					if(buffer != null)
						view = newView(null,buffer);
					else
						view = newView(null,splitConfig);
				}

				VFSManager.start();

				if(server != null)
					server.start();

				GUIUtilities.hideSplashScreen();

				Log.log(Log.MESSAGE,jEdit.class,"Startup "
					+ "complete");

				if(pluginErrors != null)
				{
					String caption = jEdit.getProperty(
						"plugin-error.caption" + (pluginErrors.size() == 1
						? "-1" : ""),new Integer[] {
						new Integer(pluginErrors.size()) });

					new ErrorListDialog(
						jEdit.getFirstView(),
						jEdit.getProperty("plugin-error.title"),
						caption,pluginErrors,true);
					pluginErrors.removeAllElements();
				}

				Toolkit.getDefaultToolkit();
			}
		});
	}

