				return arg.equals("-noplugins");
			}

			public void handle(String arg, StartupOptions options)
			{
				options.noPlugins = true;
			}
		},
		new OptionHandler()
		{
			public boolean matches(String arg)
			{
				return arg.equals("-nostartupscripts");
			}

			public void handle(String arg, StartupOptions options)
			{
				options.noStartupScripts = true;
			}
		},
		new OptionHandler()
		{
			public boolean matches(String arg)
			{
				return arg.startsWith("-run=");
			}

			public void handle(String arg, StartupOptions options)
			{
				options.scriptFile = arg.substring(5);
			}
		}
	};

	/**
	 * Verifies that the JVM is new enough to run jEdit.
	 */
	private static void checkJavaVersion()
	{
		String javaVersion = System.getProperty("java.version");
		if(javaVersion.compareTo("1.3") < 0)
		{
			System.err.println("You are running Java version "
				+ javaVersion + ".");
			System.err.println("jEdit requires Java 1.3 or later.");
			System.exit(1);
		}
	}

	/**
	 * Returns true if the argument is a single-digit log level.
	 * @param arg The argument to test
	 */
	private static boolean isLogLevelArgument(String arg)
	{
		return arg != null && arg.length() == 1
			&& Character.isDigit(arg.charAt(0));
	}

	/**
	 * Parses command-line arguments into a {@link StartupOptions} object.
	 * The args array is modified in place: recognized options are nulled out.
	 * @param args The command line arguments
	 */
	private static StartupOptions parseCommandLine(String[] args)
	{
		StartupOptions options = new StartupOptions();

		if(args.length >= 1 && isLogLevelArgument(args[0]))
		{
			options.logLevel = Integer.parseInt(args[0]);
			args[0] = null;
		}

		settingsDirectory = MiscUtilities.constructPath(
			System.getProperty("user.home"),".jedit");

		boolean endOpts = false;
		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;

			if(arg.length() == 0)
			{
				args[i] = null;
				continue;
			}

			if(!arg.startsWith("-") || endOpts)
				continue;

			if(arg.equals("--"))
			{
				endOpts = true;
				args[i] = null;
				continue;
			}

			if(!handleOption(arg,options))
			{
				System.err.println("Unknown option: "
					+ arg);
				usage();
				System.exit(1);
			}

			args[i] = null;
		}

		return options;
	}

	/**
	 * Dispatches a single command-line option to the appropriate handler.
	 * @param arg The option argument
	 * @param options The current startup options
	 * @return true if the option was recognized, false otherwise
	 */
	private static boolean handleOption(String arg, StartupOptions options)
	{
		for(int i = 0; i < OPTION_HANDLERS.length; i++)
		{
			OptionHandler handler = OPTION_HANDLERS[i];
			if(handler.matches(arg))
			{
				handler.handle(arg,options);
				return true;
			}
		}
		return false;
	}

	/**
	 * Resolves the server port file path against the settings directory.
	 * @param options The current startup options
	 */
	private static void resolvePortFile(StartupOptions options)
	{
		if(settingsDirectory != null && options.portFile != null)
			options.portFile = MiscUtilities.constructPath(settingsDirectory,options.portFile);
		else
			options.portFile = null;
	}
