	//{{{ Startup sequence helpers
	/**
	 * Attempts to connect to an already running jEdit instance.
	 * @param options The current startup options
	 * @param args The remaining command line arguments
	 * @return true if a running instance was found and the script was sent
	 */
	private static boolean tryConnectToRunningInstance(StartupOptions options,
		String[] args)
	{
		if(options.portFile == null || !new File(options.portFile).exists())
			return false;

		try
		{
			BufferedReader in = new BufferedReader(new FileReader(options.portFile));
			String check = in.readLine();
			if(!check.equals("b"))
				throw new Exception("Wrong port file format");

			int port = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(InetAddress.getByName("127.0.0.1"),port);
			DataOutputStream out = new DataOutputStream(
				socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(options.restore,args,options.scriptFile);

			out.writeUTF(script);

			out.close();

			return true;
		}
		catch(Exception e)
		{
			Log.log(Log.NOTICE,jEdit.class,"An error occurred"
				+ " while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE,jEdit.class,"This probably means that"
				+ " jEdit crashed and/or exited abnormally");
			Log.log(Log.NOTICE,jEdit.class,"the last time it was run.");
			Log.log(Log.NOTICE,jEdit.class,"If you don't"
				+ " know what this means, don't worry.");
			Log.log(Log.NOTICE,jEdit.class,e);
			return false;
		}
	}

	/**
	 * Creates the settings directory and opens the activity log.
	 * @return a writer for the log, or null if logging cannot be set up
	 */
	private static Writer initSettingsDirectory()
	{
		if(settingsDirectory == null)
			return null;

		File _settingsDirectory = new File(settingsDirectory);
		if(!_settingsDirectory.exists())
			_settingsDirectory.mkdirs();
		File _macrosDirectory = new File(settingsDirectory,"macros");
		if(!_macrosDirectory.exists())
			_macrosDirectory.mkdir();

		String logPath = MiscUtilities.constructPath(
			settingsDirectory,"activity.log");

		backupSettingsFile(new File(logPath));

		try
		{
			return new BufferedWriter(new FileWriter(logPath));
		}
		catch(Exception e)
		{
			e.printStackTrace();
			return null;
		}
	}

	/**
	 * Starts the edit server, or disables background mode if no server is used.
	 * @param options The current startup options
	 */
	private static void initServer(StartupOptions options)
	{
		if(options.portFile != null)
		{
			server = new EditServer(options.portFile);
			if(!server.isOK())
				server = null;
		}
		else if(background)
		{
			background = false;
			System.err.println("You cannot specify both the"
				+ " -background and -noserver switches");
		}
	}

	/**
	 * Initializes the jEdit core: properties, plugins, modes, etc.
	 * @param options The current startup options
	 */
	private static void startCore(StartupOptions options)
	{
		initMisc();
		initSystemProperties();
		if(jEditHome != null)
			initSiteProperties();
		GUIUtilities.advanceSplashProgress();

		BeanShell.init();

		initUserProperties();
		initPLAF();

		initJava14();

		initActions();
		initDockables();

		GUIUtilities.advanceSplashProgress();

		VFSManager.init();

		if(!options.noPlugins)
			initPlugins();

		if(settingsDirectory != null)
		{
			File history = new File(MiscUtilities.constructPath(
				settingsDirectory,"history"));
			if(history.exists())
				historyModTime = history.lastModified();
			HistoryModel.loadHistory(history);

			File recent = new File(MiscUtilities.constructPath(
				settingsDirectory,"recent.xml"));
			if(recent.exists())
				recentModTime = recent.lastModified();
			BufferHistory.load(recent);
		}

		GUIUtilities.advanceSplashProgress();

		sortBuffers = getBooleanProperty("sortBuffers");
		sortByName = getBooleanProperty("sortByName");

		reloadModes();

		GUIUtilities.advanceSplashProgress();

		SearchAndReplace.load();

		GUIUtilities.advanceSplashProgress();
	}

	/**
	 * Initializes Java 1.4-specific features if available.
	 */
	private static void initJava14()
	{
		if(OperatingSystem.hasJava14()
			&& System.getProperty("jedit.nojava14") == null)
		{
			try
			{
				ClassLoader loader = jEdit.class.getClassLoader();
				Class clazz;
				if(loader != null)
					clazz = loader.loadClass("org.gjt.sp.jedit.Java14");
				else
					clazz = Class.forName("org.gjt.sp.jedit.Java14");
				java.lang.reflect.Method meth = clazz
					.getMethod("init",new Class[0]);
				meth.invoke(null,new Object[0]);
			}
			catch(Exception e)
			{
				Log.log(Log.ERROR,jEdit.class,e);
				System.exit(1);
			}
		}
	}

	/**
	 * Starts all installed plugins.
	 * @param options The current startup options
	 */
	private static void startPlugins(StartupOptions options)
	{
		for(int i = 0; i < jars.size(); i++)
		{
			((EditPlugin.JAR)jars.elementAt(i)).getClassLoader()
				.startAllPlugins();
		}
	}

	/**
	 * Loads macros and runs startup scripts.
	 * @param options The current startup options
	 */
	private static void loadStartupScripts(StartupOptions options)
	{
		Macros.loadMacros();

		if(!options.noStartupScripts && jEditHome != null)
		{
			String path = MiscUtilities.constructPath(jEditHome,"startup");
			File file = new File(path);
			if(file.exists())
				runStartupScripts(file);
		}

		if(!options.noStartupScripts && settingsDirectory != null)
		{
			String path = MiscUtilities.constructPath(settingsDirectory,"startup");
			File file = new File(path);
			if(!file.exists())
				file.mkdirs();
			else
				runStartupScripts(file);
		}
	}

	/**
	 * Runs the BeanShell script specified with the -run= option.
	 * @param options The current startup options
	 */
	private static void runCommandLineScript(StartupOptions options)
	{
		if(options.scriptFile != null)
		{
			String scriptPath = MiscUtilities.constructPath(
				options.userDir,options.scriptFile);
			BeanShell.runScript(null,scriptPath,null,false);
		}
	}

	/**
	 * Opens files from the command line.
	 * @param options The current startup options
	 * @param args The file names to open
	 * @return the last buffer that was opened, or null
	 */
	private static Buffer openInitialFiles(StartupOptions options, String[] args)
	{
		Buffer buffer = openFiles(null,options.userDir,args);
		if(buffer != null)
			options.gui = true;
		return buffer;
	}

	/**
	 * Restores the previous session if requested and appropriate.
	 * @param options The current startup options
	 * @return the split configuration from the session, or null
	 */
	private static String restoreSessionIfNeeded(StartupOptions options)
	{
		if(options.restore && settingsDirectory != null
			&& jEdit.getBooleanProperty("restore")
			&& (bufferCount == 0 || jEdit.getBooleanProperty("restore.cli")))
		{
			return restoreOpenFiles();
		}
		return null;
	}

	/**
	 * Creates the initial view and finishes startup on the AWT thread.
	 * @param buffer The buffer to display, or null
	 * @param splitConfig The split configuration to restore, or null
	 * @param gui Whether to open the initial view
	 */
	private static void createInitialView(Buffer buffer,
		String splitConfig, boolean gui)
	{
		final Buffer _buffer = buffer;
		final String _splitConfig = splitConfig;
		final boolean _gui = gui;

		GUIUtilities.advanceSplashProgress();

		SwingUtilities.invokeLater(new Runnable() {
			public void run()
			{
				EditBus.send(new EditorStarted(null));

				if(_gui)
				{
					if(_buffer != null)
						newView(null,_buffer);
					else
						newView(null,_splitConfig);
				}

				VFSManager.start();

				if(server != null)
					server.start();

				GUIUtilities.hideSplashScreen();

				Log.log(Log.MESSAGE,jEdit.class,"Startup "
					+ "complete");

				reportPluginErrors();

				Toolkit.getDefaultToolkit();
			}
		});
	}

	/**
	 * Reports any plugin errors that occurred during startup.
	 */
	private static void reportPluginErrors()
	{
		if(pluginErrors != null)
		{
			String caption = jEdit.getProperty(
				"plugin-error.caption" + (pluginErrors.size() == 1
				? "-1" : ""),new Integer[] {
				new Integer(pluginErrors.size()) });

			new ErrorListDialog(
				jEdit.getFirstView(),
				jEdit.getProperty("plugin-error.title"),
				caption,pluginErrors,true);
			pluginErrors.removeAllElements();
		}
	}
