private static StartupOptions parseCommandLine(String[] args)
{
    StartupOptions options = new StartupOptions();

    if(args.length >= 1 && isLogLevelArgument(args[0]))
    {
        options.logLevel = Integer.parseInt(args[0]);
        args[0] = null;
    }

    settingsDirectory = MiscUtilities.constructPath(
        System.getProperty("user.home"),".jedit");

    boolean endOpts = false;
    for(int i = 0; i < args.length; i++)
    {
        String arg = args[i];
        if(arg == null)
            continue;

        if(arg.length() == 0)
        {
            args[i] = null;
            continue;
        }

        if(!arg.startsWith("-") || endOpts)
            continue;

        if(arg.equals("--"))
        {
            endOpts = true;
            args[i] = null;
            continue;
        }

        if(!handleOption(arg, options))
        {
            System.err.println("Unknown option: "
                + arg);
            usage();
            System.exit(1);
        }

        args[i] = null;
    }

    return options;
}

