	//{{{ parseCommandLine() method
	/**
	 * Parses the command line arguments into startup options.
	 * @param args The command line arguments
	 * @return The parsed startup options
	 */
	private static StartupOptions parseCommandLine(String[] args)
	{
		StartupOptions options = new StartupOptions();

		if(args.length >= 1)
		{
			String levelStr = args[0];
			if(levelStr.length() == 1 && Character.isDigit(
				levelStr.charAt(0)))
			{
				options.logLevel = Integer.parseInt(levelStr);
				args[0] = null;
			}
		}

		HashMap exactOptions = new HashMap();
		HashMap prefixOptions = new HashMap();
		registerOptionHandlers(exactOptions, prefixOptions);

		for(int i = 0; i < args.length; i++)
		{
			String arg = args[i];
			if(arg == null)
				continue;
			else if(arg.length() == 0)
				args[i] = null;
			else if(arg.startsWith("-") && !options.endOpts)
			{
				if(!processOption(arg, options, exactOptions, prefixOptions))
				{
					System.err.println("Unknown option: "
						+ arg);
					usage();
					System.exit(1);
				}
				args[i] = null;
			}
		}

		return options;
	} //}}}

	//{{{ registerOptionHandlers() method
	/**
	 * Registers the handlers for all supported command-line options.
	 * @param exactOptions Map of exact option strings to handlers
	 * @param prefixOptions Map of option prefixes to handlers
	 */
	private static void registerOptionHandlers(HashMap exactOptions,
		HashMap prefixOptions)
	{
		exactOptions.put("--", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.endOpts = true;
			}
		});
		exactOptions.put("-usage", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				version();
				System.err.println();
				usage();
				System.exit(1);
			}
		});
		exactOptions.put("-version", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				version();
				System.exit(1);
			}
		});
		exactOptions.put("-nosettings", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.settingsDirectory = null;
			}
		});
		exactOptions.put("-server", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.portFile = "server";
			}
		});
		exactOptions.put("-nogui", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.gui = false;
			}
		});
		exactOptions.put("-norestore", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.restore = false;
			}
		});
		exactOptions.put("-noplugins", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.noPlugins = true;
			}
		});
		exactOptions.put("-nostartupscripts", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.noStartupScripts = true;
			}
		});

		prefixOptions.put("-settings=", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.settingsDirectory = arg.substring(10);
			}
		});
		prefixOptions.put("-noserver", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.portFile = null;
			}
		});
		prefixOptions.put("-server=", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.portFile = arg.substring(8);
			}
		});
		prefixOptions.put("-background", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.background = true;
			}
		});
		prefixOptions.put("-run=", new OptionHandler() {
			public void handle(String arg, StartupOptions options)
			{
				options.scriptFile = arg.substring(5);
			}
		});
	} //}}}

	//{{{ processOption() method
	/**
	 * Dispatches a single command-line option to its handler.
	 * @param arg The option argument
	 * @param options The startup options to update
	 * @param exactOptions Map of exact option handlers
	 * @param prefixOptions Map of prefix option handlers
	 * @return True if the option was recognized, false otherwise
	 */
	private static boolean processOption(String arg, StartupOptions options,
		HashMap exactOptions, HashMap prefixOptions)
	{
		OptionHandler handler = (OptionHandler)exactOptions.get(arg);
		if(handler != null)
		{
			handler.handle(arg, options);
			return true;
		}

		Iterator keys = prefixOptions.keySet().iterator();
		while(keys.hasNext())
		{
			String prefix = (String)keys.next();
			if(arg.startsWith(prefix))
			{
				handler = (OptionHandler)prefixOptions.get(prefix);
				handler.handle(arg, options);
				return true;
			}
		}

		return false;
	} //}}}

	//{{{ buildPortFilePath() method
	/**
	 * Builds the full path to the server port file.
	 * @param options The startup options
	 * @return The port file path, or null if no server should be used
	 */
	private static String buildPortFilePath(StartupOptions options)
	{
