	//{{{ connectToRunningInstance() method
	/**
	 * Attempts to connect to an already running jEdit instance and
	 * hand off the command line to it.
	 * @param portFile The path to the server port file
	 * @param options The startup options
	 * @param args The command line arguments
	 */
	private static void connectToRunningInstance(String portFile,
		StartupOptions options, String[] args)
	{
		if(portFile == null || !new File(portFile).exists())
			return;

		try
		{
			BufferedReader in = new BufferedReader(
				new FileReader(portFile));
			String check = in.readLine();
			if(!check.equals("b"))
				throw new Exception("Wrong port file format");

			int port = Integer.parseInt(in.readLine());
			int key = Integer.parseInt(in.readLine());
			in.close();

			Socket socket = new Socket(
				InetAddress.getByName("127.0.0.1"),port);
			DataOutputStream out = new DataOutputStream(
				socket.getOutputStream());
			out.writeInt(key);

			String script = makeServerScript(options.restore,
				args, options.scriptFile);

			out.writeUTF(script);
			out.close();

			System.exit(0);
		}
		catch(Exception e)
		{
			// ok, this one seems to confuse newbies
			// endlessly, so log it as NOTICE, not
			// ERROR
			Log.log(Log.NOTICE,jEdit.class,"An error occurred"
				+ " while connecting to the jEdit server instance.");
			Log.log(Log.NOTICE,jEdit.class,"This probably means that"
				+ " jEdit crashed and/or exited abnormally");
			Log.log(Log.NOTICE,jEdit.class,"the last time it was run.");
			Log.log(Log.NOTICE,jEdit.class,"If you don't"
				+ " know what this means, don't worry.");
			Log.log(Log.NOTICE,jEdit.class,e);
		}
	} //}}}

