	//{{{ runStartupTasks() method
	/**
	 * Performs the final startup tasks on the AWT event thread.
	 * @param buffer The buffer to display, or null
	 * @param splitConfig The split configuration to restore, or null
	 * @param gui True if a view should be shown
	 */
	private static void runStartupTasks(Buffer buffer,
		String splitConfig, boolean gui)
	{
		EditBus.send(new EditorStarted(null));

		if(gui)
		{
			View view;
			if(buffer != null)
				view = newView(null,buffer);
			else
				view = newView(null,splitConfig);
		}

		// Start I/O threads
		VFSManager.start();

		// Start edit server
		if(server != null)
			server.start();

		GUIUtilities.hideSplashScreen();

		Log.log(Log.MESSAGE,jEdit.class,"Startup complete");

		//{{{ Report any plugin errors
		if(pluginErrors != null)
		{
			String caption = jEdit.getProperty(
				"plugin-error.caption" + (pluginErrors.size() == 1
				? "-1" : ""),new Integer[] {
				new Integer(pluginErrors.size()) });

			new ErrorListDialog(
				jEdit.getFirstView(),
				jEdit.getProperty("plugin-error.title"),
				caption,pluginErrors,true);
			pluginErrors.removeAllElements();
		} //}}}

		// in one case not a single AWT class will
		// have been touched (splash screen off +
		// -nogui -nobackground switches on command
		// line)
		Toolkit.getDefaultToolkit();
	} //}}}

