private static StartupOptions parseCommandLine(String[] args)
{
    StartupOptions options = new StartupOptions();

    if(args.length >= 1)
    {
        String levelStr = args[0];
        if(levelStr.length() == 1 && Character.isDigit(levelStr.charAt(0)))
        {
            options.logLevel = Integer.parseInt(levelStr);
            args[0] = null;
        }
    }

    HashMap exactOptions = new HashMap();
    HashMap prefixOptions = new HashMap();
    registerOptionHandlers(exactOptions, prefixOptions);

    for(int i = 0; i < args.length; i++)
    {
        String arg = args[i];
        if(arg == null)
            continue;
        else if(arg.length() == 0)
            args[i] = null;
        else if(arg.startsWith("-") && !options.endOpts)
        {
            if(!processOption(arg, options, exactOptions, prefixOptions))
            {
                System.err.println("Unknown option: " + arg);
                usage();
                System.exit(1);
            }
            args[i] = null;
        }
    }

    return options;
}

