private static boolean processOption(String arg, StartupOptions options,
    HashMap exactOptions, HashMap prefixOptions)
{
    OptionHandler handler = (OptionHandler)exactOptions.get(arg);
    if(handler != null)
    {
        handler.handle(arg,options);
        return true;
    }

    Iterator keys = prefixOptions.keySet().iterator();
    while(keys.hasNext())
    {
        String prefix = (String)keys.next();
        if(arg.startsWith(prefix))
        {
            handler = (OptionHandler)prefixOptions.get(prefix);
            handler.handle(arg,options);
            return true;
        }
    }

    return false;
}

