private static char[] convertPattern(Object patternObj) {
    char[] pattern;
    if (patternObj instanceof String) {
      pattern = ((String) patternObj).toCharArray();
    } else if (patternObj instanceof char[]) {
      pattern = (char[]) patternObj;
    } else if (patternObj instanceof StringBuffer) {
      pattern = new char[((StringBuffer) patternObj).length()];
      ((StringBuffer) patternObj).getChars(0, pattern.length, pattern, 0);
    } else {
      pattern = patternObj.toString().toCharArray();
    }
    return pattern;
  }

private static class ListState {
    Vector options;
    boolean negative;
    char lastChar;
    int index;
  }

private class REParser {
    private final char[] pattern;
    private final int pLength;
    private final RESyntax syntax;
    private final int cflags;
    private final boolean insens;
    private final int subIndex;
    private final int nextSub;

    private RE target;
    private int index;
    private REToken currentToken;
    private Vector branches;
    private int numSubs;

    REParser(Object patternObj, int cflags, RESyntax syntax, int myIndex, int nextSub) throws REException {
      this.pattern = convertPattern(patternObj);
      this.pLength = pattern.length;
      this.cflags = cflags;
      this.syntax = syntax;
      this.insens = ((cflags & REG_ICASE) > 0);
      this.subIndex = myIndex;
      this.nextSub = nextSub;
      this.index = 0;
      this.currentToken = null;
      this.branches = null;
      this.numSubs = 0;
    }

    void parse(RE target) throws REException {
      this.target = target;
      target.firstToken = target.lastToken = null;
      target.minimumLength = 0;

      while (index < pLength) {
        CharUnit unit = new CharUnit();
        index = getCharUnit(pattern, index, unit);
        processUnit(unit);
      }

      target.addToken(currentToken);

      if (branches != null) {
        branches.addElement(new RE(target.firstToken, target.lastToken, numSubs, subIndex, target.minimumLength));
        branches.trimToSize();
        target.minimumLength = 0;
        target.firstToken = target.lastToken = null;
        target.addToken(new RETokenOneOf(subIndex, branches, false));
      } else {
        target.addToken(new RETokenEndSub(subIndex));
      }

      target.numSubs = numSubs;
    }

    // processUnit and helpers...
}

