private void processUnit(CharUnit unit) throws REException {
  if (tryAlternation(unit)) return;
  if (tryInterval(unit)) return;
  if (tryList(unit)) return;
  if (trySubexpression(unit)) return;
  if (tryUnmatchedRightParen(unit)) return;
  if (tryStartOfLine(unit)) return;
  if (tryEndOfLine(unit)) return;
  if (tryAnyChar(unit)) return;
  if (tryStar(unit)) return;
  if (tryPlus(unit)) return;
  if (tryQuestion(unit)) return;
  if (tryBackreference(unit)) return;
  if (tryEscape(unit)) return;
  addOrdinaryChar(unit);
}

