private boolean tryStartOfLine(CharUnit unit) throws REException {
  if (unit.ch != '^' || unit.bk) return false;
  target.addToken(currentToken);
  currentToken = null;
  target.addToken(new RETokenStart(subIndex, ((cflags & REG_MULTILINE) > 0) ? syntax.getLineSeparator() : null));
  return true;
}

private boolean tryEndOfLine(CharUnit unit) throws REException {
  if (unit.ch != '$' || unit.bk) return false;
  target.addToken(currentToken);
  currentToken = null;
  target.addToken(new RETokenEnd(subIndex, ((cflags & REG_MULTILINE) > 0) ? syntax.getLineSeparator() : null));
  return true;
}

private boolean tryAnyChar(CharUnit unit) throws REException {
  if (unit.ch != '.' || unit.bk) return false;
  target.addToken(currentToken);
  currentToken = new RETokenAny(subIndex, syntax.get(RESyntax.RE_DOT_NEWLINE) || ((cflags & REG_DOT_NEWLINE) > 0), syntax.get(RESyntax.RE_DOT_NOT_NULL));
  return true;
}

private void addOrdinaryChar(CharUnit unit) throws REException {
  target.addToken(currentToken);
  currentToken = new RETokenChar(subIndex, unit.ch, insens);
}

private boolean tryAlternation(CharUnit unit) throws REException {
  boolean isAlt = ((unit.ch == '|' && (syntax.get(RESyntax.RE_NO_BK_VBAR) ^ unit.bk))
      || (syntax.get(RESyntax.RE_NEWLINE_ALT) && (unit.ch == '\n') && !unit.bk))
      && !syntax.get(RESyntax.RE_LIMITED_OPS);
  if (!isAlt) return false;
  target.addToken(currentToken);
  RE theBranch = new RE(target.firstToken, target.lastToken, numSubs, subIndex, target.minimumLength);
  target.minimumLength = 0;
  if (branches == null) {
    branches = new Vector();
  }
  branches.addElement(theBranch);
  target.firstToken = target.lastToken = currentToken = null;
  return true;
}

private boolean tryInterval(CharUnit unit) throws REException {
  if (unit.ch != '{' || !syntax.get(RESyntax.RE_INTERVALS) || !(syntax.get(RESyntax.RE_NO_BK_BRACES) ^ unit.bk)) return false;
  IntPair minMax = new IntPair();
  int newIndex = getMinMax(pattern, index, minMax, syntax);
  if (newIndex > index) {
    validateRepeatable(currentToken, minMax, newIndex);
    index = newIndex;
    currentToken = setRepeated(currentToken, minMax.first, minMax.second, index);
  } else {
    target.addToken(currentToken);
    currentToken = new RETokenChar(subIndex, unit.ch, insens);
  }
  return true;
}

private void validateRepeatable(REToken token, IntPair minMax, int newIndex) throws REException {
  if (minMax.first > minMax.second)
    throw new REException(getLocalizedMessage("interval.order"), REException.REG_BADRPT, newIndex);
  if (token == null)
    throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, newIndex);
  if (token instanceof RETokenRepeated)
    throw new REException(getLocalizedMessage("repeat.chained"), REException.REG_BADRPT, newIndex);
  if (token instanceof RETokenWordBoundary || token instanceof RETokenWordBoundary)
    throw new REException(getLocalizedMessage("repeat.assertion"), REException.REG_BADRPT, newIndex);
  if ((token.getMinimumLength() == 0) && (minMax.second == Integer.MAX_VALUE))
    throw new REException(getLocalizedMessage("repeat.empty.token"), REException.REG_BADRPT, newIndex);
}

private boolean tryStar(CharUnit unit) throws REException {
  if (unit.ch != '*' || unit.bk) return false;
  currentToken = makeRepeated(currentToken, 0, Integer.MAX_VALUE, index);
  return true;
}

private boolean tryPlus(CharUnit unit) throws REException {
  if (unit.ch != '+' || syntax.get(RESyntax.RE_LIMITED_OPS) || (syntax.get(RESyntax.RE_BK_PLUS_QM) ^ unit.bk)) return false;
  currentToken = makeRepeated(currentToken, 1, Integer.MAX_VALUE, index);
  return true;
}

private boolean tryQuestion(CharUnit unit) throws REException {
  if (unit.ch != '?' || syntax.get(RESyntax.RE_LIMITED_OPS) || (syntax.get(RESyntax.RE_BK_PLUS_QM) ^ unit.bk)) return false;
  if (currentToken == null)
    throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, index);
  if (currentToken instanceof RETokenRepeated) {
    if (syntax.get(RESyntax.RE_STINGY_OPS) && !((RETokenRepeated) currentToken).isStingy())
      ((RETokenRepeated) currentToken).makeStingy();
    else
      throw new REException(getLocalizedMessage("repeat.chained"), REException.REG_BADRPT, index);
  } else if (currentToken instanceof RETokenWordBoundary || currentToken instanceof RETokenWordBoundary) {
    throw new REException(getLocalizedMessage("repeat.assertion"), REException.REG_BADRPT, index);
  } else {
    currentToken = setRepeated(currentToken, 0, 1, index);
  }
  return true;
}

private REToken makeRepeated(REToken token, int min, int max, int idx) throws REException {
  if (token == null)
    throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, idx);
  if (token instanceof RETokenRepeated)
    throw new REException(getLocalizedMessage("repeat.chained"), REException.REG_BADRPT, idx);
  if (token instanceof RETokenWordBoundary || token instanceof RETokenWordBoundary)
    throw new REException(getLocalizedMessage("repeat.assertion"), REException.REG_BADRPT, idx);
  if (token.getMinimumLength() == 0)
    throw new REException(getLocalizedMessage("repeat.empty.token"), REException.REG_BADRPT, idx);
  return setRepeated(token, min, max, idx);
}

private boolean tryBackreference(CharUnit unit) throws REException {
  if (!unit.bk || !Character.isDigit(unit.ch) || syntax.get(RESyntax.RE_NO_BK_REFS)) return false;
  target.addToken(currentToken);
  currentToken = new RETokenBackRef(subIndex, Character.digit(unit.ch, 10), insens);
  return true;
}

