private boolean tryList(CharUnit unit) throws REException {
  if (unit.ch != '[' || unit.bk) return false;

  ListState state = new ListState();
  state.index = index;
  state.options = new Vector();
  state.lastChar = 0;
  state.negative = false;

  if (state.index == pLength)
    throw new REException(getLocalizedMessage("unmatched.bracket"), REException.REG_EBRACK, state.index);

  if (pattern[state.index] == '^') {
    state.negative = true;
    if (++state.index == pLength)
      throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, state.index);
  }

  char ch = pattern[state.index];
  if (ch == ']') {
    state.lastChar = ch;
    state.index++;
  }

  while ((ch = pattern[state.index++]) != ']') {
    if (ch == '-' && state.lastChar != 0) {
      addListRange(state);
    } else if (ch == '\\' && syntax.get(RESyntax.RE_BACKSLASH_ESCAPE_IN_LISTS)) {
      addListEscapedChar(state);
    } else if (ch == '[' && syntax.get(RESyntax.RE_CHAR_CLASSES) && state.index < pLength && pattern[state.index] == ':') {
      addListPosixClass(state);
    } else {
      addListChar(state, ch);
    }
    if (state.index == pLength)
      throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, state.index);
  }

  if (state.lastChar != 0)
    state.options.addElement(new RETokenChar(subIndex, state.lastChar, insens));

  index = state.index;
  target.addToken(currentToken);
  state.options.trimToSize();
  currentToken = new RETokenOneOf(subIndex, state.options, state.negative);
  return true;
}

private void addListRange(ListState state) throws REException {
  if (state.index == pLength)
    throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, state.index);
  char ch = pattern[state.index];
  if (ch == ']') {
    state.options.addElement(new RETokenChar(subIndex, state.lastChar, insens));
    state.lastChar = '-';
  } else {
    state.options.addElement(new RETokenRange(subIndex, state.lastChar, ch, insens));
    state.lastChar = 0;
    state.index++;
  }
}

private void addListEscapedChar(ListState state) throws REException {
  if (state.index == pLength)
    throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, state.index);

  char esc = pattern[state.index];

  if (state.lastChar != 0)
    state.options.addElement(new RETokenChar(subIndex, state.lastChar, insens));

  if (("dswDSW".indexOf(esc) != -1) && syntax.get(RESyntax.RE_CHAR_CLASS_ESC_IN_LISTS)) {
    int posixId = -1;
    boolean negate = false;
    if (esc == 'D') {
      negate = true;
      posixId = RETokenPOSIX.DIGIT;
    } else if (esc == 'd') {
      posixId = RETokenPOSIX.DIGIT;
    } else if (esc == 'S') {
      negate = true;
      posixId = RETokenPOSIX.SPACE;
    } else if (esc == 's') {
      posixId = RETokenPOSIX.SPACE;
    } else if (esc == 'W') {
      negate = true;
      posixId = RETokenPOSIX.ALNUM;
    } else if (esc == 'w') {
      posixId = RETokenPOSIX.ALNUM;
    }
    if (posixId != -1)
      state.options.addElement(new RETokenPOSIX(subIndex, posixId, insens, negate));
  } else if ("nrt".indexOf(esc) != -1) {
    char asciiEsc = 0;
    if (esc == 'n') asciiEsc = '\n';
    else if (esc == 't') asciiEsc = '\t';
    else if (esc == 'r') asciiEsc = '\r';
    state.lastChar = asciiEsc;
  } else {
    state.lastChar = esc;
  }

  state.index++;
}

private void addListPosixClass(ListState state) throws REException {
  StringBuffer posixSet = new StringBuffer();
  state.index = getPosixSet(pattern, state.index + 1, posixSet);
  int posixId = RETokenPOSIX.intValue(posixSet.toString());
  if (posixId != -1)
    state.options.addElement(new RETokenPOSIX(subIndex, posixId, insens, false));
}

private void addListChar(ListState state, char ch) {
  if (state.lastChar != 0)
    state.options.addElement(new RETokenChar(subIndex, state.lastChar, insens));
  state.lastChar = ch;
}

