private boolean trySubexpression(CharUnit unit) throws REException {
  if (unit.ch != '(' || !(syntax.get(RESyntax.RE_NO_BK_PARENS) ^ unit.bk)) return false;

  boolean pure = false;
  boolean comment = false;
  boolean lookAhead = false;
  boolean negativeLookahead = false;

  if ((index + 1 < pLength) && (pattern[index] == '?')) {
    char marker = pattern[index + 1];
    if (marker == '!') {
      if (syntax.get(RESyntax.RE_LOOKAHEAD)) {
        pure = true;
        negativeLookahead = true;
        lookAhead = true;
        index += 2;
      }
    } else if (marker == '=') {
      if (syntax.get(RESyntax.RE_LOOKAHEAD)) {
        pure = true;
        lookAhead = true;
        index += 2;
      }
    } else if (marker == ':') {
      if (syntax.get(RESyntax.RE_PURE_GROUPING)) {
        pure = true;
        index += 2;
      }
    } else if (marker == '#') {
      if (syntax.get(RESyntax.RE_COMMENTS)) {
        comment = true;
      }
    } else {
      throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, index);
    }
  }

  if (index >= pLength)
    throw new REException(getLocalizedMessage("unmatched.paren"), REException.REG_ESUBREG, index);

  int[] bounds = findSubexpressionEnd();
  int endIndex = bounds[0];
  int nextIndex = bounds[1];

  if (comment) {
    index = nextIndex;
  } else {
    target.addToken(currentToken);
    if (!pure) {
      numSubs++;
    }
    int useIndex = (pure || lookAhead) ? 0 : nextSub + numSubs;
    currentToken = new RE(String.valueOf(pattern, index, endIndex - index).toCharArray(), cflags, syntax, useIndex, nextSub + numSubs);
    numSubs += ((RE) currentToken).getNumSubs();
    if (lookAhead) {
      currentToken = new RETokenLookAhead(currentToken, negativeLookahead);
    }
    index = nextIndex;
  }
  return true;
}

private int[] findSubexpressionEnd() throws REException {
  int endIndex = index;
  int nextIndex = index;
  int nested = 0;
  CharUnit local = new CharUnit();

  while (true) {
    nextIndex = getCharUnit(pattern, endIndex, local);
    if (nextIndex <= 0)
      break;
    if (nested == 0 && local.ch == ')' && (syntax.get(RESyntax.RE_NO_BK_PARENS) ^ local.bk))
      break;
    endIndex = nextIndex;
    if (endIndex >= pLength)
      throw new REException(getLocalizedMessage("subexpr.no.end"), REException.REG_ESUBREG, nextIndex);
    if (local.ch == '(' && (syntax.get(RESyntax.RE_NO_BK_PARENS) ^ local.bk)) {
      nested++;
    } else if (local.ch == ')' && (syntax.get(RESyntax.RE_NO_BK_PARENS) ^ local.bk)) {
      nested--;
    }
  }
  return new int[] { endIndex, nextIndex };
}

