private RETokenOneOf parseList() throws REException {
    Vector options = new Vector();
    boolean negative = false;
    char lastChar = 0;
    if (index == pLength) throw new REException(getLocalizedMessage("unmatched.bracket"), REException.REG_EBRACK, index);

    char ch = pattern[index];
    if (ch == '^') {
        negative = true;
        if (++index == pLength) throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, index);
        ch = pattern[index];
    }

    if (ch == ']') {
        lastChar = ch;
        if (++index == pLength) throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, index);
    }

    while ((ch = pattern[index++]) != ']') {
        if (ch == '-' && lastChar != 0) {
            lastChar = parseListRange(options, lastChar);
        } else if (ch == '\\' && syntax.get(RESyntax.RE_BACKSLASH_ESCAPE_IN_LISTS)) {
            if (index == pLength) throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, index);
            lastChar = parseListEscape(options, lastChar);
        } else if (ch == '[' && syntax.get(RESyntax.RE_CHAR_CLASSES) && index < pLength && pattern[index] == ':') {
            lastChar = parseListPosix(options, lastChar);
        } else {
            if (lastChar != 0) options.addElement(new RETokenChar(subIndex, lastChar, insens));
            lastChar = ch;
        }
        if (index == pLength) throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, index);
    }

    if (lastChar != 0) options.addElement(new RETokenChar(subIndex, lastChar, insens));
    options.trimToSize();
    return new RETokenOneOf(subIndex, options, negative);
}

