private void handleSubexpression() throws REException {
    boolean pure = false;
    boolean comment = false;
    boolean lookAhead = false;
    boolean negativeLookahead = false;

    if ((index + 1 < pLength) && (pattern[index] == '?')) {
        switch (pattern[index + 1]) {
            case '!':
                if (syntax.get(RESyntax.RE_LOOKAHEAD)) {
                    pure = true;
                    negativeLookahead = true;
                    lookAhead = true;
                    index += 2;
                }
                break;
            case '=':
                if (syntax.get(RESyntax.RE_LOOKAHEAD)) {
                    pure = true;
                    lookAhead = true;
                    index += 2;
                }
                break;
            case ':':
                if (syntax.get(RESyntax.RE_PURE_GROUPING)) {
                    pure = true;
                    index += 2;
                }
                break;
            case '#':
                if (syntax.get(RESyntax.RE_COMMENTS)) {
                    comment = true;
                }
                break;
            default:
                throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, index);
        }
    }

    if (index >= pLength) {
        throw new REException(getLocalizedMessage("unmatched.paren"), REException.REG_ESUBREG, index);
    }

    int endIndex = findSubexpressionEnd();

    if (comment) {
        index = endIndex; // skip to after ')'
        return;
    }

    addToken(currentToken);
    if (!pure) {
        numSubs++;
    }

    int useIndex = (pure || lookAhead) ? 0 : nextSub + numSubs;
    currentToken = new RE(String.valueOf(pattern, index, endIndex - index).toCharArray(), cflags, syntax, useIndex, nextSub + numSubs);
    numSubs += ((RE) currentToken).getNumSubs();

    if (lookAhead) {
