private int parseIntervalBody(char[] input, int index, CharUnit unit, int min, IntPair minMax, RESyntax syntax, boolean mustMatch, int startIndex) throws REException {
    int max;
    boolean closed = (unit.ch == '}') && (syntax.get(RESyntax.RE_NO_BK_BRACES) ^ unit.bk);
    if (closed) {
        max = min;
    } else if (index == input.length) {
        return handleUnclosedInterval(mustMatch, index, startIndex);
    } else if ((unit.ch == ',') && !unit.bk) {
        StringBuffer buf = new StringBuffer();
        while (((index = getCharUnit(input, index, unit)) != input.length) && Character.isDigit(unit.ch)) {
            buf.append(unit.ch);
        }
        if (!((unit.ch == '}') && (syntax.get(RESyntax.RE_NO_BK_BRACES) ^ unit.bk))) {
            return handleInvalidInterval(mustMatch, index, startIndex);
        }
        max = (buf.length() == 0) ? Integer.MAX_VALUE : Integer.parseInt(buf.toString());
    } else {
        return handleInvalidInterval(mustMatch, index, startIndex);
    }

    minMax.first = min;
    minMax.second = max;
    return index;
}

