  index = readIntervalDigits(input, index, unit, buf);

  if (buf.length() == 0) {
    return handleInvalidInterval(mustMatch, index, startIndex);
  }

  int min = Integer.parseInt(buf.toString());
  return parseIntervalBody(input, index, unit, min, minMax, syntax, mustMatch, startIndex);
}

private int readIntervalDigits(char[] input, int index, CharUnit unit, StringBuffer buf) throws REException {
