          lastChar = ch;
        }
        if (index == pLength)
          throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, index);
      }

      if (lastChar != 0)
        options.addElement(new RETokenChar(RE.this.subIndex, lastChar, insens));

      options.trimToSize();
      return new RETokenOneOf(RE.this.subIndex, options, negative);
