    // Parses a character range inside a character class.
    private char parseListRange(Vector options, char lastChar) throws REException {
      if (index == pLength)
        throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, index);
      char ch = pattern[index];
      if (ch == ']') {
        options.addElement(new RETokenChar(RE.this.subIndex, lastChar, insens));
