      boolean negate = false;
      char asciiEsc = 0;

      if (("dswDSW".indexOf(esc) != -1) && syntax.get(RESyntax.RE_CHAR_CLASS_ESC_IN_LISTS)) {
        if (esc == 'D' || esc == 'S' || esc == 'W') {
