          posixID = RETokenPOSIX.DIGIT;
        } else if (esc == 's' || esc == 'S') {
          posixID = RETokenPOSIX.SPACE;
        } else if (esc == 'w' || esc == 'W') {
          posixID = RETokenPOSIX.ALNUM;
        }
      } else if ("nrt".indexOf(esc) != -1) {
        switch (esc) {
          case 'n':
            asciiEsc = '\n';
            break;
          case 't':
            asciiEsc = '\t';
            break;
          case 'r':
            asciiEsc = '\r';
            break;
        }
      }

      if (lastChar != 0) {
        options.addElement(new RETokenChar(RE.this.subIndex, lastChar, insens));
      }

      if (posixID != -1) {
        options.addElement(new RETokenPOSIX(RE.this.subIndex, posixID, insens, negate));
        return lastChar;
      } else if (asciiEsc != 0) {
