    // Parses a POSIX character class escape inside a character class.
    private char parseListPosix(Vector options, char lastChar) throws REException {
      StringBuffer posixSet = new StringBuffer();
      index = getPosixSet(pattern, index + 1, posixSet);
      int posixId = RETokenPOSIX.intValue(posixSet.toString());
      if (posixId != -1) {
        options.addElement(new RETokenPOSIX(RE.this.subIndex, posixId, insens, false));
