      if (index >= pLength) {
        throw new REException(getLocalizedMessage("unmatched.paren"), REException.REG_ESUBREG, index);
      }

      IntPair bounds = findSubexpressionEnd();
      int endIndex = bounds.first;
      int nextIndex = bounds.second;

      if (comment) {
        index = nextIndex;
        return;
      }

      addToken(currentToken);
      if (!pure) {
        numSubs++;
      }

      int useIndex = (pure || lookAhead) ? 0 : nextSub + numSubs;
      currentToken = new RE(String.valueOf(pattern, index, endIndex - index).toCharArray(), cflags, syntax, useIndex, nextSub + numSubs);
      numSubs += ((RE) currentToken).getNumSubs();

      if (lookAhead) {
        currentToken = new RETokenLookAhead(currentToken, negativeLookahead);
      }

      index = nextIndex;
