  private int getMinMax(char[] input, int index, IntPair minMax, RESyntax syntax) throws REException {
    boolean mustMatch = !syntax.get(RESyntax.RE_NO_BK_BRACES);
    int startIndex = index;
    if (index == input.length) {
      return handleEmptyInterval(mustMatch, index, startIndex);
    }

    CharUnit unit = new CharUnit();
    StringBuffer buf = new StringBuffer();
    index = readIntervalDigits(input, index, unit, buf);

    if (buf.length() == 0) {
      return handleInvalidInterval(mustMatch, index, startIndex);
    }

    int min = Integer.parseInt(buf.toString());
    return parseIntervalBody(input, index, unit, min, minMax, syntax, mustMatch, startIndex);
  }

  // Reads a sequence of decimal digits from an interval expression.
  private int readIntervalDigits(char[] input, int index, CharUnit unit, StringBuffer buf) throws REException {
    do {
      index = getCharUnit(input, index, unit);
      if (Character.isDigit(unit.ch)) {
        buf.append(unit.ch);
      }
    } while ((index != input.length) && Character.isDigit(unit.ch));
    return index;
  }

  // Parses the remainder of an {x,y} interval after the minimum value.
  private int parseIntervalBody(char[] input, int index, CharUnit unit, int min, IntPair minMax, RESyntax syntax, boolean mustMatch, int startIndex) throws REException {
    int max;
    if ((unit.ch == '}') && (syntax.get(RESyntax.RE_NO_BK_BRACES) ^ unit.bk)) {
      max = min;
    } else if (index == input.length) {
      return handleUnclosedInterval(mustMatch, index, startIndex);
    } else if ((unit.ch == ',') && !unit.bk) {
      StringBuffer buf = new StringBuffer();
      while (((index = getCharUnit(input, index, unit)) != input.length) && Character.isDigit(unit.ch)) {
        buf.append(unit.ch);
      }
      if (!((unit.ch == '}') && (syntax.get(RESyntax.RE_NO_BK_BRACES) ^ unit.bk))) {
        return handleInvalidInterval(mustMatch, index, startIndex);
      }
      max = (buf.length() == 0) ? Integer.MAX_VALUE : Integer.parseInt(buf.toString());
    } else {
      return handleInvalidInterval(mustMatch, index, startIndex);
    }

    minMax.first = min;
    minMax.second = max;
    return index;
  }

  private int handleEmptyInterval(boolean mustMatch, int index, int startIndex) throws REException {
    if (mustMatch) {
      throw new REException(getLocalizedMessage("unmatched.brace"), REException.REG_EBRACE, index);
    }
    return startIndex;
  }

  private int handleInvalidInterval(boolean mustMatch, int index, int startIndex) throws REException {
    if (mustMatch) {
      throw new REException(getLocalizedMessage("interval.error"), REException.REG_EBRACE, index);
    }
    return startIndex;
  }

  private int handleUnclosedInterval(boolean mustMatch, int index, int startIndex) throws REException {
    if (mustMatch) {
      throw new REException(getLocalizedMessage("interval.no.end"), REException.REG_EBRACE, index);
    }
    return startIndex;
  }

