      ctx.index = getCharUnit(ctx.pattern, ctx.index, ctx.unit);

      if (tryParseAlternation(ctx)) continue;
      if (tryParseInterval(ctx)) continue;
      if (tryParseList(ctx)) continue;
      if (tryParseSubexpression(ctx)) continue;
      checkUnmatchedRightParen(ctx);
      if (tryParseAnchorOrDot(ctx)) continue;
      if (tryParseRepeat(ctx)) continue;
      if (tryParseBackreference(ctx)) continue;
      if (tryParseEscape(ctx)) continue;
      parseLiteral(ctx);
    }
