    }
    return false;
  }

  // Handles interval expressions such as {x}, {x,} and {x,y}.
  private boolean tryParseInterval(ParseContext ctx) throws REException {
    if ((ctx.unit.ch == '{') && ctx.syntax.get(RESyntax.RE_INTERVALS)
