        ctx.currentToken = setRepeated(ctx.currentToken, ctx.minMax.first, ctx.minMax.second, ctx.index);
      } else {
        addToken(ctx.currentToken);
        ctx.currentToken = new RETokenChar(subIndex, ctx.unit.ch, ctx.insens);
      }
      return true;
    }
    return false;
  }

  // Ensures the token being repeated is suitable for repetition.
  private static void validateRepeatable(REToken token, int index) throws REException {
    if (token == null) {
      throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, index);
    }
    if (token instanceof RETokenRepeated) {
      throw new REException(getLocalizedMessage("repeat.chained"), REException.REG_BADRPT, index);
    }
