private int findSubexpressionEnd(ParseContext ctx) throws REException {
  int endIndex = ctx.index;
  int nextIndex = ctx.index;
  int nested = 0;
  CharUnit unit = new CharUnit();
  while ( ((nextIndex = getCharUnit(ctx.pattern,endIndex,unit)) > 0)
         && !(nested == 0 && (unit.ch == ')') && (ctx.syntax.get(RESyntax.RE_NO_BK_PARENS) ^ unit.bk)) ) {
    if ((endIndex = nextIndex) >= ctx.pLength)
      throw new REException(getLocalizedMessage("subexpr.no.end"),REException.REG_ESUBREG,nextIndex);
    else if (unit.ch == '(' && (ctx.syntax.get(RESyntax.RE_NO_BK_PARENS) ^ unit.bk))
      nested++;
    else if (unit.ch == ')' && (ctx.syntax.get(RESyntax.RE_NO_BK_PARENS) ^ unit.bk))
      nested--;
  }
  ctx.index = nextIndex;
  return endIndex;
}

