private SubexpressionFlags parseSubexpressionFlags(ParseContext ctx) throws REException {
  SubexpressionFlags flags = new SubexpressionFlags();
  if ((ctx.index+1 < ctx.pLength) && (ctx.pattern[ctx.index] == '?')) {
    char type = ctx.pattern[ctx.index+1];
    if (type == '!' && ctx.syntax.get(RE_LOOKAHEAD)) {
      flags.pure = true; flags.negativeLookahead = true; flags.lookAhead = true; ctx.index += 2;
    } else if (type == '=' && ctx.syntax.get(RE_LOOKAHEAD)) {
      flags.pure = true; flags.lookAhead = true; ctx.index += 2;
    } else if (type == ':' && ctx.syntax.get(RE_PURE_GROUPING)) {
      flags.pure = true; ctx.index += 2;
    } else if (type == '#' && ctx.syntax.get(RE_COMMENTS)) {
      flags.comment = true;
    } else {
      throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, ctx.index);
    }
  }
  return flags;
}

