private boolean tryParseStringAnchor(ParseContext ctx) throws REException {
  if (ctx.unit.ch == 'A' && ctx.syntax.get(RESyntax.RE_STRING_ANCHORS)) {
    addToken(ctx.currentToken);
    ctx.currentToken = new RETokenStart(subIndex, null);
    return true;
  }
  if (ctx.unit.ch == 'b' && ctx.syntax.get(RESyntax.RE_STRING_ANCHORS)) {
    addToken(ctx.currentToken);
    ctx.currentToken = new RETokenWordBoundary(subIndex, RETokenWordBoundary.BEGIN | RETokenWordBoundary.END, false);
    return true;
  }
  if (ctx.unit.ch == '<') {
    addToken(ctx.currentToken);
    ctx.currentToken = new RETokenWordBoundary(subIndex, RETokenWordBoundary.BEGIN, false);
    return true;
  }
  if (ctx.unit.ch == '>') {
    addToken(ctx.currentToken);
    ctx.currentToken = new RETokenWordBoundary(subIndex, RETokenWordBoundary.END, false);
    return true;
  }
  if (ctx.unit.ch == 'B' && ctx.syntax.get(RESyntax.RE_STRING_ANCHORS)) {
    addToken(ctx.currentToken);
    ctx.currentToken = new RETokenWordBoundary(subIndex, RETokenWordBoundary.BEGIN | RETokenWordBoundary.END, true);
    return true;
  }
  if (ctx.unit.ch == 'Z' && ctx.syntax.get(RESyntax.RE_STRING_ANCHORS)) {
    addToken(ctx.currentToken);
    ctx.currentToken = new RETokenEnd(subIndex, null);
    return true;
  }
  return false;
}

