  private boolean parseListNegation(ParseContext ctx) throws REException {
    if (ctx.index == ctx.pLength) {
      throw new REException(getLocalizedMessage("unmatched.bracket"), REException.REG_EBRACK, ctx.index);
    }
    char ch = ctx.pattern[ctx.index];
    if (ch == '^') {
      ctx.index++;
      if (ctx.index == ctx.pLength) {
        throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
      }
      return true;
    }
    return false;
  }

  private char parseListLeadingBracket(ParseContext ctx) throws REException {
    if (ctx.index == ctx.pLength) {
      throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
    }
    char ch = ctx.pattern[ctx.index];
    if (ch == ']') {
      ctx.index++;
      return ch;
    }
    return 0;
