  private char parseListBody(ParseContext ctx, Vector options, char lastChar) throws REException {
    while (true) {
      char ch = ctx.pattern[ctx.index++];
      if (ch == ']') {
        break;
      }
      lastChar = parseListCharacter(ctx, options, lastChar, ch);
      if (ctx.index == ctx.pLength) {
        throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
      }
    }
    return lastChar;
  }

  private char parseListCharacter(ParseContext ctx, Vector options, char lastChar, char ch) throws REException {
    if ((ch == '-') && (lastChar != 0)) {
      return parseListRange(ctx, options, lastChar);
    } else if ((ch == '\\') && ctx.syntax.get(RESyntax.RE_BACKSLASH_ESCAPE_IN_LISTS)) {
      return parseListEscape(ctx, options, lastChar);
    } else if ((ch == '[') && ctx.syntax.get(RESyntax.RE_CHAR_CLASSES)
               && (ctx.index < ctx.pLength) && (ctx.pattern[ctx.index] == ':')) {
      return parseListPosixClass(ctx, options, lastChar);
    } else {
      return parseListLiteralChar(options, lastChar, ch);
    }
  }

  private char parseListRange(ParseContext ctx, Vector options, char lastChar) throws REException {
    if (ctx.index == ctx.pLength) {
      throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
    }
    char ch = ctx.pattern[ctx.index];
    if (ch == ']') {
      options.addElement(new RETokenChar(subIndex, lastChar, ctx.insens));
      return '-';
    } else {
      options.addElement(new RETokenRange(subIndex, lastChar, ch, ctx.insens));
      ctx.index++;
      return 0;
    }
  }

  private char parseListEscape(ParseContext ctx, Vector options, char lastChar) throws REException {
    if (ctx.index == ctx.pLength) {
      throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
    }
    char esc = ctx.pattern[ctx.index];
    int posixID = -1;
    boolean negate = false;
    char asciiEsc = 0;

    if (("dswDSW".indexOf(esc) != -1) && ctx.syntax.get(RESyntax.RE_CHAR_CLASS_ESC_IN_LISTS)) {
      if (esc == 'd' || esc == 'D') {
        posixID = RETokenPOSIX.DIGIT;
        negate = (esc == 'D');
      } else if (esc == 's' || esc == 'S') {
        posixID = RETokenPOSIX.SPACE;
        negate = (esc == 'S');
      } else if (esc == 'w' || esc == 'W') {
        posixID = RETokenPOSIX.ALNUM;
        negate = (esc == 'W');
      }
    } else if ("nrt".indexOf(esc) != -1) {
      if (esc == 'n') {
        asciiEsc = '\n';
      } else if (esc == 't') {
        asciiEsc = '\t';
      } else if (esc == 'r') {
        asciiEsc = '\r';
      }
    }

    if (lastChar != 0) {
      options.addElement(new RETokenChar(subIndex, lastChar, ctx.insens));
    }

    if (posixID != -1) {
      options.addElement(new RETokenPOSIX(subIndex, posixID, ctx.insens, negate));
      ctx.index++;
      return 0;
    } else if (asciiEsc != 0) {
      ctx.index++;
      return asciiEsc;
    } else {
      ctx.index++;
      return esc;
    }
  }

