  private boolean tryParseSubexpression(ParseContext ctx) throws REException {
    if ((ctx.unit.ch == '(') && (ctx.syntax.get(RESyntax.RE_NO_BK_PARENS) ^ ctx.unit.bk)) {
      parseSubexpression(ctx);
