  private void parseSubexpression(ParseContext ctx) throws REException {
    SubexpressionFlags flags = parseSubexpressionFlags(ctx);

    if (ctx.index >= ctx.pLength) {
      throw new REException(getLocalizedMessage("unmatched.paren"), REException.REG_ESUBREG, ctx.index);
    }

    int startIndex = ctx.index;
    int endIndex = findSubexpressionEnd(ctx);

    if (flags.comment) {
      return;
    }

    addToken(ctx.currentToken);
    if (!flags.pure) {
      numSubs++;
    }

    int useIndex = (flags.pure || flags.lookAhead) ? 0 : ctx.nextSub + numSubs;
    ctx.currentToken = new RE(String.valueOf(ctx.pattern, startIndex, endIndex - startIndex).toCharArray(),
                            ctx.cflags, ctx.syntax, useIndex, ctx.nextSub + numSubs);
    numSubs += ((RE) ctx.currentToken).getNumSubs();

    if (flags.lookAhead) {
      ctx.currentToken = new RETokenLookAhead(ctx.currentToken, flags.negativeLookahead);
    }
  }

  private SubexpressionFlags parseSubexpressionFlags(ParseContext ctx) throws REException {
    SubexpressionFlags flags = new SubexpressionFlags();
    if ((ctx.index + 1 < ctx.pLength) && (ctx.pattern[ctx.index] == '?')) {
      char type = ctx.pattern[ctx.index + 1];
      if (type == '!' && ctx.syntax.get(RESyntax.RE_LOOKAHEAD)) {
        flags.pure = true;
        flags.negativeLookahead = true;
        flags.lookAhead = true;
        ctx.index += 2;
      } else if (type == '=' && ctx.syntax.get(RESyntax.RE_LOOKAHEAD)) {
        flags.pure = true;
        flags.lookAhead = true;
        ctx.index += 2;
      } else if (type == ':' && ctx.syntax.get(RESyntax.RE_PURE_GROUPING)) {
        flags.pure = true;
        ctx.index += 2;
      } else if (type == '#') {
        if (ctx.syntax.get(RESyntax.RE_COMMENTS)) {
          flags.comment = true;
        }
      } else {
        throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, ctx.index);
      }
    }
    return flags;
  }

  private int findSubexpressionEnd(ParseContext ctx) throws REException {
    int endIndex = ctx.index;
    int nextIndex = ctx.index;
    int nested = 0;
    CharUnit unit = new CharUnit();

    while (((nextIndex = getCharUnit(ctx.pattern, endIndex, unit)) > 0)
           && !(nested == 0 && (unit.ch == ')') && (ctx.syntax.get(RESyntax.RE_NO_BK_PARENS) ^ unit.bk))) {
      if ((endIndex = nextIndex) >= ctx.pLength) {
        throw new REException(getLocalizedMessage("subexpr.no.end"), REException.REG_ESUBREG, nextIndex);
      } else if (unit.ch == '(' && (ctx.syntax.get(RESyntax.RE_NO_BK_PARENS) ^ unit.bk)) {
        nested++;
      } else if (unit.ch == ')' && (ctx.syntax.get(RESyntax.RE_NO_BK_PARENS) ^ unit.bk)) {
        nested--;
      }
    }

    ctx.index = nextIndex;
    return endIndex;
  }

