      if (ctx.currentToken.getMinimumLength() == 0) {
        throw new REException(getLocalizedMessage("repeat.empty.token"), REException.REG_BADRPT, ctx.index);
      }
      ctx.currentToken = setRepeated(ctx.currentToken, 1, Integer.MAX_VALUE, ctx.index);
