  private int getMinMax(char[] input, int index, IntPair minMax, RESyntax syntax) throws REException {
    boolean mustMatch = !syntax.get(RESyntax.RE_NO_BK_BRACES);
    int startIndex = index;

    if (index == input.length) {
      return handleMissingBrace(mustMatch, index, startIndex);
    }

    CharUnit unit = new CharUnit();
    StringBuffer buf = new StringBuffer();
    index = readDigits(input, index, unit, buf);

    if (buf.length() == 0) {
      return handleIntervalError(mustMatch, index, startIndex);
    }

    int min = Integer.parseInt(buf.toString());
    IntervalResult result = parseIntervalMax(input, index, unit, syntax, mustMatch, startIndex, min);
    if (result == null) {
      return startIndex;
    }

    minMax.first = min;
    minMax.second = result.max;
    return result.index;
  }

  private int handleMissingBrace(boolean mustMatch, int index, int startIndex) throws REException {
    if (mustMatch) {
      throw new REException(getLocalizedMessage("unmatched.brace"), REException.REG_EBRACE, index);
    }
    return startIndex;
  }

  private int handleIntervalError(boolean mustMatch, int index, int startIndex) throws REException {
    if (mustMatch) {
      throw new REException(getLocalizedMessage("interval.error"), REException.REG_EBRACE, index);
    }
    return startIndex;
  }

  private int readDigits(char[] input, int index, CharUnit unit, StringBuffer buf) throws REException {
    do {
      index = getCharUnit(input, index, unit);
      if (Character.isDigit(unit.ch)) {
        buf.append(unit.ch);
      }
    } while ((index != input.length) && Character.isDigit(unit.ch));
    return index;
  }

  private IntervalResult parseIntervalMax(char[] input, int index, CharUnit unit, RESyntax syntax,
                                          boolean mustMatch, int startIndex, int min) throws REException {
    if ((unit.ch == '}') && (syntax.get(RESyntax.RE_NO_BK_BRACES) ^ unit.bk)) {
      return new IntervalResult(min, index);
    }

    if (index == input.length) {
      if (mustMatch) {
        throw new REException(getLocalizedMessage("interval.no.end"), REException.REG_EBRACE, index);
      }
      return null;
    }

    if ((unit.ch == ',') && !unit.bk) {
      StringBuffer buf = new StringBuffer();
      while (((index = getCharUnit(input, index, unit)) != input.length) && Character.isDigit(unit.ch)) {
        buf.append(unit.ch);
      }
      if (!((unit.ch == '}') && (syntax.get(RESyntax.RE_NO_BK_BRACES) ^ unit.bk))) {
        if (mustMatch) {
          throw new REException(getLocalizedMessage("interval.error"), REException.REG_EBRACE, index);
        }
        return null;
      }
      int max = (buf.length() == 0) ? Integer.MAX_VALUE : Integer.parseInt(buf.toString());
      return new IntervalResult(max, index);
    }

    if (mustMatch) {
      throw new REException(getLocalizedMessage("interval.error"), REException.REG_EBRACE, index);
    }
    return null;
  }

