private boolean parseListNegation(ParserContext ctx) throws REException {
    if (ctx.index == ctx.pLength) throw new REException(...);
    if (ctx.pattern[ctx.index] != '^') return false;
    if (++ctx.index == ctx.pLength) throw new REException(...);
    return true;
