private SubexpressionModifier parseSubexpressionModifier(ParserContext ctx) {
    SubexpressionModifier mod = new SubexpressionModifier();
    if (ctx.index + 1 >= ctx.pLength) return mod;
    if (ctx.pattern[ctx.index] != '?') return mod;
    char type = ctx.pattern[ctx.index + 1];
