        mod.pure = true; mod.lookAhead = true; mod.negativeLookAhead = true; ctx.index += 2;
    } else if (type == '=' && ctx.syntax.get(RE_LOOKAHEAD)) {
        mod.pure = true; mod.lookAhead = true; ctx.index += 2;
    } else if (type == ':' && ctx.syntax.get(RE_PURE_GROUPING)) {
