private void handleList(ParserContext ctx) throws REException {
    addToken(ctx.currentToken);
    Vector options = new Vector();
    boolean negative = parseListNegation(ctx);
    char lastChar = parseListLeadingBracket(ctx);
    lastChar = parseListBody(ctx, options, lastChar);
    if (lastChar != 0) {
        options.addElement(new RETokenChar(subIndex, lastChar, ctx.insens));
    }
    options.trimToSize();
    ctx.currentToken = new RETokenOneOf(subIndex, options, negative);
}

parseListNegation:

private boolean parseListNegation(ParserContext ctx) throws REException {
    if (ctx.index == ctx.pLength) {
        throw new REException(getLocalizedMessage("unmatched.bracket"), REException.REG_EBRACK, ctx.index);
    }
    if (ctx.pattern[ctx.index] != '^') {
        return false;
    }
    if (++ctx.index == ctx.pLength) {
        throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
    }
    return true;
}

parseListLeadingBracket:

private char parseListLeadingBracket(ParserContext ctx) throws REException {
    if (ctx.pattern[ctx.index] != ']') {
        return 0;
    }
    if (++ctx.index == ctx.pLength) {
        throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
    }
    return ']';
}

parseListBody:

private char parseListBody(ParserContext ctx, Vector options, char lastChar) throws REException {
    char ch;
    while ((ch = ctx.pattern[ctx.index++]) != ']') {
        lastChar = parseListCharacter(ctx, options, lastChar, ch);
        if (ctx.index == ctx.pLength) {
            throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
        }
    }
    return lastChar;
}

parseListCharacter:

private char parseListCharacter(ParserContext ctx, Vector options, char lastChar, char ch) throws REException {
    if (isListRange(ch, lastChar)) {
        return parseListRange(ctx, options, lastChar);
    }
    if (isListBackslashEscape(ctx, ch)) {
        return parseListBackslashEscape(ctx, options, lastChar);
    }
    if (isListPosixClass(ctx, ch)) {
        parseListPosixClass(ctx, options);
        return lastChar;
    }
    return parseListPlainChar(ctx, options, lastChar, ch);
}

isListRange: ch == '-' && lastChar != 0.

isListBackslashEscape: ch == '\\' && ctx.syntax.get(RE_BACKSLASH_ESCAPE_IN_LISTS).

isListPosixClass: ch == '[' && ctx.syntax.get(RE_CHAR_CLASSES) && ctx.index < ctx.pLength && ctx.pattern[ctx.index] == ':'.

