private char parseListRange(ParserContext ctx, Vector options, char lastChar) throws REException {
    if (ctx.index == ctx.pLength) {
        throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
    }
    char ch = ctx.pattern[ctx.index];
    if (ch == ']') {
        options.addElement(new RETokenChar(subIndex, lastChar, ctx.insens));
        return '-';
    }
    options.addElement(new RETokenRange(subIndex, lastChar, ch, ctx.insens));
    ctx.index++;
    return 0;
}

