private char parseListBackslashEscape(ParserContext ctx, Vector options, char lastChar) throws REException {
    if (ctx.index == ctx.pLength) {
        throw new REException(getLocalizedMessage("class.no.end"), REException.REG_EBRACK, ctx.index);
    }
    if (lastChar != 0) {
        options.addElement(new RETokenChar(subIndex, lastChar, ctx.insens));
    }
    char next = ctx.pattern[ctx.index];
    if (isCharClassEscape(ctx, next)) {
        options.addElement(createCharClassToken(ctx, next));
        ctx.index++;
        return 0;
    }
    if (isAsciiEscape(next)) {
        ctx.index++;
        return asciiValue(next);
    }
