private IntPair findSubexpressionEnd(ParserContext ctx) throws REException {
    IntPair bounds = new IntPair();
    bounds.first = ctx.index;
    bounds.second = ctx.index;
    int nested = 0;
    while (true) {
        bounds.second = getCharUnit(ctx.pattern, bounds.first, ctx.unit);
        if (isSubexpressionEnd(ctx, nested)) {
            return bounds;
        }
        bounds.first = bounds.second;
        if (bounds.first >= ctx.pLength) {
            throw new REException(getLocalizedMessage("subexpr.no.end"), REException.REG_ESUBREG, bounds.second);
        }
        if (isOpenParen(ctx)) {
            nested++;
        } else if (isCloseParen(ctx)) {
            nested--;
        }
    }
}

