private SubexpressionModifier parseSubexpressionModifier(ParserContext ctx) throws REException {
    SubexpressionModifier mod = new SubexpressionModifier();
    if (ctx.index + 1 >= ctx.pLength) {
        return mod;
    }
    if (ctx.pattern[ctx.index] != '?') {
        return mod;
    }
    char type = ctx.pattern[ctx.index + 1];
    if (type == '!' && ctx.syntax.get(RESyntax.RE_LOOKAHEAD)) {
        mod.pure = true;
        mod.lookAhead = true;
        mod.negativeLookAhead = true;
        ctx.index += 2;
    } else if (type == '=' && ctx.syntax.get(RESyntax.RE_LOOKAHEAD)) {
        mod.pure = true;
        mod.lookAhead = true;
        ctx.index += 2;
    } else if (type == ':' && ctx.syntax.get(RESyntax.RE_PURE_GROUPING)) {
        mod.pure = true;
        ctx.index += 2;
    } else if (type == '#' && ctx.syntax.get(RESyntax.RE_COMMENTS)) {
        mod.comment = true;
    } else {
        throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, ctx.index);
    }
    return mod;
}

