  /** Returns true when the current unit is an alternation operator. */
  private boolean isAlternation(ParserContext ctx) {
    if (ctx.syntax.get(RESyntax.RE_LIMITED_OPS)) return false;
    return isAlternationOperator(ctx) || isNewlineAlternation(ctx);
  }

  private boolean isAlternationOperator(ParserContext ctx) {
    return isOperatorChar(ctx, '|', RESyntax.RE_NO_BK_VBAR);
  }

  private boolean isNewlineAlternation(ParserContext ctx) {
    return ctx.syntax.get(RESyntax.RE_NEWLINE_ALT) && isBareChar(ctx, '\n');
  }

  private boolean isInterval(ParserContext ctx) {
    return ctx.syntax.get(RESyntax.RE_INTERVALS) && isOperatorChar(ctx, '{', RESyntax.RE_NO_BK_BRACES);
  }

  private boolean isListStart(ParserContext ctx) {
    return isBareChar(ctx, '[');
