  private boolean isUnmatchedRightParen(ParserContext ctx) {
    return isRightParen(ctx) && !ctx.syntax.get(RESyntax.RE_UNMATCHED_RIGHT_PAREN_ORD);
  }

  private boolean isRightParen(ParserContext ctx) {
    return isOperatorChar(ctx, ')', RESyntax.RE_NO_BK_PARENS);
