  /** Buffers the current token and starts a new alternation branch. */
  private void handleAlternation(ParserContext ctx) {
    addToken(ctx.currentToken);
    if (ctx.branches == null) {
      ctx.branches = new Vector();
    }
    ctx.branches.addElement(new RE(firstToken, lastToken, numSubs, subIndex, minimumLength));
    minimumLength = 0;
    firstToken = lastToken = null;
    ctx.currentToken = null;
  }

  /** Parses an interval specification and applies it to the current token. */
  private void handleInterval(ParserContext ctx) throws REException {
    IntPair minMax = new IntPair();
    int newIndex = getMinMax(ctx.pattern, ctx.index, minMax, ctx.syntax);
    if (newIndex <= ctx.index) {
      addToken(ctx.currentToken);
      ctx.currentToken = new RETokenChar(subIndex, ctx.unit.ch, ctx.insens);
      return;
    }
    validateInterval(ctx, minMax);
    ctx.index = newIndex;
    ctx.currentToken = setRepeated(ctx.currentToken, minMax.first, minMax.second, ctx.index);
  }

  private void validateInterval(ParserContext ctx, IntPair minMax) throws REException {
    if (minMax.first > minMax.second) {
      throw new REException(getLocalizedMessage("interval.order"), REException.REG_BADRPT, ctx.index);
    }
    if (ctx.currentToken == null) {
      throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, ctx.index);
    }
    if (ctx.currentToken instanceof RETokenRepeated) {
      throw new REException(getLocalizedMessage("repeat.chained"), REException.REG_BADRPT, ctx.index);
    }
    if (ctx.currentToken instanceof RETokenWordBoundary) {
      throw new REException(getLocalizedMessage("repeat.assertion"), REException.REG_BADRPT, ctx.index);
    }
    if (ctx.currentToken.getMinimumLength() == 0 && minMax.second == Integer.MAX_VALUE) {
      throw new REException(getLocalizedMessage("repeat.empty.token"), REException.REG_BADRPT, ctx.index);
    }
  }
