    if (c == 'd') return new RETokenPOSIX(subIndex, RETokenPOSIX.DIGIT, ctx.insens, false);
    if (c == 'D') return new RETokenPOSIX(subIndex, RETokenPOSIX.DIGIT, ctx.insens, true);
    if (c == 's') return new RETokenPOSIX(subIndex, RETokenPOSIX.SPACE, ctx.insens, false);
    if (c == 'S') return new RETokenPOSIX(subIndex, RETokenPOSIX.SPACE, ctx.insens, true);
    if (c == 'w') return new RETokenPOSIX(subIndex, RETokenPOSIX.ALNUM, ctx.insens, false);
    if (c == 'W') return new RETokenPOSIX(subIndex, RETokenPOSIX.ALNUM, ctx.insens, true);
    return null;
  }

  private boolean isAsciiEscape(char c) {
    return "nrt".indexOf(c) != -1;
  }

  private char asciiValue(char c) {
    if (c == 'n') return '\n';
    if (c == 'r') return '\r';
    if (c == 't') return '\t';
    return 0;
  }

  private void parseListPosixClass(ParserContext ctx, Vector options) {
    StringBuffer posixSet = new StringBuffer();
    ctx.index = getPosixSet(ctx.pattern, ctx.index + 1, posixSet);
    int posixId = RETokenPOSIX.intValue(posixSet.toString());
    if (posixId != -1) {
      options.addElement(new RETokenPOSIX(subIndex, posixId, ctx.insens, false));
    }
  }

  private char parseListPlainChar(ParserContext ctx, Vector options, char lastChar, char ch) {
    if (lastChar != 0) {
      options.addElement(new RETokenChar(subIndex, lastChar, ctx.insens));
    }
    return ch;
  }
