```
  /** Holds modifier flags for a parenthesized subexpression. */
  private static class SubexpressionModifier {
    boolean pure;
    boolean comment;
    boolean lookAhead;
    boolean negativeLookAhead;
  }

  /** Parses a parenthesized subexpression and creates a token for it. */
  private void handleSubexpression(ParserContext ctx) throws REException {
    SubexpressionModifier mod = parseSubexpressionModifier(ctx);
    if (ctx.index >= ctx.pLength) {
      throw new REException(getLocalizedMessage("unmatched.paren"), REException.REG_ESUBREG, ctx.index);
    }
    int startIndex = ctx.index;
    IntPair bounds = findSubexpressionEnd(ctx);
    if (mod.comment) {
      ctx.index = bounds.second;
      return;
    }
    addToken(ctx.currentToken);
    ctx.currentToken = null;
    if (!mod.pure) {
      numSubs++;
    }
    int useIndex = subexpressionUseIndex(mod, ctx.nextSub, numSubs);
    ctx.currentToken = createSubexpression(ctx, startIndex, bounds, useIndex);
    numSubs += ((RE) ctx.currentToken).getNumSubs();
    if (mod.lookAhead) {
      ctx.currentToken = new RETokenLookAhead(ctx.currentToken, mod.negativeLookAhead);
    }
    ctx.index = bounds.second;
  }

  private int subexpressionUseIndex(SubexpressionModifier mod, int nextSub, int numSubs) {
    if (mod.pure || mod.lookAhead) {
      return 0;
    }
    return nextSub + numSubs;
  }

  private RE createSubexpression(ParserContext ctx, int startIndex, IntPair bounds, int useIndex) throws REException {
    return new RE(String.valueOf(ctx.pattern, startIndex, bounds.first - startIndex).toCharArray(),
                  ctx.cflags, ctx.syntax, useIndex, ctx.nextSub + numSubs);
  }

  private SubexpressionModifier parseSubexpressionModifier(ParserContext ctx) throws REException {
    SubexpressionModifier mod = new SubexpressionModifier();
    if (ctx.index + 1 >= ctx.pLength) {
      return mod;
    }
    if (ctx.pattern[ctx.index] != '?') {
      return mod;
    }
    char type = ctx.pattern[ctx.index + 1];
    if (type == '!' && ctx.syntax.get(RESyntax.RE_LOOKAHEAD)) {
      mod.pure = true;
      mod.lookAhead = true;
      mod.negativeLookAhead = true;
      ctx.index += 2;
    } else if (type == '=' && ctx.syntax.get(RESyntax.RE_LOOKAHEAD)) {
      mod.pure = true;
      mod.lookAhead = true;
      ctx.index += 2;
    } else if (type == ':' && ctx.syntax.get(RESyntax.RE_PURE_GROUPING)) {
      mod.pure = true;
      ctx.index += 2;
    } else if (type == '#' && ctx.syntax.get(RESyntax.RE_COMMENTS)) {
      mod.comment = true;
    } else {
      throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, ctx.index);
    }
    return mod;
  }

  private IntPair findSubexpressionEnd(ParserContext ctx) throws REException {
    IntPair bounds = new IntPair();
    bounds.first = ctx.index;
    bounds.second = ctx.index;
    int nested = 0;
    while (true) {
      if (bounds.first >= ctx.pLength) {
        throw new REException(getLocalizedMessage("subexpr.no.end"), REException.REG_ESUBREG, bounds.first);
      }
      bounds.second = getCharUnit(ctx.pattern, bounds.first, ctx.unit);
      if (isSubexpressionEnd(ctx, nested)) {
        return bounds;
      }
      bounds.first = bounds.second;
      if (isOpenParen(ctx)) {
        nested++;
      } else if (isCloseParen(ctx)) {
        nested--;
      }
    }
  }

  private boolean isSubexpressionEnd(ParserContext ctx, int nested) {
    return nested == 0 && isRightParen(ctx);
  }

  private boolean isOpenParen(ParserContext ctx) {
    return isOperatorChar(ctx, '(', RESyntax.RE_NO_BK_PARENS);
  }

  private boolean isCloseParen(ParserContext ctx) {
    return isOperatorChar(ctx, ')', RESyntax.RE_NO_BK_PARENS);
  }
