  private int getMinMax(char[] input, int index, IntPair minMax, RESyntax syntax) throws REException {
    boolean mustMatch = !syntax.get(RESyntax.RE_NO_BK_BRACES);
    int startIndex = index;
    if (isAtEnd(input, index)) {
      return handleOptionalBrace(mustMatch, startIndex, index, "unmatched.brace");
    }
    CharUnit unit = new CharUnit();
    StringBuffer buf = new StringBuffer();
    index = readDigits(input, index, unit, buf);
    if (buf.length() == 0) {
      return handleOptionalBrace(mustMatch, startIndex, index, "interval.error");
    }
    int min = Integer.parseInt(buf.toString());
    if (isClosingBrace(unit, syntax)) {
      return setMinMax(minMax, min, min, index);
    }
    if (isAtEnd(input, index)) {
      return handleOptionalBrace(mustMatch, startIndex, index, "interval.no.end");
    }
    if (isComma(unit)) {
      return parseMaxRange(input, index, unit, minMax, min, mustMatch, startIndex, syntax);
    }
    return handleOptionalBrace(mustMatch, startIndex, index, "interval.error");
  }

  private int readDigits(char[] input, int index, CharUnit unit, StringBuffer buf) throws REException {
    do {
      index = getCharUnit(input, index, unit);
      if (Character.isDigit(unit.ch)) {
        buf.append(unit.ch);
      }
    } while (index != input.length && Character.isDigit(unit.ch));
    return index;
  }

  private int parseMaxRange(char[] input, int index, CharUnit unit, IntPair minMax,
                            int min, boolean mustMatch, int startIndex, RESyntax syntax) throws REException {
    StringBuffer buf = new StringBuffer();
    index = readDigits(input, index, unit, buf);
    if (!isClosingBrace(unit, syntax)) {
      return handleOptionalBrace(mustMatch, startIndex, index, "interval.error");
    }
    int max = (buf.length() == 0) ? Integer.MAX_VALUE : Integer.parseInt(buf.toString());
    return setMinMax(minMax, min, max, index);
  }

  private boolean isClosingBrace(CharUnit unit, RESyntax syntax) {
    return unit.ch == '}' && (syntax.get(RESyntax.RE_NO_BK_BRACES) ^ unit.bk);
  }

  private boolean isComma(CharUnit unit) {
    return unit.ch == ',' && !unit.bk;
  }

  private boolean isAtEnd(char[] input, int index) {
    return index == input.length;
  }

  private int handleOptionalBrace(boolean mustMatch, int startIndex, int index, String key) throws REException {
    if (mustMatch) {
      throw new REException(getLocalizedMessage(key), REException.REG_EBRACE, index);
    }
    return startIndex;
  }

  private int setMinMax(IntPair minMax, int min, int max, int index) {
    minMax.first = min;
    minMax.second = max;
    return index;
  }
