  protected void initialize(Object patternObj, int cflags, RESyntax syntax, int myIndex, int nextSub) throws REException {
    char[] pattern = patternToCharArray(patternObj);
    int pLength = pattern.length;

    numSubs = 0;
    Vector branches = null;
    firstToken = lastToken = null;

    boolean insens = isCaseInsensitive(cflags);

    int index = 0;
    CharUnit unit = new CharUnit();
    IntPair minMax = new IntPair();
    REToken currentToken = null;

    while (index < pLength) {
      index = getCharUnit(pattern, index, unit);
      ParseResult step = processUnit(pattern, pLength, cflags, syntax, unit, index, currentToken, minMax, branches, insens);
      currentToken = step.currentToken;
      index = step.index;
      branches = step.branches;
    }

    addToken(currentToken);

    if (branches != null) {
      branches.addElement(new RE(firstToken, lastToken, numSubs, subIndex, minimumLength));
      branches.trimToSize();
      minimumLength = 0;
      firstToken = lastToken = null;
      addToken(new RETokenOneOf(subIndex, branches, false));
    } else {
      addToken(new RETokenEndSub(subIndex));
    }
  }

