  private ParseResult processUnit(char[] pattern, int pLength, int cflags, RESyntax syntax, CharUnit unit, int index, REToken currentToken, IntPair minMax, Vector branches, boolean insens) throws REException {
    if (isAlternationOperator(unit, syntax)) {
      return handleAlternation(currentToken, branches, index);
    }
    if (isIntervalOperator(unit, syntax)) {
      return handleInterval(pattern, index, syntax, currentToken, minMax, insens);
    }
    if (isListOperator(unit)) {
      return handleList(pattern, pLength, syntax, index, currentToken, insens);
    }
    if (isSubexpressionOperator(unit, syntax)) {
      return handleSubexpression(pattern, pLength, cflags, syntax, index, currentToken);
    }
    if (isUnmatchedRightParen(unit, syntax)) {
      throw new REException(getLocalizedMessage("unmatched.paren"), REException.REG_EPAREN, index);
    }
    if (isStartOfLineOperator(unit)) {
      return handleStartOfLine(currentToken, cflags, syntax);
    }
    if (isEndOfLineOperator(unit)) {
      return handleEndOfLine(currentToken, cflags, syntax);
    }
    if (isDotOperator(unit)) {
      return handleDot(currentToken, cflags, syntax);
    }
    if (isStarOperator(unit)) {
      return handleStar(currentToken, index);
    }
    if (isPlusOperator(unit, syntax)) {
      return handlePlus(currentToken, index);
    }
    if (isQuestionOperator(unit, syntax)) {
      return handleQuestion(currentToken, syntax, index);
    }
    if (isBackreferenceOperator(unit, syntax)) {
      return handleBackreference(currentToken, unit, insens, index);
    }
    if (isStringAnchorEscape(unit, 'A', syntax, RESyntax.RE_STRING_ANCHORS)) {
      return handleStringStart(currentToken, index);
    }
    if (isStringAnchorEscape(unit, 'b', syntax, RESyntax.RE_STRING_ANCHORS)) {
      return handleWordBoundary(currentToken, index, RETokenWordBoundary.BEGIN | RETokenWordBoundary.END, false);
    }
    if (isEscapedChar(unit, '<')) {
      return handleWordBoundary(currentToken, index, RETokenWordBoundary.BEGIN, false);
    }
    if (isEscapedChar(unit, '>')) {
      return handleWordBoundary(currentToken, index, RETokenWordBoundary.END, false);
    }
    if (isStringAnchorEscape(unit, 'B', syntax, RESyntax.RE_STRING_ANCHORS)) {
      return handleWordBoundary(currentToken, index, RETokenWordBoundary.BEGIN | RETokenWordBoundary.END, true);
    }
    if (isCharClassEscape(unit, 'd', syntax, RESyntax.RE_CHAR_CLASS_ESCAPES)) {
      return handleCharClass(currentToken, index, RETokenPOSIX.DIGIT, insens, false);
    }
    if (isCharClassEscape(unit, 'D', syntax, RESyntax.RE_CHAR_CLASS_ESCAPES)) {
      return handleCharClass(currentToken, index, RETokenPOSIX.DIGIT, insens, true);
    }
    if (isEscapedChar(unit, 'n')) {
      return handleLiteralChar(currentToken, index, '\n', false);
    }
    if (isEscapedChar(unit, 'r')) {
      return handleLiteralChar(currentToken, index, '\r', false);
    }
    if (isCharClassEscape(unit, 's', syntax, RESyntax.RE_CHAR_CLASS_ESCAPES)) {
      return handleCharClass(currentToken, index, RETokenPOSIX.SPACE, insens, false);
    }
    if (isCharClassEscape(unit, 'S', syntax, RESyntax.RE_CHAR_CLASS_ESCAPES)) {
      return handleCharClass(currentToken, index, RETokenPOSIX.SPACE, insens, true);
    }
    if (isEscapedChar(unit, 't')) {
      return handleLiteralChar(currentToken, index, '\t', false);
    }
    if (isCharClassEscape(unit, 'w', syntax, RESyntax.RE_CHAR_CLASS_ESCAPES)) {
      return handleCharClass(currentToken, index, RETokenPOSIX.ALNUM, insens, false);
    }
    if (isCharClassEscape(unit, 'W', syntax, RESyntax.RE_CHAR_CLASS_ESCAPES)) {
      return handleCharClass(currentToken, index, RETokenPOSIX.ALNUM, insens, true);
    }
    if (isStringAnchorEscape(unit, 'Z', syntax, RESyntax.RE_STRING_ANCHORS)) {
      return handleStringEnd(currentToken, index);
    }
    return handleOrdinaryChar(currentToken, index, unit.ch, insens);
  }

