  private static boolean isAlternationOperator(CharUnit unit, RESyntax syntax) {
    return !syntax.get(RESyntax.RE_LIMITED_OPS)
        && ((unit.ch == '|' && (syntax.get(RESyntax.RE_NO_BK_VBAR) ^ unit.bk))
            || (syntax.get(RESyntax.RE_NEWLINE_ALT) && unit.ch == '\n' && !unit.bk));
  }

  private static boolean isIntervalOperator(CharUnit unit, RESyntax syntax) {
    return unit.ch == '{' && syntax.get(RESyntax.RE_INTERVALS) && (syntax.get(RESyntax.RE_NO_BK_BRACES) ^ unit.bk);
  }

  private static boolean isListOperator(CharUnit unit) {
    return unit.ch == '[' && !unit.bk;
  }

  private static boolean isSubexpressionOperator(CharUnit unit, RESyntax syntax) {
    return unit.ch == '(' && (syntax.get(RESyntax.RE_NO_BK_PARENS) ^ unit.bk);
  }

  private static boolean isUnmatchedRightParen(CharUnit unit, RESyntax syntax) {
    return !syntax.get(RESyntax.RE_UNMATCHED_RIGHT_PAREN_ORD)
        && unit.ch == ')'
        && (syntax.get(RESyntax.RE_NO_BK_PARENS) ^ unit.bk);
  }

  private static boolean isStartOfLineOperator(CharUnit unit) {
    return unit.ch == '^' && !unit.bk;
  }

  private static boolean isEndOfLineOperator(CharUnit unit) {
    return unit.ch == '$' && !unit.bk;
  }

  private static boolean isDotOperator(CharUnit unit) {
    return unit.ch == '.' && !unit.bk;
  }

  private static boolean isStarOperator(CharUnit unit) {
    return unit.ch == '*' && !unit.bk;
  }

  private static boolean isPlusOperator(CharUnit unit, RESyntax syntax) {
    return unit.ch == '+' && !syntax.get(RESyntax.RE_LIMITED_OPS) && (!syntax.get(RESyntax.RE_BK_PLUS_QM) ^ unit.bk);
  }

  private static boolean isQuestionOperator(CharUnit unit, RESyntax syntax) {
    return unit.ch == '?' && !syntax.get(RESyntax.RE_LIMITED_OPS) && (!syntax.get(RESyntax.RE_BK_PLUS_QM) ^ unit.bk);
  }

  private static boolean isBackreferenceOperator(CharUnit unit, RESyntax syntax) {
    return unit.bk && Character.isDigit(unit.ch) && !syntax.get(RESyntax.RE_NO_BK_REFS);
  }

  private static boolean isStringAnchorEscape(CharUnit unit, char anchor, RESyntax syntax, int syntaxFlag) {
