  private ParseResult handleSubexpression(char[] pattern, int pLength, int cflags, RESyntax syntax, int index, REToken currentToken) throws REException {
    GroupOptions options = readGroupOptions(pattern, pLength, syntax, index);
    if (options.index >= pLength) {
      throw new REException(getLocalizedMessage("unmatched.paren"), REException.REG_ESUBREG, options.index);
    }
    int nextIndex = findSubexpressionEnd(pattern, pLength, syntax, options.index);
    if (options.comment) {
      return new ParseResult(currentToken, nextIndex);
    }
    addToken(currentToken);
    if (!options.pure) {
      numSubs++;
    }
    int useIndex = computeSubexpressionIndex(options, numSubs, nextSub);
    REToken sub = new RE(String.valueOf(pattern, options.index, nextIndex - options.index).toCharArray(), cflags, syntax, useIndex, nextSub + numSubs);
    numSubs += ((RE) sub).getNumSubs();
    if (options.lookAhead) {
      sub = new RETokenLookAhead(sub, options.negativeLookahead);
    }
    return new ParseResult(sub, nextIndex);
  }

readGroupOptions:
  private static GroupOptions readGroupOptions(char[] pattern, int pLength, RESyntax syntax, int index) throws REException {
    boolean pure = false;
    boolean comment = false;
    boolean lookAhead = false;
    boolean negativeLookahead = false;
    if ((index + 1 < pLength) && (pattern[index] == '?')) {
      char marker = pattern[index + 1];
      if (marker == '!') {
        if (syntax.get(RESyntax.RE_LOOKAHEAD)) {
          pure = true;
          negativeLookahead = true;
          lookAhead = true;
          index += 2;
        }
      } else if (marker == '=') {
        if (syntax.get(RESyntax.RE_LOOKAHEAD)) {
          pure = true;
          lookAhead = true;
          index += 2;
        }
      } else if (marker == ':') {
        if (syntax.get(RESyntax.RE_PURE_GROUPING)) {
          pure = true;
          index += 2;
        }
      } else if (marker == '#') {
        if (syntax.get(RESyntax.RE_COMMENTS)) {
          comment = true;
        }
      } else {
        throw new REException(getLocalizedMessage("repeat.no.token"), REException.REG_BADRPT, index);
      }
    }
    return new GroupOptions(pure, comment, lookAhead, negativeLookahead, index);
  }

computeSubexpressionIndex:
  private static int computeSubexpressionIndex(GroupOptions options, int numSubs, int nextSub) {
    if (options.pure || options.lookAhead) {
      return 0;
    }
    return nextSub + numSubs;
  }

