private static class ParseContext {
    final char[] pattern;
    final int pLength;
    final int cflags;
    final RESyntax syntax;
    final IntPair minMax;
    final boolean insens;
    final int nextSub;
    int index;
    REToken currentToken;
    Vector branches;
    ParseContext(char[] pattern, int pLength, int cflags, RESyntax syntax, IntPair minMax, boolean insens, int nextSub, int index, REToken currentToken, Vector branches) {
        this.pattern = pattern;
        this.pLength = pLength;
        this.cflags = cflags;
        this.syntax = syntax;
        this.minMax = minMax;
        this.insens = insens;
        this.nextSub = nextSub;
        this.index = index;
        this.currentToken = currentToken;
        this.branches = branches;
