private boolean tryStructuralOperator(ParseContext ctx, CharUnit unit) throws REException {
    if (isAlternationOperator(unit, ctx.syntax)) { handleAlternation(ctx); return true; }
    if (isIntervalOperator(unit, ctx.syntax)) { handleInterval(ctx); return true; }
    if (isListOperator(unit)) { handleList(ctx); return true; }
    if (isSubexpressionOperator(unit, ctx.syntax)) { handleSubexpression(ctx); return true; }
    if (isUnmatchedRightParen(unit, ctx.syntax)) { throw ...; }
    if (isStartOfLineOperator(unit)) { handleStartOfLine(ctx); return true; }
    if (isEndOfLineOperator(unit)) { handleEndOfLine(ctx); return true; }
    if (isDotOperator(unit)) { handleDot(ctx); return true; }
    return false;
}

