private boolean tryAnchorEscape(ParseContext ctx, CharUnit unit) throws REException {
    if (isStringAnchorEscape(unit, 'A', ctx.syntax, RESyntax.RE_STRING_ANCHORS)) { handleStringStart(ctx); return true; }
    if (isStringAnchorEscape(unit, 'b', ctx.syntax, RESyntax.RE_STRING_ANCHORS)) { handleWordBoundary(ctx, RETokenWordBoundary.BEGIN | RETokenWordBoundary.END, false); return true; }
    if (isEscapedChar(unit, '<')) { handleWordBoundary(ctx, RETokenWordBoundary.BEGIN, false); return true; }
    if (isEscapedChar(unit, '>')) { handleWordBoundary(ctx, RETokenWordBoundary.END, false); return true; }
    if (isStringAnchorEscape(unit, 'B', ctx.syntax, RESyntax.RE_STRING_ANCHORS)) { handleWordBoundary(ctx, RETokenWordBoundary.BEGIN | RETokenWordBoundary.END, true); return true; }
    if (isStringAnchorEscape(unit, 'Z', ctx.syntax, RESyntax.RE_STRING_ANCHORS)) { handleStringEnd(ctx); return true; }
    return false;
}

