handleAlternation:
private void handleAlternation(ParseContext ctx) {
    addToken(ctx.currentToken);
    RE branch = new RE(firstToken, lastToken, numSubs, subIndex, minimumLength);
    minimumLength = 0;
    if (ctx.branches == null) {
        ctx.branches = new Vector();
    }
    ctx.branches.addElement(branch);
    firstToken = lastToken = null;
    ctx.currentToken = null;
}

handleInterval:
private void handleInterval(ParseContext ctx) throws REException {
    int newIndex = getMinMax(ctx.pattern, ctx.index, ctx.minMax, ctx.syntax);
    if (newIndex <= ctx.index) {
        addToken(ctx.currentToken);
        ctx.currentToken = new RETokenChar(subIndex, '{', ctx.insens);
        return;
    }
    validateInterval(ctx.currentToken, ctx.minMax, newIndex);
    ctx.currentToken = setRepeated(ctx.currentToken, ctx.minMax.first, ctx.minMax.second, newIndex);
    ctx.index = newIndex;
}

handleList:
private void handleList(ParseContext ctx) throws REException {
    addToken(ctx.currentToken);
    ListState state = new ListState();
    state.options = new Vector();
    state.index = ctx.index;
    state.lastChar = 0;
    state.negative = false;
    if (state.index == ctx.pLength) { throw ...; }
    char ch = ctx.pattern[state.index];
    if (ch == '^') { ... }
    if (ch == ']') { ... }
    while (true) {
        ch = ctx.pattern[state.index++];
        if (ch == ']') break;
        if (ch == '-' && state.lastChar != 0) { state = handleListDash(ctx, state); }
        else if (ch == '\\' && ctx.syntax.get(RE_BACKSLASH_ESCAPE_IN_LISTS)) { state = handleListBackslash(ctx, state); }
        else if (ch == '[' && ctx.syntax.get(RE_CHAR_CLASSES) && state.index < ctx.pLength && ctx.pattern[state.index] == ':') { state = handleListPosix(ctx, state); }
        else { state = handleListChar(state, ch, ctx.insens); }
        if (state.index == ctx.pLength) throw ...;
    }
    if (state.lastChar != 0) add char;
    state.options.trimToSize();
    ctx.currentToken = new RETokenOneOf(subIndex, state.options, state.negative);
    ctx.index = state.index;
}

