handleSubexpression:
private void handleSubexpression(ParseContext ctx) throws REException {
    GroupOptions options = readGroupOptions(ctx.pattern, ctx.pLength, ctx.syntax, ctx.index);
    if (options.index >= ctx.pLength) throw ...;
    int nextIndex = findSubexpressionEnd(ctx.pattern, ctx.pLength, ctx.syntax, options.index);
    if (options.comment) {
        ctx.index = nextIndex;
        return;
    }
    addToken(ctx.currentToken);
    if (!options.pure) numSubs++;
    int useIndex = computeSubexpressionIndex(options, numSubs, ctx.nextSub);
    REToken sub = new RE(String.valueOf(ctx.pattern, options.index, nextIndex - options.index).toCharArray(), ctx.cflags, ctx.syntax, useIndex, ctx.nextSub + numSubs);
    numSubs += ((RE) sub).getNumSubs();
    if (options.lookAhead) sub = new RETokenLookAhead(sub, options.negativeLookahead);
    ctx.currentToken = sub;
    ctx.index = nextIndex;
}

