private void handleDot(ParseContext ctx) {
    addToken(ctx.currentToken);
    boolean dotNewline = ctx.syntax.get(RE_DOT_NEWLINE) || isDotNewlineFlag(ctx.cflags);
    ctx.currentToken = new RETokenAny(subIndex, dotNewline, ctx.syntax.get(RE_DOT_NOT_NULL));
}

