private void handleQuestion(ParseContext ctx) throws REException {
    if (ctx.currentToken == null) throw ...;
    if (ctx.currentToken instanceof RETokenRepeated) {
        handleStingy((RETokenRepeated) ctx.currentToken, ctx.syntax, ctx.index);
        return;
    }
    if (ctx.currentToken instanceof RETokenWordBoundary) throw ...;
    ctx.currentToken = setRepeated(ctx.currentToken, 0, 1, ctx.index);
}

