private static Boolean longComparisonOperation(long lhs, long rhs, int kind) {
    switch(kind) {
        case LT:
        case LTX: return new Boolean(lhs < rhs);
        case GT:
        case GTX: return new Boolean(lhs > rhs);
        case EQ: return new Boolean(lhs == rhs);
        case LE:
        case LEX: return new Boolean(lhs <= rhs);
        case GE:
        case GEX: return new Boolean(lhs >= rhs);
        case NE: return new Boolean(lhs != rhs);
        default: throw new InterpreterError("Unimplemented binary long operator");
    }
}
```
