        if(isComparisonOperator(kind))
            return intComparisonOperation(lhs, rhs, kind);
        if(isArithmeticOperator(kind))
            return intArithmeticOperation(lhs, rhs, kind);
        if(isBitwiseOperator(kind))
            return intBitwiseOperation(lhs, rhs, kind);

        throw new InterpreterError("Unimplemented binary integer operator");
    }

