    // returns Object covering both Long and Boolean return types
    static Object floatBinaryOperation(Float F1, Float F2, int kind)
        throws EvalError
    {
        float lhs = F1.floatValue();
        float rhs = F2.floatValue();

        switch(kind)
        {
            case LT: case LTX: case GT: case GTX: case EQ:
            case LE: case LEX: case GE: case GEX: case NE:
                return floatComparisonOperation(lhs, rhs, kind);

            case PLUS: case MINUS: case STAR: case SLASH: case MOD:
                return floatArithmeticOperation(lhs, rhs, kind);

            case LSHIFT: case LSHIFTX: case RSIGNEDSHIFT: case RSIGNEDSHIFTX:
            case RUNSIGNEDSHIFT: case RUNSIGNEDSHIFTX:
                throw new EvalError("Can't shift floats ");

            default:
                throw new InterpreterError("Unimplemented binary float operator");
