	/**
		Allow primitive operations on wrapper types such as Integer and Boolean.
		This is static so that it can be reached from wherever...
	*/
    public static Object binaryOperation(
		Object obj1, Object obj2, int kind)
        throws EvalError
    {
        validateBinaryOperands(obj1, obj2);

        Class lhsOrgType = obj1.getClass();
        Class rhsOrgType = obj2.getClass();

        obj1 = unwrapBinaryOperand(obj1);
        obj2 = unwrapBinaryOperand(obj2);

        Object[] operands = promotePrimitives(obj1, obj2);
        Object lhs = operands[0];
        Object rhs = operands[1];

        if(lhs.getClass() != rhs.getClass())
            throw new EvalError("type mismatch in operator.  " 
			+ lhs.getClass() + " cannot be used with " + rhs.getClass() );

        Object result = executeBinaryOperation(lhs, rhs, kind);

        return wrapBinaryResult(result, lhsOrgType, rhsOrgType);
    }

    /**
        Validates that the given operands are valid for a binary operation.
    */
    private static void validateBinaryOperands(Object obj1, Object obj2)
        throws EvalError
    {
        if(obj1 == NULL || obj2 == NULL)
            throw new EvalError(
                "Null value or 'null' literal in binary operation");
        if(obj1 == VOID || obj2 == VOID)
            throw new EvalError(
                "Undefined variable, class, or 'void' literal in binary operation");
    }

    /**
        Unwraps a Primitive operand to its underlying value.
    */
    private static Object unwrapBinaryOperand(Object obj)
    {
        if(obj instanceof Primitive)
            return ((Primitive)obj).getValue();
        return obj;
    }

    /**
        Executes the binary operation on the promoted operands.
    */
    private static Object executeBinaryOperation(Object lhs, Object rhs, int kind)
        throws EvalError
    {
        try {
            return binaryOperationImpl(lhs, rhs, kind);
        } catch (ArithmeticException e) {
            throw new TargetError("Arithemetic Exception in binary op", e);
        }
    }

    /**
        Wraps the binary operation result in a Primitive if both original
        operands were Primitives.
    */
    private static Object wrapBinaryResult(
        Object result, Class lhsOrgType, Class rhsOrgType)
    {
        if(lhsOrgType == Primitive.class && rhsOrgType == Primitive.class)
            return new Primitive(result);
        return result;
    }

    static Object binaryOperationImpl( Object lhs, Object rhs, int kind )
        throws EvalError
	{
        if(lhs instanceof Boolean)
            return booleanBinaryOperation((Boolean)lhs, (Boolean)rhs, kind);
        else if(lhs instanceof Integer)
            return intBinaryOperation( (Integer)lhs, (Integer)rhs, kind );
        else if(lhs instanceof Long)
            return longBinaryOperation((Long)lhs, (Long)rhs, kind);
        else if(lhs instanceof Float)
            return floatBinaryOperation((Float)lhs, (Float)rhs, kind);
        else if(lhs instanceof Double)
            return doubleBinaryOperation( (Double)lhs, (Double)rhs, kind);
        else
            throw new EvalError("Invalid types in binary operator" );
	}

    /**
        Determines if the given operator kind is a comparison operator.
    */
    private static boolean isComparisonOperator(int kind)
    {
        return kind == LT || kind == LTX || kind == GT || kind == GTX
            || kind == EQ || kind == LE || kind == LEX
            || kind == GE || kind == GEX || kind == NE;
    }

    /**
        Determines if the given operator kind is an arithmetic operator.
    */
    private static boolean isArithmeticOperator(int kind)
    {
        return kind == PLUS || kind == MINUS || kind == STAR
            || kind == SLASH || kind == MOD;
    }

    /**
        Determines if the given operator kind is a bitwise operator.
    */
    private static boolean isBitwiseOperator(int kind)
    {
        return kind == LSHIFT || kind == LSHIFTX
            || kind == RSIGNEDSHIFT || kind == RSIGNEDSHIFTX
            || kind == RUNSIGNEDSHIFT || kind == RUNSIGNEDSHIFTX
            || kind == BIT_AND || kind == BIT_ANDX
            || kind == BIT_OR || kind == BIT_ORX
            || kind == XOR;
    }

    static Boolean booleanBinaryOperation(Boolean B1, Boolean B2, int kind)
        throws EvalError
    {
        boolean lhs = B1.booleanValue();
        boolean rhs = B2.booleanValue();

        switch(kind)
        {
            case EQ:
                return new Boolean(lhs == rhs);

            case NE:
                return new Boolean(lhs != rhs);

            case BOOL_OR:
            case BOOL_ORX:
                return new Boolean( lhs || rhs );

            case BOOL_AND:
            case BOOL_ANDX:
                return new Boolean( lhs && rhs );

            default:
                throw new InterpreterError("unimplemented binary operator");
        }
    }

    // returns Object covering both Long and Boolean return types
    static Object longBinaryOperation(Long L1, Long L2, int kind)
    {
        long lhs = L1.longValue();
        long rhs = L2.longValue();

        if(isComparisonOperator(kind))
            return longComparisonOperation(lhs, rhs, kind);
        if(isArithmeticOperator(kind))
            return longArithmeticOperation(lhs, rhs, kind);
        if(isBitwiseOperator(kind))
            return longBitwiseOperation(lhs, rhs, kind);

        throw new InterpreterError("Unimplemented binary long operator");
    }

    /**
        Performs a comparison operation on two long values.
    */
    private static Object longComparisonOperation(long lhs, long rhs, int kind)
    {
        switch(kind)
        {
            case LT:
            case LTX:
                return new Boolean(lhs < rhs);

            case GT:
            case GTX:
                return new Boolean(lhs > rhs);

            case EQ:
                return new Boolean(lhs == rhs);

            case LE:
            case LEX:
                return new Boolean(lhs <= rhs);

            case GE:
            case GEX:
                return new Boolean(lhs >= rhs);

            case NE:
                return new Boolean(lhs != rhs);

            default:
                throw new InterpreterError("Unimplemented long comparison operator");
        }
    }

    /**
        Performs an arithmetic operation on two long values.
    */
    private static Object longArithmeticOperation(long lhs, long rhs, int kind)
    {
        switch(kind)
        {
            case PLUS:
                return new Long(lhs + rhs);

            case MINUS:
                return new Long(lhs - rhs);

            case STAR:
                return new Long(lhs * rhs);

            case SLASH:
                return new Long(lhs / rhs);

            case MOD:
                return new Long(lhs % rhs);

            default:
                throw new InterpreterError("Unimplemented long arithmetic operator");
        }
    }

    /**
        Performs a bitwise operation on two long values.
    */
    private static Object longBitwiseOperation(long lhs, long rhs, int kind)
    {
        switch(kind)
        {
            case LSHIFT:
            case LSHIFTX:
                return new Long(lhs << rhs);

            case RSIGNEDSHIFT:
            case RSIGNEDSHIFTX:
                return new Long(lhs >> rhs);

            case RUNSIGNEDSHIFT:
            case RUNSIGNEDSHIFTX:
                return new Long(lhs >>> rhs);

            case BIT_AND:
            case BIT_ANDX:
                return new Long(lhs & rhs);

            case BIT_OR:
            case BIT_ORX:
                return new Long(lhs | rhs);

            case XOR:
                return new Long(lhs ^ rhs);

            default:
                throw new InterpreterError("Unimplemented long bitwise operator");
        }
    }

    // returns Object covering both Integer and Boolean return types
    static Object intBinaryOperation(Integer I1, Integer I2, int kind)
    {
        int lhs = I1.intValue();
        int rhs = I2.intValue();

        if(isComparisonOperator(kind))
            return intComparisonOperation(lhs, rhs, kind);
        if(isArithmeticOperator(kind))
            return intArithmeticOperation(lhs, rhs, kind);
        if(isBitwiseOperator(kind))
            return intBitwiseOperation(lhs, rhs, kind);

        throw new InterpreterError("Unimplemented binary integer operator");
    }

