    /**
        Performs a bitwise operation on two int values.
    */
    private static Object intBitwiseOperation(int lhs, int rhs, int kind)
    {
        switch(kind)
        {
            case LSHIFT:
            case LSHIFTX:
                return new Integer(lhs << rhs);

            case RSIGNEDSHIFT:
