                return new Integer(lhs ^ rhs);

            default:
                throw new InterpreterError("Unimplemented integer bitwise operator");
        }
    }

    // returns Object covering both Double and Boolean return types
    static Object doubleBinaryOperation(Double D1, Double D2, int kind)
        throws EvalError
    {
        double lhs = D1.doubleValue();
        double rhs = D2.doubleValue();

        if(isComparisonOperator(kind))
            return doubleComparisonOperation(lhs, rhs, kind);
        if(isArithmeticOperator(kind))
            return doubleArithmeticOperation(lhs, rhs, kind);
        if(isBitwiseOperator(kind))
            throw new EvalError("Can't shift doubles");

        throw new InterpreterError("Unimplemented binary double operator");
    }

    /**
        Performs a comparison operation on two double values.
    */
    private static Object doubleComparisonOperation(double lhs, double rhs, int kind)
    {
        switch(kind)
        {
            case LT:
