        if(isArithmeticOperator(kind))
            return floatArithmeticOperation(lhs, rhs, kind);
        if(isBitwiseOperator(kind))
            throw new EvalError("Can't shift floats ");

        throw new InterpreterError("Unimplemented binary float operator");
    }

    /**
        Performs a comparison operation on two float values.
    */
    private static Object floatComparisonOperation(float lhs, float rhs, int kind)
    {
        switch(kind)
        {
            case LT:
            case LTX:
                return new Boolean(lhs < rhs);

            case GT:
