package bsh;

/**
    Wrapper for primitive types in Bsh.  This is package public because it 
	is used in the implementation of some bsh commands.

    See the note in LHS.java about wrapping objects.
*/
public class Primitive implements ParserConstants, java.io.Serializable
{
    // stored internally in java.lang. wrappers
    private java.io.Serializable value;

    private static class Special implements java.io.Serializable
    {
        private Special() { }

        public static final Special NULL_VALUE = new Special();
        public static final Special VOID_TYPE = new Special();
    }

    /*
        NULL means "no value".
        This ia a placeholder for primitive null value.
    */
    public static final Primitive NULL = new Primitive(Special.NULL_VALUE);

    /**
        VOID means "no type".
        Strictly speaking, this makes no sense here.  But for practical
        reasons we'll consider the lack of a type to be a special value.
    */
    public static final Primitive VOID = new Primitive(Special.VOID_TYPE);

    // private to prevent invocation with param that isn't a primitive-wrapper
    private Primitive(Object value)
    {
        if(value == null)
            throw new InterpreterError(
				"Use Primitve.NULL instead of Primitive(null)");

        this.value = (java.io.Serializable)value;
    }

    public Primitive(Number number) { this((Object)number); }

    public Primitive(Boolean value) { this((Object)value); }
    public Primitive(Byte value) { this((Object)value); }
    public Primitive(Short value) { this((Object)value); }
    public Primitive(Character value) { this((Object)value); }
    public Primitive(Integer value) { this((Object)value); }
    public Primitive(Long value) { this((Object)value); }
    public Primitive(Float value) { this((Object)value); }
    public Primitive(Double value) { this((Object)value); }

    public Primitive(boolean value) { this(new Boolean(value)); }
    public Primitive(byte value) { this(new Byte(value)); }
    public Primitive(short value) { this(new Short(value)); }
    public Primitive(char value) { this(new Character(value)); }
    public Primitive(int value) { this(new Integer(value)); }
    public Primitive(long value) { this(new Long(value)); }
    public Primitive(float value) { this(new Float(value)); }
    public Primitive(double value) { this(new Double(value)); }

    public Object getValue()
    {
        if(value == Special.NULL_VALUE)
            return null;
        else if(value == Special.VOID_TYPE)
                throw new InterpreterError("attempt to unwrap void type");
        else
            return value;
    }

    public String toString()
    {
        if(value == Special.NULL_VALUE)
            return "null";
        else if(value == Special.VOID_TYPE)
            return "void";
        else
            return value.toString();
    }

    public Class getType()
    {
        return getType(value);
    }

    private Class getType(Object o)
    {
        if(o instanceof Boolean)
            return Boolean.TYPE;
        else if(o instanceof Byte)
            return Byte.TYPE;
        else if(o instanceof Short)
            return Short.TYPE;
        else if(o instanceof Character)
            return Character.TYPE;
        else if(o instanceof Integer)
            return Integer.TYPE;
        else if(o instanceof Long)
            return Long.TYPE;
        else if(o instanceof Float)
            return Float.TYPE;
        else if(o instanceof Double)
            return Double.TYPE;

        return null;
    }

/*
    public static Primitive binaryOperation(
		Primitive p1, Primitive p2, int kind )
        throws EvalError
    {
		return new Primitive( binaryOperation( p1, p2, kind ) );
    }
*/

	/**
		Allow primitive operations on wrapper types such as Integer and Boolean.
		This is static so that it can be reached from wherever...
	*/
    public static Object binaryOperation(
		Object obj1, Object obj2, int kind)
        throws EvalError
    {
		validateBinaryOperands(obj1, obj2);

		Class lhsOrgType = obj1.getClass();
		Class rhsOrgType = obj2.getClass();

		Object lhs = unwrapPrimitiveValue(obj1);
		Object rhs = unwrapPrimitiveValue(obj2);

		Object[] operands = promotePrimitives(lhs, rhs);
		lhs = operands[0];
		rhs = operands[1];

        if(lhs.getClass() != rhs.getClass())
            throw new EvalError("type mismatch in operator.  " 
			+ lhs.getClass() + " cannot be used with " + rhs.getClass() );

		Object result;
		try {
			result = binaryOperationImpl( lhs, rhs, kind );
		} catch ( ArithmeticException e ) {
			throw new TargetError("Arithemetic Exception in binary op", e);
		}

		return wrapBinaryResult(result, lhsOrgType, rhsOrgType);
    }

	/**
		Validates that neither operand is NULL or VOID.
	*/
	static void validateBinaryOperands(Object obj1, Object obj2) throws EvalError
	{
		if(obj1 == NULL || obj2 == NULL)
			throw new EvalError(
				"Null value or 'null' literal in binary operation");
		if(obj1 == VOID || obj2 == VOID)
			throw new EvalError(
			"Undefined variable, class, or 'void' literal in binary operation");
	}

	/**
		Unwraps a Primitive operand to its underlying value.
	*/
	static Object unwrapPrimitiveValue(Object obj)
	{
		if(obj instanceof Primitive)
			return ((Primitive)obj).getValue();
		return obj;
	}

	/**
		Wraps the binary operation result in a Primitive if both
		original arguments were Primitives.
	*/
	static Object wrapBinaryResult(Object result, Class lhsOrgType, Class rhsOrgType)
	{
		if ( lhsOrgType == Primitive.class && rhsOrgType == Primitive.class )
			return new Primitive( result );
		else
			return result;
	}

    static Object binaryOperationImpl( Object lhs, Object rhs, int kind )
        throws EvalError
	{
        if(lhs instanceof Boolean)
            return booleanBinaryOperation((Boolean)lhs, (Boolean)rhs, kind);
        else if(lhs instanceof Integer)
            return intBinaryOperation( (Integer)lhs, (Integer)rhs, kind );
        else if(lhs instanceof Long)
            return longBinaryOperation((Long)lhs, (Long)rhs, kind);
        else if(lhs instanceof Float)
            return floatBinaryOperation((Float)lhs, (Float)rhs, kind);
        else if(lhs instanceof Double)
            return doubleBinaryOperation( (Double)lhs, (Double)rhs, kind);
        else
            throw new EvalError("Invalid types in binary operator" );
	}


    static Boolean booleanBinaryOperation(Boolean B1, Boolean B2, int kind)
        throws EvalError
    {
        boolean lhs = B1.booleanValue();
        boolean rhs = B2.booleanValue();

        switch(kind)
        {
            case EQ:
                return new Boolean(lhs == rhs);

            case NE:
                return new Boolean(lhs != rhs);

            case BOOL_OR:
            case BOOL_ORX:
                return new Boolean( lhs || rhs );

            case BOOL_AND:
            case BOOL_ANDX:
                return new Boolean( lhs && rhs );

            default:
                throw new InterpreterError("unimplemented binary operator");
        }
    }

    // returns Object covering both Long and Boolean return types
    static Object longBinaryOperation(Long L1, Long L2, int kind)
    {
        long lhs = L1.longValue();
        long rhs = L2.longValue();

        switch(kind)
        {
            case LT: case LTX: case GT: case GTX: case EQ:
            case LE: case LEX: case GE: case GEX: case NE:
                return compareLongs(lhs, rhs, kind);
            case PLUS: case MINUS: case STAR: case SLASH: case MOD:
                return arithmeticLongs(lhs, rhs, kind);
            case LSHIFT: case LSHIFTX: case RSIGNEDSHIFT: case RSIGNEDSHIFTX:
            case RUNSIGNEDSHIFT: case RUNSIGNEDSHIFTX: case BIT_AND: case BIT_ANDX:
            case BIT_OR: case BIT_ORX: case XOR:
                return bitwiseLongs(lhs, rhs, kind);
            default:
                throw new InterpreterError("Unimplemented binary long operator");
        }
    }

	/**
		Compares two long values using the specified operator kind.
	*/
	static Boolean compareLongs(long lhs, long rhs, int kind)
	{
		switch(kind)
		{
			case LT: case LTX: return new Boolean(lhs < rhs);
			case GT: case GTX: return new Boolean(lhs > rhs);
			case EQ: return new Boolean(lhs == rhs);
			case LE: case LEX: return new Boolean(lhs <= rhs);
			case GE: case GEX: return new Boolean(lhs >= rhs);
			case NE: return new Boolean(lhs != rhs);
			default: throw new InterpreterError("Unimplemented long comparison operator");
		}
	}

	/**
		Performs arithmetic on two long values using the specified operator kind.
	*/
	static Long arithmeticLongs(long lhs, long rhs, int kind)
	{
		switch(kind)
		{
			case PLUS: return new Long(lhs + rhs);
			case MINUS: return new Long(lhs - rhs);
			case STAR: return new Long(lhs * rhs);
			case SLASH: return new Long(lhs / rhs);
			case MOD: return new Long(lhs % rhs);
			default: throw new InterpreterError("Unimplemented long arithmetic operator");
		}
	}

	/**
		Performs a bitwise operation on two long values using the specified operator kind.
	*/
	static Long bitwiseLongs(long lhs, long rhs, int kind)
	{
		switch(kind)
		{
			case LSHIFT: case LSHIFTX: return new Long(lhs << rhs);
			case RSIGNEDSHIFT: case RSIGNEDSHIFTX: return new Long(lhs >> rhs);
			case RUNSIGNEDSHIFT: case RUNSIGNEDSHIFTX: return new Long(lhs >>> rhs);
			case BIT_AND: case BIT_ANDX: return new Long(lhs & rhs);
			case BIT_OR: case BIT_ORX: return new Long(lhs | rhs);
			case XOR: return new Long(lhs ^ rhs);
			default: throw new InterpreterError("Unimplemented long bitwise operator");
		}
	}

    // returns Object covering both Integer and Boolean return types
    static Object intBinaryOperation(Integer I1, Integer I2, int kind)
    {
        int lhs = I1.intValue();
        int rhs = I2.intValue();

        switch(kind)
        {
            case LT: case LTX: case GT: case GTX: case EQ:
            case LE: case LEX: case GE: case GEX: case NE:
                return compareInts(lhs, rhs, kind);
            case PLUS: case MINUS: case STAR: case SLASH: case MOD:
                return arithmeticInts(lhs, rhs, kind);
            case LSHIFT: case LSHIFTX: case RSIGNEDSHIFT: case RSIGNEDSHIFTX:
            case RUNSIGNEDSHIFT: case RUNSIGNEDSHIFTX: case BIT_AND: case BIT_ANDX:
            case BIT_OR: case BIT_ORX: case XOR:
                return bitwiseInts(lhs, rhs, kind);
            default:
                throw new InterpreterError("Unimplemented binary integer operator");
        }
    }

	/**
		Compares two int values using the specified operator kind.
	*/
	static Boolean compareInts(int lhs, int rhs, int kind)
	{
		switch(kind)
		{
			case LT: case LTX: return new Boolean(lhs < rhs);
			case GT: case GTX: return new Boolean(lhs > rhs);
			case EQ: return new Boolean(lhs == rhs);
			case LE: case LEX: return new Boolean(lhs <= rhs);
			case GE: case GEX: return new Boolean(lhs >= rhs);
			case NE: return new Boolean(lhs != rhs);
			default: throw new InterpreterError("Unimplemented int comparison operator");
		}
	}

	/**
		Performs arithmetic on two int values using the specified operator kind.
	*/
	static Integer arithmeticInts(int lhs, int rhs, int kind)
	{
		switch(kind)
		{
			case PLUS: return new Integer(lhs + rhs);
			case MINUS: return new Integer(lhs - rhs);
			case STAR: return new Integer(lhs * rhs);
			case SLASH: return new Integer(lhs / rhs);
			case MOD: return new Integer(lhs % rhs);
			default: throw new InterpreterError("Unimplemented int arithmetic operator");
		}
	}

	/**
		Performs a bitwise operation on two int values using the specified operator kind.
	*/
	static Integer bitwiseInts(int lhs, int rhs, int kind)
	{
		switch(kind)
		{
			case LSHIFT: case LSHIFTX: return new Integer(lhs << rhs);
			case RSIGNEDSHIFT: case RSIGNEDSHIFTX: return new Integer(lhs >> rhs);
			case RUNSIGNEDSHIFT: case RUNSIGNEDSHIFTX: return new Integer(lhs >>> rhs);
			case BIT_AND: case BIT_ANDX: return new Integer(lhs & rhs);
			case BIT_OR: case BIT_ORX: return new Integer(lhs | rhs);
			case XOR: return new Integer(lhs ^ rhs);
			default: throw new InterpreterError("Unimplemented int bitwise operator");
		}
	}

    // returns Object covering both Double and Boolean return types
    static Object doubleBinaryOperation(Double D1, Double D2, int kind)
        throws EvalError
    {
        double lhs = D1.doubleValue();
        double rhs = D2.doubleValue();

        switch(kind)
        {
            case LT: case LTX: case GT: case GTX: case EQ:
            case LE: case LEX: case GE: case GEX: case NE:
                return compareDoubles(lhs, rhs, kind);
            case PLUS: case MINUS: case STAR: case SLASH: case MOD:
                return arithmeticDoubles(lhs, rhs, kind);
            case LSHIFT: case LSHIFTX: case RSIGNEDSHIFT: case RSIGNEDSHIFTX:
            case RUNSIGNEDSHIFT: case RUNSIGNEDSHIFTX:
                throw new EvalError("Can't shift doubles");
            default:
                throw new InterpreterError("Unimplemented binary double operator");
        }
    }

	/**
		Compares two double values using the specified operator kind.
	*/
	static Boolean compareDoubles(double lhs, double rhs, int kind)
	{
		switch(kind)
		{
			case LT: case LTX: return new Boolean(lhs < rhs);
			case GT: case GTX: return new Boolean(lhs > rhs);
			case EQ: return new Boolean(lhs == rhs);
			case LE: case LEX: return new Boolean(lhs <= rhs);
			case GE: case GEX: return new Boolean(lhs >= rhs);
			case NE: return new Boolean(lhs != rhs);
			default: throw new InterpreterError("Unimplemented double comparison operator");
		}
	}

	/**
		Performs arithmetic on two double values using the specified operator kind.
	*/
	static Double arithmeticDoubles(double lhs, double rhs, int kind)
	{
		switch(kind)
		{
			case PLUS: return new Double(lhs + rhs);
