	/**
		Performs arithmetic on two float values using the specified operator kind.
	*/
	static Float arithmeticFloats(float lhs, float rhs, int kind)
	{
		switch(kind)
		{
			case PLUS: return new Float(lhs + rhs);
			case MINUS: return new Float(lhs - rhs);
