private static AssignmentContext processObjectRhs(Object rhs, Class lhsType) throws EvalError {
    Class originalType = rhs.getClass();
    Class rhsType = originalType;
    if (lhsType.isPrimitive()) {
        if (originalType == Boolean.class) {
            rhs = new Primitive((Boolean)rhs);
            rhsType = Boolean.TYPE;
        } else if (originalType == Character.class) {
            rhs = new Primitive((Character)rhs);
            rhsType = Character.TYPE;
