/**
    Convert the RHS value to an assignable form when the LHS is a wrapper
    type and the RHS is a Primitive, or when the LHS is primitive and the
    RHS is a wrapper object.  Throws an EvalError if the types are
    incompatible.
*/
private static ConversionResult prepareAssignableRhs(
    Object rhs, Class lhsType) throws EvalError
{
    if (rhs instanceof Primitive)
    {
        Class originalType = ((Primitive)rhs).getType();
        if (lhsType.isPrimitive())
        {
            return new ConversionResult(rhs, originalType, originalType);
        }
        else
        {
            if (Boolean.class.isAssignableFrom(lhsType) ||
                Character.class.isAssignableFrom(lhsType) ||
                Number.class.isAssignableFrom(lhsType))
            {
                Object converted = ((Primitive)rhs).getValue();
                return new ConversionResult(
                    converted, converted.getClass(), originalType);
            }
            else
            {
                assignmentError(lhsType, originalType);
                return null; // unreachable
            }
        }
    }
    else
    {
        Class originalType = rhs.getClass();
        if (lhsType.isPrimitive())
        {
            if (originalType == Boolean.class)
            {
                Object converted = new Primitive((Boolean)rhs);
                return new ConversionResult(
                    converted, ((Primitive)converted).getType(), originalType);
            }
            else if (originalType == Character.class)
            {
                Object converted = new Primitive((Character)rhs);
                return new ConversionResult(
                    converted, ((Primitive)converted).getType(), originalType);
            }
            else if (Number.class.isAssignableFrom(originalType))
            {
                Object converted = new Primitive((Number)rhs);
                return new ConversionResult(
                    converted, ((Primitive)converted).getType(), originalType);
            }
            else
            {
                assignmentError(lhsType, originalType);
                return null; // unreachable
            }
        }
        else
        {
            return new ConversionResult(rhs, originalType, originalType);
        }
    }
}

