	public String name; 
    private NameSpace parent;
    private Hashtable variables;
    private Hashtable methods;
    private Hashtable importedClasses;
    private This thisReference;
    private Vector importedPackages;

	/** "import *;" operation has been performed */
	transient private static boolean superImport;

	/**
		Local class cache for classes resolved through this namespace using 
		getClass() (taking into account imports).  Only unqualified class names
		are cached here (those which might be imported).  Qualified names are 
		always absolute and are cached by BshClassManager.
	*/
    transient private Hashtable classCache;

	/**
		Default Primitive values for the Java primitive types, used when
		initializing a typed variable with a null value.
	*/
	private static final Hashtable primitiveDefaults = new Hashtable();
	static {
		primitiveDefaults.put(Boolean.TYPE, new Primitive(Boolean.FALSE));
		primitiveDefaults.put(Byte.TYPE, new Primitive((byte)0));
		primitiveDefaults.put(Short.TYPE, new Primitive((short)0));
		primitiveDefaults.put(Character.TYPE, new Primitive((char)0));
		primitiveDefaults.put(Integer.TYPE, new Primitive((int)0));
		primitiveDefaults.put(Long.TYPE, new Primitive(0L));
		primitiveDefaults.put(Float.TYPE, new Primitive(0.0f));
		primitiveDefaults.put(Double.TYPE, new Primitive(0.0d));
	}

	// End instance data

